class SunucuDavetView(discord.ui.View):
    """td!sunucular sayfasındaki sunuculara tek tıkla davet linki üretir (sadece bot sahibi).
    Davetler 10 dakika geçerli ve tek kullanımlıktır; sunucunun denetim kaydında botun adıyla görünür."""

    def __init__(self, sunucular):
        super().__init__(timeout=300)
        self.sunucular = list(sunucular)
        sec = discord.ui.Select(
            placeholder="🔗 Katılmak istediğin sunucuyu seç...",
            options=[discord.SelectOption(label=g.name[:100] or "?", value=str(g.id),
                                          description=f"{g.member_count or '?'} üye • ID {g.id}"[:100])
                     for g in self.sunucular[:25]])
        sec.callback = self.sec_callback
        self.add_item(sec)

    async def interaction_check(self, it):
        if await bot.is_owner(it.user):
            return True
        await it.response.send_message("❌ Bu menü sadece bot sahibine ait.", ephemeral=True)
        return False

    @staticmethod
    async def davet_olustur(g):
        """(link, hata) döner. Botun davet oluşturabildiği ilk kanalda 10 dk'lık, tek kullanımlık davet açar."""
        me = g.me or g.get_member(bot.user.id)
        adaylar = []
        if g.system_channel is not None:
            adaylar.append(g.system_channel)
        adaylar += [c for c in g.text_channels if c not in adaylar]
        adaylar += list(g.voice_channels)
        for k in adaylar:
            if me is None or not k.permissions_for(me).create_instant_invite:
                continue
            try:
                d = await k.create_invite(max_age=600, max_uses=1, unique=True,
                                          reason="Bot sahibi katılmak için davet istedi")
                return d.url, None
            except discord.HTTPException:
                continue
        return None, "Davet oluşturma (Create Invite) yetkim yok"

    async def sec_callback(self, it):
        g = bot.get_guild(int(it.data["values"][0]))
        await it.response.defer(ephemeral=True, thinking=True)
        if g is None:
            return await it.followup.send("❌ Bot artık bu sunucuda değil.", ephemeral=True)
        link, hata = await self.davet_olustur(g)
        ad = discord.utils.escape_markdown(g.name)
        if link:
            await it.followup.send(f"✅ **{ad}**\n{link}\n_10 dakika geçerli, tek kullanımlık._", ephemeral=True)
        else:
            await it.followup.send(f"❌ **{ad}**: {hata}", ephemeral=True)

    @discord.ui.button(label="Sayfadakilerin hepsine katıl", emoji="🚪", style=discord.ButtonStyle.success, row=1)
    async def hepsi(self, it, button):
        await it.response.defer(ephemeral=True, thinking=True)
        satirlar = []
        for g in self.sunucular:
            link, hata = await self.davet_olustur(g)
            ad = discord.utils.escape_markdown(g.name)[:60]
            satirlar.append(f"✅ **{ad}** → {link}" if link else f"❌ **{ad}**: {hata}")
            await asyncio.sleep(0.6)          # Discord hız sınırına takılmamak için
        parca, mesajlar = "", []
        for satir in satirlar:
            if len(parca) + len(satir) + 1 > 1900:
                mesajlar.append(parca)
                parca = ""
            parca += satir + "\n"
        if parca:
            mesajlar.append(parca)
        for m in mesajlar or ["Bu sayfada sunucu yok."]:
            await it.followup.send(m, ephemeral=True, suppress_embeds=True)
        await it.followup.send("_Davetler 10 dakika geçerli ve tek kullanımlık._", ephemeral=True)


@bot.hybrid_command(name="sunucular", aliases=["sunucularim", "guilds", "serverlist"], usage="[sayfa]")
async def sunucular(ctx, sayfa: int = 1):
    """🌐 Botun bulunduğu sunucuları listele (sadece bot sahibi)"""
    if not await bot.is_owner(ctx.author):
        return await ctx.send("❌ Bu komutu sadece bot sahibi kullanabilir.", ephemeral=True)
    liste = sorted(bot.guilds, key=lambda x: x.member_count or 0, reverse=True)
    if not liste:
        return await ctx.send("Bot hiçbir sunucuda değil.", ephemeral=True)
    boyut = 15
    toplam_sayfa = max(1, (len(liste) + boyut - 1) // boyut)
    sayfa = min(max(sayfa, 1), toplam_sayfa)
    baslangic = (sayfa - 1) * boyut
    satirlar = []
    for i, g in enumerate(liste[baslangic:baslangic + boyut], start=baslangic + 1):
        sahip = f"<@{g.owner_id}>" if g.owner_id else "?"
        satirlar.append(f"**{i}. {discord.utils.escape_markdown(g.name)}**\n"
                        f"　ID: `{g.id}` • 👥 {g.member_count or '?'} • 👑 {sahip}")
    toplam_uye = sum(g.member_count or 0 for g in liste)
    embed = discord.Embed(
        title=f"🌐 Bot {len(liste)} sunucuda",
        description="\n".join(satirlar)[:4000],
        color=discord.Color.blurple(),
    )
    embed.set_footer(text=f"Sayfa {sayfa}/{toplam_sayfa} • toplam {toplam_uye} üye"
                          + (f" • td!sunucular {sayfa + 1}" if sayfa < toplam_sayfa else ""))
    embed.add_field(name="🔗 Katılmak için", value="Aşağıdaki menüden sunucuyu seç ya da sayfadakilerin hepsi için yeşil butona bas.", inline=False)
    await ctx.send(embed=embed, view=SunucuDavetView(liste[baslangic:baslangic + boyut]), allowed_mentions=NO_PING, ephemeral=True)


BASLANGIC_ZAMANI = time.time()


def _gizle(metin):
    """Konsola/loga giden hata metninden token ve API anahtarlarını siler."""
    import re as _re
    metin = str(metin)
    for ad in ("DISCORD_TOKEN", "GEMINI_KEY", "GEMINI_PREMIUM_KEY", "YT_PROXY", "YT_COOKIES"):
        deger = os.getenv(ad, "").strip()
        if len(deger) >= 6:
            metin = metin.replace(deger, f"<{ad}>")
    metin = _re.sub(r"(?i)(key|token|api_key|apikey|password|secret)=([^&\s'\"]+)", r"\1=<gizli>", metin)
    return _re.sub(r"[A-Za-z0-9_\-]{24}\.[A-Za-z0-9_\-]{6}\.[A-Za-z0-9_\-]{27,}", "<discord-token>", metin)


def surum_embed(guncelleme=False, eski=None):
    """td!surum ve otomatik güncelleme duyurusu için sürüm kartı."""
    ilk = DEGISIKLIKLER.split("\n")[0]
    govde = ilk.split(":", 1)[1].strip() if ":" in ilk else ilk
    if " • " in govde:
        maddeler = [m.strip(" •") for m in govde.split(" • ") if m.strip(" •")]
        metin = "\n".join(f"• {m}" for m in maddeler)
    else:
        metin = govde
    e = discord.Embed(title=(f"✅ Güncellendim! → THEDLAX v{SURUM}" if guncelleme else f"🤖 THEDLAX v{SURUM}"),
                      description=metin[:4000], color=discord.Color.green())
    e.add_field(name="🏷️ Sürüm", value=f"`v{SURUM}`" + (f" (önceki: `v{eski}`)" if eski and eski != SURUM else ""), inline=True)
    e.add_field(name="🌐 Sunucu", value=str(len(bot.guilds)), inline=True)
    sa, dk = divmod(int(time.time() - BASLANGIC_ZAMANI) // 60, 60)
    e.add_field(name="⏱️ Çalışma", value=f"{sa} sa {dk} dk", inline=True)
    yuklu = sum(1 for v in MODUL_DURUM.values() if str(v).startswith("✅"))
    e.add_field(name="🧩 Modül", value=f"{yuklu}/{len(MODUL_DURUM)}", inline=True)
    e.set_footer(text="Tüm komutlar için: td!yardim")
    return e


