        eko_ekle(ctx.guild.id, uye.id, miktar)
        yeni = eko(ctx.guild.id, uye.id)["bakiye"]
        await ctx.send(f"🖨️ {uye.mention} cüzdanına **{para(miktar)} 🪙** basıldı. Yeni bakiye: **{para(yeni)} 🪙**",
                       allowed_mentions=NO_PING)


