def miktar_coz(metin, hepsi):
    if metin.lower() in ("hepsi", "all", "tum", "tüm"):
        return hepsi
    try:
        return int(metin.replace(".", "").replace(",", ""))
    except ValueError:
        return None


def banka_gecis():
    """v4.4: sunucu bazlı bankaları tek global bankada birleştirir (para toplanır)."""
    bk = veri["banka"]
    if bk.get("_global_gecis"):
        return
    hedef = bk.setdefault("global", {})
    for gid in [k for k in list(bk) if k not in ("global", "_global_gecis")]:
        kayitlar = bk.pop(gid)
        if not isinstance(kayitlar, dict):
            continue
        for uid, b in kayitlar.items():
            if not isinstance(b, dict):
                continue
            h = hedef.setdefault(uid, {"para": 0, "son": b.get("son", time.time())})
            h["para"] = min(int(h.get("para", 0)) + int(b.get("para", 0)), BANKA_TAVAN)
            h["son"] = max(h.get("son", 0), b.get("son", 0))
    bk["_global_gecis"] = True
    isaretle18()


def banka_kayit(gid, uid):
    """Bankadaki hesabı verir (tüm sunucularda ortak), birikmiş günlük faizi işler."""
    banka_gecis()
    b = veri["banka"].setdefault("global", {}).setdefault(str(uid), {"para": 0, "son": time.time()})
    if b["para"] <= 0:
        b["son"] = time.time()
        return b
    gun = int((time.time() - b["son"]) // 86400)
    if gun > 0:
        faiz = int(b["para"] * BANKA_FAIZ * min(gun, BANKA_MAX_GUN))
        b["para"] = min(b["para"] + faiz, BANKA_TAVAN)
        b["son"] += gun * 86400
        isaretle18()
    return b


