def quiz_metin(soru, secenekler, dogru=None, ekstra=None, bitis=None):
    """v2.0: panel yok, normal yazı. Soru açılırken @everyone etiketler."""
    satirlar = []
    for i, sec in enumerate(secenekler):
        isaret = "✅ " if dogru is not None and i == dogru else ""
        satirlar.append(f"**{HARFLER[i]})** {isaret}{sec}")
    baslik = "@here 🧠 **Günün Sorusu**" if dogru is None else "🧠 **Günün Sorusu — Sonuç**"
    parcalar = [baslik, f"**{soru}**\n\n" + "\n".join(satirlar)]
    if ekstra:
        parcalar.append(f"🏁 **Sonuç**\n{ekstra[:1000]}")
    if bitis:
        parcalar.append(f"⏰ Kapanış: <t:{int(bitis)}:R>\n"
                        "_Aşağıdaki **✍️ Cevapla** butonuna bas, açılan kutuya şıkkı yaz (A, B, C ya da D). Doğru mu yanlış mı hemen söylenir. Tek hakkın var, tam cevap soru kapanınca açıklanır._")
    return "\n\n".join(parcalar)[:2000]


async def quiz_cevap_isle(interaction, q, k):
    """Şıkkı (0-3) değerlendirir, ödülü verir, sonucu sadece cevaplayan kişiye gösterir."""
    uid = str(interaction.user.id)
    q["cevap"][uid] = k
    q.setdefault("odul", [])
    isaretle18()
    dogru_mu = k == q["dogru"]
    await interaction.response.send_message("🤔 Cevabın kontrol ediliyor... ▰▱▱", ephemeral=True)
    await asyncio.sleep(0.6)
    await interaction.edit_original_response(content="🤔 Cevabın kontrol ediliyor... ▰▰▱")
    await asyncio.sleep(0.6)
    toplam = len(q["cevap"])
    dogrular = sum(1 for x in q["cevap"].values() if x == q["dogru"])
    oran = round(dogrular * 100 / toplam) if toplam else 0
    if dogru_mu:
        if interaction.user.id not in q["odul"] and interaction.guild is not None:
            q["odul"].append(interaction.user.id)
            eko_ekle(interaction.guild.id, interaction.user.id, QUIZ_PARA)
            await xp_ekle(interaction.guild, interaction.user, QUIZ_XP, duyur=False)
            __import__("sys").modules.get("v25") and __import__("sys").modules["v25"].gorev_say(interaction.guild.id, interaction.user.id, "quiz")
        sonuc = f"✅ **DOĞRU!** 🎉 +{QUIZ_PARA} 🪙 +{QUIZ_XP} XP kazandın."
    else:
        sonuc = "❌ **YANLIŞ!** 😢 Bir dahaki sefere!"
    if toplam > 1:
        karsilastir = f"\n👥 Seninle birlikte **{toplam}** kişi cevapladı, şu an **%{oran}** doğru bildi."
    else:
        karsilastir = "\n👥 İlk cevaplayan sensin!"
    await interaction.edit_original_response(
        content=sonuc + karsilastir + f"\n⏰ Tam cevap <t:{int(q['bitis'])}:R> açıklanacak.")


class QuizModal(discord.ui.Modal, title="🧠 Günün Sorusu"):
    """Cevapla butonuna basınca açılan yazı kutusu."""

    def __init__(self, mid, secenekler):
        super().__init__(timeout=600)
        self.mid = str(mid)
        ipucu = "   ".join(f"{HARFLER[i]}) {sec}" for i, sec in enumerate(secenekler))
        self.kutu = discord.ui.TextInput(
            label="Cevabın (A, B, C ya da D)", placeholder=ipucu[:100] or "A, B, C ya da D",
            min_length=1, max_length=60, required=True)
        self.add_item(self.kutu)

    async def on_submit(self, interaction):
        q = veri["quiz"].get(self.mid)
        if not q or q["bitti"] or q["bitis"] <= time.time():
            return await interaction.response.send_message("⌛ Bu soru kapandı.", ephemeral=True)
        uid = str(interaction.user.id)
        if uid in q["cevap"]:
            return await interaction.response.send_message(
                f"Bu soruyu zaten cevapladın (**{HARFLER[q['cevap'][uid]]}**). Tek hakkın vardı 🙂", ephemeral=True)
        k = cevap_coz(self.kutu.value, q["sec"])
        if k is None:
            return await interaction.response.send_message(
                "❓ Cevabını anlayamadım. **A, B, C ya da D** yaz (ya da şıkkın kendisini). "
                "Butona tekrar basıp dene, hakkın gitmedi.", ephemeral=True)
        await quiz_cevap_isle(interaction, q, k)


class QuizCevapButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td18:quizcevap"):
    def __init__(self):
        super().__init__(discord.ui.Button(
            label="Cevapla", emoji="✍️", style=discord.ButtonStyle.primary, custom_id="td18:quizcevap"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls()

    async def callback(self, interaction):
        q = veri["quiz"].get(str(interaction.message.id))
        if not q or q["bitti"] or q["bitis"] <= time.time():
            return await interaction.response.send_message("⌛ Bu soru kapandı.", ephemeral=True)
        uid = str(interaction.user.id)
        if uid in q["cevap"]:
            return await interaction.response.send_message(
                f"Bu soruyu zaten cevapladın (**{HARFLER[q['cevap'][uid]]}**). Sonuç soru kapanınca açıklanacak.", ephemeral=True)
        await interaction.response.send_modal(QuizModal(interaction.message.id, q["sec"]))


def quiz_gorunum():
    v = discord.ui.View(timeout=None)
    v.add_item(QuizCevapButon())
    return v


