VIP_UYARI_SURE = 86400       # bitmeye kaç saniye kala DM ile haber verilsin

CIZ_BEKLEME = 30             # ciz: kişi başı bekleme (saniye)
CIZ_MAX_HARF = 500           # tarif en fazla kaç karakter
