class V20(commands.Cog):
    def __init__(self, bot, g):
        self.bot = bot
        self.g = g
        self.gorev = None
        self.ciz_son = {}

    def cog_unload(self):
        if self.gorev is not None:
            self.gorev.cancel()

    @staticmethod
    def vip_rol(guild):
        rid = veri["sunucu"].get(str(guild.id), {}).get("rol")
        return guild.get_role(rid) if rid else None

    @staticmethod
    async def kisisel_sil(guild, uid):
        rid = veri["kisisel"].get(str(guild.id), {}).pop(str(uid), None)
        if rid is None:
            return
        isaretle20()
        rol = guild.get_role(rid)
        if rol is not None:
            try:
                await rol.delete(reason="PREMIUM bitti, kişisel rol silindi")
            except discord.HTTPException:
                pass

    # ================= 👑 Komutlar =================
    @commands.hybrid_command(name="premiumkur", usage="[@rol]")
    @commands.has_permissions(manage_guild=True)
    @commands.bot_has_permissions(manage_roles=True)
    @commands.guild_only()
    async def premiumkur(self, ctx, rol: discord.Role = None):
        """PREMIUM rolünü ayarla (rol yazmazsan 👑 PREMIUM rolü açılır)"""
        await ctx.defer()
        if rol is None:
            try:
                rol = await ctx.guild.create_role(
                    name=VIP_ROL_ADI, colour=discord.Colour.gold(), hoist=True,
                    reason=f"{ctx.author} PREMIUM rolü kurdu")
            except discord.HTTPException:
                return await ctx.send("❌ Rol oluşturulamadı. Botun **Rolleri Yönet** yetkisi var mı?")
        else:
            if rol.managed or rol.is_default() or rol >= ctx.guild.me.top_role:
                return await ctx.send("❌ Bu rolü veremem (rolüm onun altında kalıyor ya da özel bir rol).")
            if riskli_rol(rol):
                return await ctx.send("❌ Yetkili bir rol PREMIUM rolü olamaz.")
            if ctx.author.id != ctx.guild.owner_id and rol >= ctx.author.top_role:
                return await ctx.send("❌ Bu rol senin rolünle aynı ya da senden yüksek.")
        veri["sunucu"].setdefault(str(ctx.guild.id), {})["rol"] = rol.id
        isaretle20()
        await ctx.send(
            f"✅ PREMIUM rolü {rol.mention} olarak ayarlandı.\n"
            f"PREMIUM vermek için: `td!premiumver @kişi [gün]`", allowed_mentions=NO_PING)

    @commands.hybrid_command(name="premiumver", aliases=["premiumekle"], usage="@kişi [gün] [kademe 1-3]")
    @commands.has_permissions(manage_roles=True)
    @commands.bot_has_permissions(manage_roles=True)
    @commands.guild_only()
    async def premiumver(self, ctx, uye: discord.Member, gun: int = 0, kademe: int = 1):
        """Birine PREMIUM ver: gün (0=kalıcı) ve kademe (1=PREMIUM, 2=PREMIUM+, 3=PREMIUM MAX)"""
        await ctx.defer()
        if uye.bot:
            return await ctx.send("🤖 Botlara PREMIUM verilmez.")
        rol = self.vip_rol(ctx.guild)
        if rol is None:
            return await ctx.send("❌ PREMIUM rolü ayarlı değil. Önce `td!premiumkur` yaz.")
        if not 0 <= gun <= VIP_MAX_GUN:
            return await ctx.send(f"❌ Gün 0 (kalıcı) ile {VIP_MAX_GUN} arasında olmalı.")
        if kademe not in KADEMELER:
            return await ctx.send("❌ Kademe 1 (PREMIUM), 2 (PREMIUM+) ya da 3 (PREMIUM MAX) olmalı.")
        if rol >= ctx.guild.me.top_role:
            return await ctx.send("❌ PREMIUM rolü benim rolümden yüksek, veremiyorum.")
        kayit = vip_kayit(ctx.guild.id)
        uid = str(uye.id)
        simdi = time.time()
        onceki = kayit.get(uid)
        if onceki == 0 and gun > 0:
            return await ctx.send(f"ℹ️ **{uye.display_name}** zaten kalıcı PREMIUM.", allowed_mentions=NO_PING)
        if gun == 0:
            bitis = 0
        else:
            temel = onceki if (onceki and onceki > simdi) else simdi   # süreli PREMIUM'e gün eklenir
            bitis = temel + gun * 86400
        try:
            if rol not in uye.roles:
                await uye.add_roles(rol, reason=f"{ctx.author} PREMIUM verdi")
        except discord.HTTPException:
            return await ctx.send("❌ Rol verilemedi (rol sırası ya da yetki sorunu).")
        kayit[uid] = bitis
        veri["kademe"].setdefault(str(ctx.guild.id), {})[uid] = kademe
        isaretle20()
        await ctx.send(f"{KADEMELER[kademe]['emoji']} {uye.mention} artık **{KADEMELER[kademe]['ad']}**! "
                       f"Süre: {bitis_yaz(bitis)}", allowed_mentions=NO_PING)
        try:
            await uye.send(
                f"{KADEMELER[kademe]['emoji']} **{ctx.guild.name}** sunucusunda **{KADEMELER[kademe]['ad']}** oldun! "
                f"Süre: {bitis_yaz(bitis)}\n"
                "Avantajların için sunucuda `td!premium` yaz. Günlük bonus: `td!premiumgunluk`, resim çizmek için: `td!ciz <tarif>`.")
        except discord.HTTPException:
            pass                                  # DM'leri kapalıysa sorun değil

    @commands.hybrid_command(name="premiumal", aliases=["premiumsil"], usage="@kişi")
    @commands.has_permissions(manage_roles=True)
    @commands.bot_has_permissions(manage_roles=True)
    @commands.guild_only()
    async def premiumal(self, ctx, uye: discord.Member):
        """Birinin PREMIUM'liğini al"""
        await ctx.defer()
        rol = self.vip_rol(ctx.guild)
        kayitli = vip_kayit(ctx.guild.id).pop(str(uye.id), None) is not None
        rolde = rol is not None and rol in uye.roles
        if not kayitli and not rolde:
            return await ctx.send("❌ Bu kişi PREMIUM değil.")
        veri["kademe"].get(str(ctx.guild.id), {}).pop(str(uye.id), None)
        isaretle20()
        await self.kisisel_sil(ctx.guild, uye.id)
        if rolde:
            try:
                await uye.remove_roles(rol, reason=f"{ctx.author} PREMIUM'liği aldı")
            except discord.HTTPException:
                return await ctx.send("❌ Rol alınamadı (rol sırası ya da yetki sorunu).")
        await ctx.send(f"✅ {uye.mention} kişisinin PREMIUM'liği alındı.", allowed_mentions=NO_PING)

    @commands.hybrid_command(name="premiumlistesi", aliases=["premiumlist", "premiumlar"])
    @commands.guild_only()
    async def premiumlistesi(self, ctx):
        """PREMIUM üyeleri listele"""
        simdi = time.time()
        liste = [(u, b) for u, b in vip_kayit(ctx.guild.id).items() if b == 0 or b > simdi]
        if not liste:
            return await ctx.send("📭 Sunucuda PREMIUM yok.")
        liste.sort(key=lambda x: (x[1] == 0, x[1]))
        satirlar = [f"{kademe_ad(kademe_al(ctx.guild.id, u))} <@{u}> — {bitis_yaz(b)}" for u, b in liste[:25]]
        e = discord.Embed(title=f"👑 PREMIUM listesi ({len(liste)})", description="\n".join(satirlar),
                          color=discord.Color.gold())
        await ctx.send(embed=e, allowed_mentions=NO_PING)

    @commands.hybrid_command(name="premium", usage="[@kişi]")
    @commands.guild_only()
    async def premium(self, ctx, uye: discord.Member = None):
        """PREMIUM durumunu ve avantajları göster"""
        uye = uye or ctx.author
        _g = veri["genel"].get(str(uye.id))
