def nadirlik(deger):
    if deger >= 400:
        return "🌟 EFSANE"
    if deger >= 100:
        return "✨ Nadir"
    if deger >= 40:
        return "🔹 Güzel"
    return "▫️ Sıradan"


def meslek_bul(girdi):
    a = tr_ascii(girdi)
    for ad in MESLEKLER:
        if tr_ascii(ad) == a:
            return ad
    for ad in MESLEKLER:
        if tr_ascii(ad).startswith(a) and a:
            return ad
    return None


