_onbellek = {}


async def onbellekli(anahtar, sure, getir):
    simdi = time.time()
    if anahtar in _onbellek and simdi - _onbellek[anahtar][0] < sure:
        return _onbellek[anahtar][1]
    sonuc = await getir()
    _onbellek[anahtar] = (simdi, sonuc)
    return sonuc


