    @commands.hybrid_command(name="kayit")
    @commands.guild_only()
    async def kayit(self, ctx):
        """📝 Kayıt sorularını baştan başlat"""
        a = ayar(ctx.guild.id)
        kanal = ctx.guild.get_channel(a["kanal"] or 0)
        kayitli = ctx.guild.get_role(a["kayitli"] or 0)
        if not a["aktif"] or kanal is None:
            return await ctx.send("❌ Kayıt sistemi şu an kapalı.")
        if kayitli is not None and kayitli in ctx.author.roles:
            return await ctx.send("✅ Zaten kayıtlısın.")
        if f"{ctx.guild.id}:{ctx.author.id}" in veri["bekleyen"]:
            return await ctx.send("⏳ Başvurun zaten yetkililerde, onay bekliyor.")
        if a.get("buton"):
            return await ctx.send(f"✅ Kayıt için {kanal.mention} kanalındaki **Doğrula** butonuna bas.")
        await self.oturum_baslat(ctx.author, kanal)
        await ctx.send(f"📝 Sorular {kanal.mention} kanalında başladı.")

    # ------------------------------------------------------------------ doğrula butonu paneli
    async def panel_gonder(self, guild, kanal):
        """Kayıt kanalına 'Doğrula' butonlu paneli koyar ve butonlu modu açar."""
        a = ayar(guild.id)
        e = discord.Embed(
            title="✅ Kayıt / Doğrulama",
            description=("Sunucuya girmek için aşağıdaki **Doğrula** butonuna bas.\n\n"
                         "📝 Birkaç soruya cevap vereceksin\n"
                         "👮 Cevapların yetkililere ve sunucu sahibine gider\n"
                         "🎉 Onaylanınca tüm kanallar açılır, sana DM ile haber veririm"),
            color=0x57F287)
        v = discord.ui.View(timeout=None)
        v.add_item(KayitBaslaButon())
        msg = await kanal.send(embed=e, view=v)
        eski = a.get("panel")
        if eski and eski[1] != msg.id:
            try:
                ek = guild.get_channel(eski[0])
                if ek is not None:
                    await ek.get_partial_message(eski[1]).delete()
            except discord.HTTPException:
                pass
        a["panel"] = [kanal.id, msg.id]
        a["buton"] = True
        kaydet()
        return msg

    async def buton_basla(self, interaction):
        guild, uye = interaction.guild, interaction.user
        if guild is None or not isinstance(uye, discord.Member):
            return await interaction.response.send_message("❌ Bu buton sadece sunucuda çalışır.", ephemeral=True)
        a = ayar(guild.id)
        if not a["aktif"]:
            return await interaction.response.send_message("❌ Kayıt sistemi şu an kapalı.", ephemeral=True)
        if self.yetkili_mi(uye):
            return await interaction.response.send_message("👮 Sen yetkilisin, kayıt olmana gerek yok.", ephemeral=True)
        kayitli = guild.get_role(a["kayitli"] or 0)
        if kayitli is not None and kayitli in uye.roles:
            return await interaction.response.send_message("✅ Zaten kayıtlısın.", ephemeral=True)
        anahtar = f"{guild.id}:{uye.id}"
        if anahtar in veri["bekleyen"]:
            return await interaction.response.send_message("⏳ Başvurun zaten yetkililerde, onay bekliyor.", ephemeral=True)
        bekle = RED_BEKLEME - (time.time() - veri["ret"].get(anahtar, 0))
        if bekle > 0:
            return await interaction.response.send_message(
                f"⏳ Yeniden başvurmak için **{int(bekle) // 60 + 1} dakika** beklemelisin.", ephemeral=True)
        sorular = list(a["sorular"])
        if not sorular:
            return await interaction.response.send_message("❌ Kayıt soruları ayarlanmamış, bir yetkiliye haber ver.", ephemeral=True)
        await interaction.response.send_modal(KayitModal(self, sorular, 0, []))

    async def modal_bitir(self, interaction, sorular, cevaplar):
        guild, uye = interaction.guild, interaction.user
        anahtar = f"{guild.id}:{uye.id}"
        if anahtar in veri["bekleyen"]:
            return await interaction.response.send_message("⏳ Başvurun zaten yetkililerde.", ephemeral=True)
        await interaction.response.defer(ephemeral=True, thinking=True)      # DM gönderimi 3 saniyeden uzun sürebilir
        self.oturum.pop((guild.id, uye.id), None)
        kayit = {"gid": guild.id, "uid": uye.id, "sorular": sorular, "cevaplar": cevaplar,
                 "zaman": time.time(), "dmler": [], "log_mesaj": None}
        veri["bekleyen"][anahtar] = kayit
        kaydet()
        ulasti = await self.yetkililere_gonder(guild, kayit)
        if ulasti == 0:
            veri["bekleyen"].pop(anahtar, None)               # kimseye ulaşmadıysa başvuru takılı kalmasın, tekrar deneyebilsin
            kaydet()
            return await interaction.followup.send(
                "⚠️ Başvurun yetkililere ulaştırılamadı. Bir yetkiliye haber ver, sonra **Doğrula** butonuna tekrar bas.", ephemeral=True)
        await interaction.followup.send(
            "✅ Cevapların **yetkililere iletildi**. Onaylanınca sunucunun tüm kanalları açılacak, "
            "sana DM ile haber vereceğim. ⏳ (DM'lerin açık olsun)", ephemeral=True)

    @commands.hybrid_command(name="kayitpanel", usage="[#kanal]")
    @commands.has_permissions(administrator=True)
    @commands.guild_only()
    async def kayitpanel(self, ctx, kanal: discord.TextChannel = None):
        """✅ Kayıt kanalına 'Doğrula' butonlu paneli koyar (butona basınca sorular kutuda açılır)"""
        a = ayar(ctx.guild.id)
        kanal = kanal or ctx.guild.get_channel(a["kanal"] or 0)
        if kanal is None:
            return await ctx.send("❌ Önce `td!kayitkur` ile kayıt sistemini kur ya da `td!kayitpanel #kanal` yaz.")
        try:
            await self.panel_gonder(ctx.guild, kanal)
        except discord.HTTPException:
            return await ctx.send("❌ Panel gönderilemedi. Botun o kanalda **Mesaj Gönder** ve **Bağlantı Yerleştir** yetkisi var mı?")
        await ctx.send(f"✅ Doğrula paneli {kanal.mention} kanalına konuldu. Başvurular yetkililere ve sunucu sahibine DM gelir, "
                       f"oradan **Onayla / Reddet** butonuyla karar verilir.")

    @commands.hybrid_command(name="kayitpanelkapat")
    @commands.has_permissions(administrator=True)
    @commands.guild_only()
    async def kayitpanelkapat(self, ctx):
        """🔕 Butonlu kaydı kapatır, eski sohbetle soru sorma yöntemine döner"""
        a = ayar(ctx.guild.id)
        eski = a.get("panel")
        a["buton"] = False
        a["panel"] = None
        kaydet()
        if eski:
            try:
                ek = ctx.guild.get_channel(eski[0])
                if ek is not None:
                    await ek.get_partial_message(eski[1]).delete()
            except discord.HTTPException:
                pass
        await ctx.send("✅ Butonlu kayıt kapatıldı, yeni üyelere sorular yine sohbetle sorulacak.")

    async def manuel_karar(self, ctx, uye, onay):
        kayit = veri["bekleyen"].get(f"{ctx.guild.id}:{uye.id}")
        if kayit is None:
            return await ctx.send("❌ Bu kişinin bekleyen başvurusu yok.")
        if not self.yetkili_mi(ctx.author):
            return await ctx.send("❌ Yetkin yok.")
        a = ayar(ctx.guild.id)
        if onay:
            kayitli, kayitsiz = ctx.guild.get_role(a["kayitli"] or 0), ctx.guild.get_role(a["kayitsiz"] or 0)
            try:
                if kayitli is not None:
                    await uye.add_roles(kayitli)
                if kayitsiz is not None and kayitsiz in uye.roles:
                    await uye.remove_roles(kayitsiz)
            except discord.HTTPException:
                return await ctx.send("⚠️ Rolü veremedim, botun rolü Kayıtlı/Kayıtsız rollerinin üstünde olmalı.")
            durum, renk = f"✅ **{ctx.author.display_name}** onayladı", 0x57F287
        else:
            durum, renk = f"❌ **{ctx.author.display_name}** reddetti", 0xED4245
            veri["ret"][f"{ctx.guild.id}:{uye.id}"] = time.time()
        veri["bekleyen"].pop(f"{ctx.guild.id}:{uye.id}", None)
        kaydet()
        await self.diger_mesajlari_guncelle(ctx.guild, kayit, self.basvuru_embed(ctx.guild, kayit, durum, renk), None)
        try:
            await uye.send(f"🎉 **{ctx.guild.name}** kaydın onaylandı!" if onay else f"😕 **{ctx.guild.name}** kayıt başvurun reddedildi.")
        except discord.HTTPException:
            pass
        await ctx.send(f"{durum} → {uye.mention}", allowed_mentions=NO_PING)

    @commands.hybrid_command(name="kayitonay", usage="@kişi")
    @commands.guild_only()
    async def kayitonay(self, ctx, uye: discord.Member):
        """✅ Bekleyen başvuruyu komutla onayla (DM butonu çalışmazsa)"""
        await self.manuel_karar(ctx, uye, True)

    @commands.hybrid_command(name="kayitred", usage="@kişi")
    @commands.guild_only()
    async def kayitred(self, ctx, uye: discord.Member):
        """❌ Bekleyen başvuruyu komutla reddet"""
        await self.manuel_karar(ctx, uye, False)


