class AcButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td32:ac:(?P<tur>destek|hata|oneri)"):
    def __init__(self, tur):
        t = TURLER[tur]
        super().__init__(discord.ui.Button(label=t["buton"], emoji=t["emoji"], style=t["stil"], custom_id=f"td32:ac:{tur}"))
        self.tur = tur

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["tur"])

    async def callback(self, interaction):
        await cok_guvenli(interaction, "ac", self.tur)


class KapatButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td32:kapat"):
    def __init__(self):
        super().__init__(discord.ui.Button(label="Kapat", emoji="🔒", style=discord.ButtonStyle.secondary, custom_id="td32:kapat"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls()

    async def callback(self, interaction):
        await cok_guvenli(interaction, "kapat")


class DurumButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td32:durum:(?P<d>ok|no|ink)"):
    ETIKET = {"ok": ("Çözüldü", "✅", discord.ButtonStyle.success),
              "no": ("Geçersiz", "🚫", discord.ButtonStyle.secondary),
              "ink": ("İnceleniyor", "🛠️", discord.ButtonStyle.primary)}

    def __init__(self, d):
        etiket, emoji, stil = self.ETIKET[d]
        super().__init__(discord.ui.Button(label=etiket, emoji=emoji, style=stil, custom_id=f"td32:durum:{d}"))
        self.d = d

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["d"])

    async def callback(self, interaction):
        await cok_guvenli(interaction, "durum", self.d)


class UstlenButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td32:ustlen"):
    def __init__(self):
        super().__init__(discord.ui.Button(label="Üstlen", emoji="🙋", style=discord.ButtonStyle.success, custom_id="td32:ustlen"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls()

    async def callback(self, interaction):
        await cok_guvenli(interaction, "ustlen")


class OneriDurumButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td32:od:(?P<d>kabul|dusun|red)"):
    ETIKET = {"kabul": ("Kabul", "✅", discord.ButtonStyle.secondary),
              "dusun": ("Düşünülüyor", "⏳", discord.ButtonStyle.secondary),
              "red": ("Red", "❌", discord.ButtonStyle.secondary)}

    def __init__(self, d):
        etiket, emoji, stil = self.ETIKET[d]
        super().__init__(discord.ui.Button(label=etiket, emoji=emoji, style=stil, custom_id=f"td32:od:{d}", row=1))
        self.d = d

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["d"])

    async def callback(self, interaction):
        await cok_guvenli(interaction, "od", self.d)


class OyButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td32:oy:(?P<y>up|down)"):
    def __init__(self, y, sayi=0):
        super().__init__(discord.ui.Button(
            label=str(sayi), emoji="👍" if y == "up" else "👎",
            style=discord.ButtonStyle.success if y == "up" else discord.ButtonStyle.danger, custom_id=f"td32:oy:{y}"))
        self.y = y

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["y"])

    async def callback(self, interaction):
        await cok_guvenli(interaction, "oy", self.y)


async def cok_guvenli(interaction, islem, *arg):
    """Buton hatası olursa kullanıcı 'etkileşim başarısız' görmesin."""
    cog = interaction.client.get_cog("V32")
    try:
        if cog is None:
            return await interaction.response.send_message("❌ Bu sistem şu an çalışmıyor.", ephemeral=True)
        await getattr(cog, "buton_" + islem)(interaction, *arg)
    except Exception:
        traceback.print_exc()
        mesaj = "❌ Bir hata oldu, tekrar dene. Sürerse bir yetkiliye haber ver."
        try:
            if interaction.response.is_done():
                await interaction.followup.send(mesaj, ephemeral=True)
            else:
                await interaction.response.send_message(mesaj, ephemeral=True)
        except discord.HTTPException:
            pass


def panel_gorunumu(tur):
    v = discord.ui.View(timeout=None)
    v.add_item(AcButon(tur))
    return v


def oy_gorunumu(yukari=0, asagi=0):
    v = discord.ui.View(timeout=None)
    v.add_item(OyButon("up", yukari))
    v.add_item(OyButon("down", asagi))
    for d in ("kabul", "dusun", "red"):          # yetkili durum butonları (ikinci satır)
        v.add_item(OneriDurumButon(d))
    return v


def bilet_gorunumu():
    v = discord.ui.View(timeout=None)
    v.add_item(UstlenButon())
    v.add_item(KapatButon())
    return v


def rapor_gorunumu():
    v = discord.ui.View(timeout=None)
    v.add_item(DurumButon("ink"))
    v.add_item(DurumButon("ok"))
    v.add_item(DurumButon("no"))
    return v


def alan_yaz(e, ad, deger):
    """Embed'de aynı adlı alan varsa değiştirir, yoksa ekler."""
    for i, f in enumerate(e.fields):
        if f.name == ad:
            e.set_field_at(i, name=ad, value=deger, inline=False)
            return
    e.add_field(name=ad, value=deger, inline=False)


class FormModal(discord.ui.Modal):
    def __init__(self, cog, tur):
        super().__init__(title=TURLER[tur]["modal"][:45], timeout=900)
        self.cog, self.tur = cog, tur
        self.kutular = []
        for etiket, ipucu, stil, en_cok, zorunlu in FORMLAR[tur]:
            k = discord.ui.TextInput(label=etiket[:45], placeholder=ipucu[:100], style=stil,
                                     max_length=en_cok, required=zorunlu)
            self.kutular.append((etiket, k))
            self.add_item(k)

    async def on_submit(self, interaction):
        alanlar = [(e, (k.value or "").strip()) for e, k in self.kutular]
        await self.cog.gonder(interaction, self.tur, alanlar)

    async def on_error(self, interaction, error):
        traceback.print_exception(type(error), error, error.__traceback__)
        mesaj = "❌ Gönderilirken bir hata oldu, tekrar dene. Sürerse bir yetkiliye haber ver."
        try:
            if interaction.response.is_done():
                await interaction.followup.send(mesaj, ephemeral=True)
            else:
                await interaction.response.send_message(mesaj, ephemeral=True)
        except discord.HTTPException:
            pass


# ======================================================================
# Ana cog
# ======================================================================
class V32(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.son = {}

    # ------------------------------------------------------------------ yardımcılar
    @staticmethod
    def yetkili_mi(uye):
        p = uye.guild_permissions
        if p.administrator or p.manage_guild:
            return True
        a = ayar(uye.guild.id)
        return any(r.id in a["yetkili"] for r in uye.roles)

    @staticmethod
    def yetkili_izinleri(guild):
        PO = discord.PermissionOverwrite
        ow = {}
        for rid in ayar(guild.id)["yetkili"]:
            r = guild.get_role(rid)
            if r is not None:
                ow[r] = PO(view_channel=True, send_messages=True, read_message_history=True, attach_files=True)
        return ow

    async def kategori(self, guild):
        return discord.utils.get(guild.categories, name=KATEGORI_AD) or await guild.create_category(KATEGORI_AD)

    async def kanal_bul_ya_da_ac(self, guild, tur):
        for ad in TURLER[tur]["kanal_adlari"]:
            k = discord.utils.get(guild.text_channels, name=ad)
            if k is not None:
                return k, False
        PO = discord.PermissionOverwrite
        ow = {guild.default_role: PO(send_messages=False, add_reactions=False),
              guild.me: PO(view_channel=True, send_messages=True, embed_links=True)}
        kat = await self.kategori(guild)
        k = await guild.create_text_channel(TURLER[tur]["kanal_adlari"][0], category=kat, overwrites=ow,
                                            reason="Geri bildirim sistemi")
        return k, True

    async def rapor_kanali_hazirla(self, guild, kategori=None):
        """Hata raporlarının düşeceği gizli kanal."""
        a = ayar(guild.id)
        var = guild.get_channel(a["hata"]["rapor"]) if a["hata"]["rapor"] else None
        if var is not None:
            return var
        PO = discord.PermissionOverwrite
        ow = {guild.default_role: PO(view_channel=False),
              guild.me: PO(view_channel=True, send_messages=True, embed_links=True, read_message_history=True)}
        ow.update(self.yetkili_izinleri(guild))
        try:
            kanal = await guild.create_text_channel(RAPOR_KANALI, category=kategori, overwrites=ow, reason="Hata raporları")
        except discord.HTTPException:
            return None
        a["hata"]["rapor"] = kanal.id
        kaydet()
        return kanal

    async def panel_gonder(self, guild, kanal, tur):
        a = ayar(guild.id)[tur]
        t = TURLER[tur]
        e = discord.Embed(title=t["baslik"], description=t["yazi"], color=t["renk"])
        msg = await kanal.send(embed=e, view=panel_gorunumu(tur))
        eski = a.get("panel")
        if eski and eski[1] != msg.id:
            try:
                ek = guild.get_channel(eski[0])
                if ek is not None:
                    await ek.get_partial_message(eski[1]).delete()
            except discord.HTTPException:
                pass
        a["kanal"] = kanal.id
        a["panel"] = [kanal.id, msg.id]
        kaydet()
        return msg

    # ------------------------------------------------------------------ butonlar
    async def buton_ac(self, interaction, tur):
        guild, uye = interaction.guild, interaction.user
        if guild is None or not isinstance(uye, discord.Member):
            return await interaction.response.send_message("❌ Bu buton sadece sunucuda çalışır.", ephemeral=True)
        a = ayar(guild.id)
        if tur == "destek":
            var = guild.get_channel(a["bilet"].get(str(uye.id), 0))
            if var is not None:
                return await interaction.response.send_message(f"🎫 Zaten açık bir destek kanalın var: {var.mention}", ephemeral=True)
            a["bilet"].pop(str(uye.id), None)
        anahtar = (guild.id, uye.id, tur)
        kalan = BEKLEME - (time.time() - self.son.get(anahtar, 0))
        if kalan > 0:
            return await interaction.response.send_message(f"⏳ Biraz yavaş, **{int(kalan) + 1} saniye** sonra tekrar dene.", ephemeral=True)
        await interaction.response.send_modal(FormModal(self, tur))

    @staticmethod
    def bilet_sahibi(kanal):
        a = ayar(kanal.guild.id)
        return next((u for u, c in a["bilet"].items() if c == kanal.id), None)

    async def transkript(self, kanal):
        satirlar = []
        async for m in kanal.history(limit=1000, oldest_first=True):
            icerik = m.content or ""
            if not icerik and m.embeds:
                e0 = m.embeds[0]
                icerik = "[embed] " + " | ".join(x for x in (e0.title, kisalt(e0.description, 300)) if x)
            for ek in m.attachments:
                icerik += f" [dosya: {ek.url}]"
            satirlar.append(f"[{m.created_at.strftime('%Y-%m-%d %H:%M')}] {m.author}: {icerik}")
        return "\n".join(satirlar) or "(mesaj yok)", len(satirlar)

    async def arsiv_kanali_hazirla(self, guild, kategori=None):
        """Kapanan destek kanallarının kaydı (transkript) düşen gizli kanal."""
        a = ayar(guild.id)
        var = guild.get_channel(a["arsiv"]) if a["arsiv"] else None
        if var is not None:
            return var
        PO = discord.PermissionOverwrite
        ow = {guild.default_role: PO(view_channel=False),
              guild.me: PO(view_channel=True, send_messages=True, embed_links=True, attach_files=True, read_message_history=True)}
        ow.update(self.yetkili_izinleri(guild))
        try:
            kanal = await guild.create_text_channel("destek-arsivi", category=kategori, overwrites=ow, reason="Destek arşivi")
        except discord.HTTPException:
            return None
        a["arsiv"] = kanal.id
        kaydet()
        return kanal

    async def buton_kapat(self, interaction):
        guild, kanal = interaction.guild, interaction.channel
        a = ayar(guild.id)
        sahip = self.bilet_sahibi(kanal)
        if sahip is None:
            return await interaction.response.send_message("❌ Bu bir destek kanalı değil.", ephemeral=True)
        if str(interaction.user.id) != sahip and not self.yetkili_mi(interaction.user):
            return await interaction.response.send_message("❌ Bu kanalı sadece açan kişi ya da yetkililer kapatabilir.", ephemeral=True)
        await interaction.response.send_message(
            f"🔒 {interaction.user.mention} destek kanalını kapattı. Konuşma kaydedilip kanal **5 saniye** sonra silinecek.",
            allowed_mentions=NO_PING)
        a["bilet"].pop(sahip, None)
        ustlenen = a["ustlen"].pop(str(kanal.id), None)
        kaydet()
        try:
            metin, adet = await self.transkript(kanal)
        except discord.HTTPException:
            metin, adet = "(kayıt okunamadı)", 0
        dosya_adi = f"{kanal.name}.txt"
        veri_bayt = metin.encode("utf-8")
        arsiv = await self.arsiv_kanali_hazirla(guild, kanal.category)
        e = discord.Embed(title=f"📁 Destek kapandı: #{kanal.name}", color=0x99AAB5)
        e.add_field(name="Açan", value=f"<@{sahip}>", inline=True)
        e.add_field(name="Kapatan", value=interaction.user.mention, inline=True)
        e.add_field(name="Üstlenen", value=f"<@{ustlenen}>" if ustlenen else "—", inline=True)
        e.add_field(name="Mesaj sayısı", value=str(adet), inline=True)
        if arsiv is not None:
            try:
                await arsiv.send(embed=e, file=discord.File(io.BytesIO(veri_bayt), dosya_adi), allowed_mentions=NO_PING)
            except discord.HTTPException:
                pass
        kisi = guild.get_member(int(sahip))
        if kisi is not None:
            try:
                await kisi.send(f"🎫 **{guild.name}** destek konuşmanın kaydı ektedir.",
                                file=discord.File(io.BytesIO(veri_bayt), dosya_adi))
            except discord.HTTPException:
                pass
        await asyncio.sleep(5)
        try:
            await kanal.delete(reason=f"Destek kapatıldı: {interaction.user}")
        except discord.HTTPException:
            pass

    async def buton_ustlen(self, interaction):
        guild, kanal = interaction.guild, interaction.channel
        if not isinstance(interaction.user, discord.Member) or not self.yetkili_mi(interaction.user):
            return await interaction.response.send_message("❌ Bunu sadece yetkililer yapabilir.", ephemeral=True)
        if self.bilet_sahibi(kanal) is None or not interaction.message.embeds:
            return await interaction.response.send_message("❌ Bu bir destek kanalı değil.", ephemeral=True)
        a = ayar(guild.id)
        if str(kanal.id) in a["ustlen"]:
            return await interaction.response.send_message(f"🙋 Bu talebi zaten <@{a['ustlen'][str(kanal.id)]}> üstlendi.",
                                                           ephemeral=True)
        a["ustlen"][str(kanal.id)] = interaction.user.id
        kaydet()
        e = interaction.message.embeds[0]
        alan_yaz(e, "Üstlenen", f"🙋 {interaction.user.mention}")
        await interaction.response.edit_message(embed=e)
        await kanal.send(f"🙋 {interaction.user.mention} bu talebi **üstlendi**.", allowed_mentions=NO_PING)

    async def buton_durum(self, interaction, d):
        if not isinstance(interaction.user, discord.Member) or not self.yetkili_mi(interaction.user):
            return await interaction.response.send_message("❌ Bunu sadece yetkililer yapabilir.", ephemeral=True)
        if not interaction.message.embeds:
            return await interaction.response.send_message("❌ Rapor bulunamadı.", ephemeral=True)
        metin, renk = {"ok": ("✅ Çözüldü", 0x57F287), "no": ("🚫 Geçersiz", 0x99AAB5),
                       "ink": ("🛠️ İnceleniyor", 0xFEE75C)}[d]
        e = interaction.message.embeds[0]
        e.color = renk
        alan_yaz(e, "Durum", f"{metin} • {interaction.user.mention}")
        son = d != "ink"                                   # inceleniyor: butonlar kalır, çözüldü/geçersiz: kapanır
        await interaction.response.edit_message(embed=e, view=None if son else rapor_gorunumu())
        if not son:
            return
        m = re.search(r"Bildiren ID: (\d+)", (e.footer.text if e.footer else "") or "")
        if m:
            try:
                kisi = interaction.guild.get_member(int(m.group(1))) or await self.bot.fetch_user(int(m.group(1)))
                await kisi.send(f"🐞 **{interaction.guild.name}** sunucusuna bildirdiğin hata raporu "
                                f"{'**çözüldü**, teşekkürler!' if d == 'ok' else '**geçersiz** bulundu.'}")
            except (discord.HTTPException, discord.NotFound):
                pass

    async def buton_od(self, interaction, d):
        if not isinstance(interaction.user, discord.Member) or not self.yetkili_mi(interaction.user):
            return await interaction.response.send_message("❌ Bunu sadece yetkililer yapabilir.", ephemeral=True)
        if not interaction.message.embeds:
            return await interaction.response.send_message("❌ Öneri bulunamadı.", ephemeral=True)
        metin, renk = {"kabul": ("✅ Kabul edildi", 0x57F287), "dusun": ("⏳ Düşünülüyor", 0xFEE75C),
                       "red": ("❌ Reddedildi", 0xED4245)}[d]
        e = interaction.message.embeds[0]
        e.color = renk
        alan_yaz(e, "Durum", f"{metin} • {interaction.user.mention}")
        await interaction.response.edit_message(embed=e)
        m = re.search(r"Öneren ID: (\d+)", (e.footer.text if e.footer else "") or "")
        if m and d in ("kabul", "red"):
            try:
                kisi = interaction.guild.get_member(int(m.group(1))) or await self.bot.fetch_user(int(m.group(1)))
                await kisi.send(f"💡 **{interaction.guild.name}** sunucusuna yaptığın öneri "
                                f"{'**kabul edildi** 🎉' if d == 'kabul' else '**reddedildi**, ilgin için teşekkürler.'}")
            except (discord.HTTPException, discord.NotFound):
                pass

    async def buton_oy(self, interaction, yon):
        msg = interaction.message
        o = veri["oy"].setdefault(str(msg.id), {"up": [], "down": []})
        uid = interaction.user.id
        karsi = "down" if yon == "up" else "up"
        if uid in o[yon]:
            o[yon].remove(uid)
        else:
            o[yon].append(uid)
            if uid in o[karsi]:
                o[karsi].remove(uid)
        kaydet()
        await interaction.response.edit_message(view=oy_gorunumu(len(o["up"]), len(o["down"])))

    # ------------------------------------------------------------------ form gönderildi
    async def gonder(self, interaction, tur, alanlar):
        guild, uye = interaction.guild, interaction.user
        a = ayar(guild.id)
        await interaction.response.defer(ephemeral=True, thinking=True)
        self.son[(guild.id, uye.id, tur)] = time.time()
        a["sayac"][tur] += 1
        no = a["sayac"][tur]
        baslik, ayrinti = alanlar[0][1], alanlar[1][1]
        ekstra = alanlar[2:]
        t = TURLER[tur]

        if tur == "destek":
            panel_kanal = guild.get_channel(a["destek"]["kanal"] or 0)
            PO = discord.PermissionOverwrite
            ow = {guild.default_role: PO(view_channel=False),
                  uye: PO(view_channel=True, send_messages=True, read_message_history=True, attach_files=True),
                  guild.me: PO(view_channel=True, send_messages=True, manage_channels=True, embed_links=True, read_message_history=True)}
            ow.update(self.yetkili_izinleri(guild))
            ad = re.sub(r"[^a-z0-9]+", "-", uye.name.lower().translate(str.maketrans("çğıöşü", "cgiosu")))[:20].strip("-") or "uye"
            try:
                kanal = await guild.create_text_channel(
                    f"destek-{ad}", category=panel_kanal.category if panel_kanal else None, overwrites=ow,
                    topic=f"Destek • {uye} • ID {uye.id}", reason=f"Destek talebi: {uye}")
            except discord.HTTPException:
                a["sayac"][tur] -= 1
                return await interaction.followup.send("❌ Destek kanalı açılamadı. Bir yetkiliye haber ver.", ephemeral=True)
            a["bilet"][str(uye.id)] = kanal.id
            kaydet()
            e = discord.Embed(title=f"🎫 Destek #{no}: {kisalt(baslik, 200)}", description=kisalt(ayrinti, 3500), color=t["renk"])
            e.set_author(name=str(uye), icon_url=uye.display_avatar.url)
            e.set_footer(text="Yetkililer birazdan yazacak • Kapatmak için 🔒 butonuna bas")
            roller = " ".join(r.mention for r in (guild.get_role(i) for i in a["yetkili"]) if r)
            await kanal.send(content=f"{uye.mention} {roller}".strip(), embed=e, view=bilet_gorunumu(),
                             allowed_mentions=discord.AllowedMentions(users=True, roles=True))
            return await interaction.followup.send(f"✅ Destek kanalın açıldı: {kanal.mention}", ephemeral=True)

        if tur == "hata":
            kanal = guild.get_channel(a["hata"]["rapor"] or 0) or await self.rapor_kanali_hazirla(guild)
            if kanal is None:
                a["sayac"][tur] -= 1
                return await interaction.followup.send("❌ Rapor kanalı bulunamadı. Bir yetkiliye haber ver.", ephemeral=True)
            e = discord.Embed(title=f"🐞 Hata #{no}: {kisalt(baslik, 200)}", description=kisalt(ayrinti, 3500), color=t["renk"])
            e.set_author(name=str(uye), icon_url=uye.display_avatar.url)
            for etiket, deger in ekstra:
                if deger:
                    e.add_field(name=etiket[:100], value=kisalt(deger, 1000), inline=False)
            e.add_field(name="Bildiren", value=uye.mention, inline=True)
            e.set_footer(text=f"Bildiren ID: {uye.id}")
            roller = " ".join(r.mention for r in (guild.get_role(i) for i in a["yetkili"]) if r)
            try:
                await kanal.send(content=roller or None, embed=e, view=rapor_gorunumu(),
                                 allowed_mentions=discord.AllowedMentions(roles=True, users=False))
            except discord.HTTPException:
                a["sayac"][tur] -= 1
                return await interaction.followup.send("❌ Rapor gönderilemedi. Bir yetkiliye haber ver.", ephemeral=True)
            return await interaction.followup.send(f"✅ Hata raporun (**#{no}**) yetkililere iletildi, teşekkürler!", ephemeral=True)

        # öneri: öneri kanalına düşer, panel yeniden en alta konur
        kanal = guild.get_channel(a["oneri"]["kanal"] or 0)
        if kanal is None:
            a["sayac"][tur] -= 1
            return await interaction.followup.send("❌ Öneri kanalı bulunamadı. Bir yetkiliye haber ver.", ephemeral=True)
        e = discord.Embed(title=f"💡 Öneri #{no}: {kisalt(baslik, 200)}", description=kisalt(ayrinti, 3500), color=t["renk"])
        e.set_author(name=str(uye), icon_url=uye.display_avatar.url)
        e.set_footer(text=f"Öneren ID: {uye.id}")
        try:
            await kanal.send(embed=e, view=oy_gorunumu(), allowed_mentions=NO_PING)
            await self.panel_gonder(guild, kanal, "oneri")
        except discord.HTTPException:
            a["sayac"][tur] -= 1
            return await interaction.followup.send("❌ Öneri gönderilemedi. Bir yetkiliye haber ver.", ephemeral=True)
        await interaction.followup.send(f"✅ Önerin (**#{no}**) {kanal.mention} kanalına gönderildi, teşekkürler!", ephemeral=True)

    @commands.Cog.listener()
    async def on_guild_channel_delete(self, kanal):
        a = ayar(kanal.guild.id)
        for u in [u for u, c in a["bilet"].items() if c == kanal.id]:
            a["bilet"].pop(u, None)
        kaydet()

