    async def kural_kabul(self, interaction):
        guild, uye = interaction.guild, interaction.user
        rol = guild.get_role(ayar(guild.id)["kural"]["rol"] or 0)
        if rol is None:
            return await interaction.response.send_message("✅ Teşekkürler!", ephemeral=True)
        if rol in uye.roles:
            return await interaction.response.send_message("✅ Kuralları zaten kabul etmiştin.", ephemeral=True)
        if rol.managed or rol >= guild.me.top_role or sys.modules["v15"].riskli_rol(rol):      # rol sonradan yetkilendirilmiş olabilir
            return await interaction.response.send_message("⚠️ Bu rol artık güvenli değil (yetkileri değişmiş). Bir yetkiliye haber ver.", ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        try:
            await uye.add_roles(rol, reason="Kuralları kabul etti")
        except discord.HTTPException:
            return await interaction.followup.send(
                "⚠️ Rolü veremedim. Botun rolü, verilecek rolün **üstünde** olmalı. Bir yetkiliye haber ver.", ephemeral=True)
        await interaction.followup.send(f"✅ Kuralları kabul ettin, {rol.mention} rolü verildi!", ephemeral=True)

    async def kural_yenile(self, guild):
        k = ayar(guild.id)["kural"]
        if not k["panel"]:
            return
        kanal = guild.get_channel(k["panel"][0])
        if kanal is None:
            k["panel"] = None
            return
        try:
            await kanal.get_partial_message(k["panel"][1]).edit(embed=kural_embed(guild), view=kural_gorunumu(guild))
        except discord.NotFound:
            k["panel"] = None
        except discord.HTTPException:
            pass
        kaydet()

