    @commands.Cog.listener()
    async def on_member_update(self, once, sonra):
        # timeout verildi
        if sonra.timed_out_until and once.timed_out_until != sonra.timed_out_until:
            await asyncio.sleep(1.5)
            yetkili, sebep = await self.denetim(sonra.guild, discord.AuditLogAction.member_update, sonra.id)
            sure = int((sonra.timed_out_until - discord.utils.utcnow()).total_seconds())
            await self.vaka_ac(sonra.guild, "timeout", sonra.id, yetkili, sebep, max(sure, 0))
        # boost teşekkürü
        if once.premium_since is None and sonra.premium_since is not None:
            b = ayar(sonra.guild.id)["boost"]
            kanal = sonra.guild.get_channel(b["kanal"]) if b["kanal"] else None
            if kanal is not None:
                metin = (b["metin"] or "💎 {uye} sunucuyu **boostladı**! Çok teşekkürler 💜 Sunucumuz artık **{sayi}** boost'a sahip.")
                metin = metin.replace("{uye}", sonra.mention).replace("{sunucu}", sonra.guild.name) \
                             .replace("{sayi}", str(sonra.guild.premium_subscription_count or 0))
                e = discord.Embed(description=metin[:4000], color=0xF47FFF)
                e.set_thumbnail(url=sonra.display_avatar.url)
                try:
                    await kanal.send(content=sonra.mention, embed=e, allowed_mentions=discord.AllowedMentions(users=True))
                except discord.HTTPException:
                    pass

    # ------------------------------------------------------------------ hayalet ping
    @commands.Cog.listener()
    async def on_message_delete(self, message):
        if message.guild is None or message.author.bot:
            return
        kanal_id = ayar(message.guild.id)["hayalet"]["kanal"]
        if not kanal_id:
            return
        hedefler = [m for m in message.mentions if not m.bot and m.id != message.author.id]
        if not hedefler and not message.role_mentions and not message.mention_everyone:
            return
        if (discord.utils.utcnow() - message.created_at).total_seconds() > 300:
            return
        kanal = message.guild.get_channel(kanal_id)
        if kanal is None:
            return
        e = discord.Embed(title="👻 Hayalet ping", color=0x99AAB5, description=kisalt(message.content, 1500))
        e.add_field(name="Gönderen", value=message.author.mention, inline=True)
        e.add_field(name="Kanal", value=message.channel.mention, inline=True)
        kisiler = [m.mention for m in hedefler] + [r.mention for r in message.role_mentions] + (["@everyone/@here"] if message.mention_everyone else [])
        e.add_field(name="Etiketlenenler", value=kisalt(" ".join(kisiler), 1000), inline=False)
        try:
            await kanal.send(embed=e, allowed_mentions=NO_PING)
        except discord.HTTPException:
            pass

    # ------------------------------------------------------------------ arka plan döngüsü
    @tasks.loop(seconds=30)
    async def dongu(self):
        try:
            await self.gecici_kontrol()
            await self.etkinlik_kontrol()
        except Exception:
            traceback.print_exc()

    @dongu.before_loop
    async def dongu_once(self):
        await self.bot.wait_until_ready()

    async def gecici_kontrol(self):
        simdi = time.time()
        for g in [x for x in veri["gecici"] if x["bitis"] <= simdi]:
            await self.gecici_bitir(g)

    async def gecici_bitir(self, g, yetkili_id=None):
        if g in veri["gecici"]:
            veri["gecici"].remove(g)
            kaydet()
        guild = self.bot.get_guild(g["gid"])
        if guild is None:
            return
        try:
            if g["tur"] == "ban":
                self.atla[("unban", guild.id, g["uid"])] = time.time()
                await guild.unban(discord.Object(id=g["uid"]), reason="Geçici ban süresi doldu")
                await self.vaka_ac(guild, "unban", g["uid"], yetkili_id, "Geçici ban süresi doldu")
            else:
                uye, rol = guild.get_member(g["uid"]), guild.get_role(g["rol"])
                if uye is not None and rol is not None and rol in uye.roles:
                    await uye.remove_roles(rol, reason="Geçici rol süresi doldu")
        except discord.HTTPException:
            pass

    async def etkinlik_kontrol(self):
        simdi = time.time()
        for mid, ev in list(veri["etkinlik"].items()):
            guild = self.bot.get_guild(ev["gid"])
            if guild is None:
                veri["etkinlik"].pop(mid, None)
                continue
            kalan = ev["bitis"] - simdi
            baglanti = f"https://discord.com/channels/{ev['gid']}/{ev['kanal']}/{mid}"
            if 0 < kalan <= 900 and not ev["hatirlatma"]:
                ev["hatirlatma"] = True
                kaydet()
                for uid in ev["kat"]:
                    uye = guild.get_member(uid)
                    if uye is None:
                        continue
                    try:
                        await uye.send(f"⏰ **{guild.name}** • **{ev['baslik']}** etkinliği yaklaşık **{int(kalan // 60) + 1} dakika** sonra başlıyor!\n{baglanti}")
                    except discord.HTTPException:
                        pass
                    await asyncio.sleep(0.5)
            if kalan <= 0 and not ev["basladi"]:
                ev["basladi"] = True
                kaydet()
                kanal = guild.get_channel(ev["kanal"])
                if kanal is not None:
                    etiket = " ".join(f"<@{u}>" for u in ev["kat"][:40])
                    try:
                        await kanal.send(f"🎉 **{ev['baslik']}** etkinliği **başladı!** {etiket}".strip(),
                                         allowed_mentions=discord.AllowedMentions(users=True))
                        await kanal.get_partial_message(int(mid)).edit(embed=etkinlik_embed(ev), view=None)
                    except discord.HTTPException:
                        pass
            if kalan < -172800:
                veri["etkinlik"].pop(mid, None)
                kaydet()

    async def etkinlik_buton(self, interaction, d):
        ev = veri["etkinlik"].get(str(interaction.message.id))
        if ev is None:
            return await interaction.response.send_message("❌ Bu etkinlik artık yok.", ephemeral=True)
        if ev.get("basladi"):
            return await interaction.response.send_message("🎉 Etkinlik zaten başladı.", ephemeral=True)
        uid = interaction.user.id
        if uid in ev[d]:
            ev[d].remove(uid)
        else:
            for k in ("kat", "belki", "yok"):
                if uid in ev[k]:
                    ev[k].remove(uid)
            ev[d].append(uid)
        kaydet()
        await interaction.response.edit_message(embed=etkinlik_embed(ev))

