    async def notsil(self, ctx, uye: discord.User, no: int):
        """🗑️ Bir notu siler (notu yazan ya da Sunucuyu Yönet yetkisi olan)"""
        notlar = ayar(ctx.guild.id)["notlar"].get(str(uye.id), [])
        if not 1 <= no <= len(notlar):
            return await ctx.send(f"❌ 1 ile {len(notlar)} arasında bir numara yaz.")
        if notlar[no - 1]["y"] != ctx.author.id and not ctx.author.guild_permissions.manage_guild:
            return await ctx.send("❌ Bu notu sadece yazan kişi ya da **Sunucuyu Yönet** yetkisi olan silebilir.")
        notlar.pop(no - 1)
        kaydet()
        await ctx.send("🗑️ Not silindi.")

