    @commands.has_permissions(manage_guild=True)
    @commands.guild_only()
    async def boostmetin(self, ctx, *, metin: str):
        """💎 Boost teşekkür metnini değiştirir ({uye}, {sunucu}, {sayi})"""
        b = ayar(ctx.guild.id)["boost"]
