def ses_dm_durum(gid):
    """Ses DM sistemi v29'da; buradan sadece okunur/değiştirilir."""
    v29 = sys.modules.get("v29")
    if v29 is None:
        return None
    return bool(v29.veri["sesdm"].get(str(gid), {}).get("aktif"))


def ses_dm_ayarla(guild, acik, bot=None):
    v29 = sys.modules.get("v29")
    if v29 is None:
        return False
    a = v29.veri["sesdm"].setdefault(str(guild.id), {"aktif": False, "mesaj": ""})
    a["aktif"] = bool(acik)
    v29.kaydet()
