def gizle(metin):
    """Hata/log metninden token ve API anahtarlarını siler."""
    metin = str(metin)
    for ad in ("DISCORD_TOKEN", "GEMINI_KEY", "YT_PROXY", "YT_COOKIES"):
        deger = os.getenv(ad, "").strip()
        if len(deger) >= 6:
            metin = metin.replace(deger, f"<{ad}>")
    metin = re.sub(r"(?i)(key|token|api_key|apikey|password|secret)=([^&\s'\"]+)", r"\1=<gizli>", metin)
    metin = re.sub(r"[A-Za-z0-9_\-]{24}\.[A-Za-z0-9_\-]{6}\.[A-Za-z0-9_\-]{27,}", "<discord-token>", metin)
    return metin


def sayi_al(metin, alt, ust):
    """Sadece rakamlardan oluşan, alt-üst sınır içindeki sayıyı döndürür; aksi halde None."""
    metin = (metin or "").strip()
    if not re.fullmatch(r"\d{1,6}", metin):
        return None
    n = int(metin)
    return n if alt <= n <= ust else None


def temiz_metin(metin, n=70):
    """Önizlemede gösterilecek metni etiket/biçim kaçışlarından arındırır."""
    metin = (metin or "").replace("\n", " ")
    return discord.utils.escape_markdown(discord.utils.escape_mentions(metin))[:n]


class Sinirlayici:
    """Kayan pencere hız sınırı: `sure` saniyede en fazla `adet` işlem."""

    def __init__(self, adet, sure):
        self.adet, self.sure, self.k = adet, sure, {}

    def dene(self, anahtar):
        simdi = time.monotonic()
        liste = [t for t in self.k.get(anahtar, []) if simdi - t < self.sure]
        if len(liste) >= self.adet:
            self.k[anahtar] = liste
            return False
        liste.append(simdi)
        self.k[anahtar] = liste
        return True

    def bakim(self):
        simdi = time.monotonic()
        for a in list(self.k):
            self.k[a] = [t for t in self.k[a] if simdi - t < self.sure]
            if not self.k[a]:
                del self.k[a]


KOMUT_LIMIT = Sinirlayici(6, 10)        # kişi başı 10 sn'de 6 komut
BUTON_LIMIT = Sinirlayici(8, 10)        # kişi başı 10 sn'de 8 buton
UYARI_LIMIT = Sinirlayici(1, 10)        # "yavaş" uyarısı da spam olmasın
TEMIZLE_LIMIT = Sinirlayici(1, 5)       # kişi başı 5 sn'de 1 silme işlemi
ISLEM_KILIT = set()                     # aynı kanalda aynı anda tek temizleme


async def global_hiz(ctx):
    """Tüm komutlar için flood koruması (bot sahibi muaf). Aşılınca komut sessizce reddedilir."""
    try:
        if await ctx.bot.is_owner(ctx.author):
            return True
    except Exception:
        pass
    if KOMUT_LIMIT.dene(ctx.author.id):
        return True
    if UYARI_LIMIT.dene(("uyari", ctx.author.id)):
        try:
            await ctx.send("⏳ Çok hızlı komut yazıyorsun, birkaç saniye bekle.", delete_after=5)
        except discord.HTTPException:
            pass
    raise commands.CheckFailure("hız sınırı")


MODERASYON_UYE = {"ban", "kick", "timeout", "untimeout", "warn", "clearwarns", "nick", "rolver", "rolal", "tempban", "temprol", "notekle"}
KENDINE_YASAK = {"ban", "kick", "timeout", "tempban"}
MODERASYON_ROL = {"rolver", "rolal", "toplurolver", "temprol"}


async def hiyerarsi_muhafizi(ctx):
    """Eski komutlar dahil TÜM moderasyon komutlarında rol hiyerarşisini zorlar (komut parametreleri çözüldükten sonra çalışır)."""
    try:
        kmt = ctx.command
        if kmt is None or ctx.guild is None:
            return
        ad = kmt.qualified_name
        if ad not in MODERASYON_UYE and ad not in MODERASYON_ROL:
            return
        g, yazar, ben = ctx.guild, ctx.author, ctx.guild.me
        sahip = yazar.id == g.owner_id
        for d in [*ctx.args, *ctx.kwargs.values()]:
            sorun = None
            if isinstance(d, discord.Member) and ad in MODERASYON_UYE:
                if d.id == ben.id:
                    sorun = "❌ Bu işlemi bana uygulayamazsın."
                elif d.id == yazar.id:
                    if ad in KENDINE_YASAK:
                        sorun = "❌ Bunu kendine uygulayamazsın."
                elif d.id == g.owner_id:
                    sorun = "❌ Sunucu sahibine bu işlem uygulanamaz."
                elif not sahip and d.top_role >= yazar.top_role:
                    sorun = "❌ Rolü senden yüksek ya da eşit birine bu işlemi uygulayamazsın."
                elif d.top_role >= ben.top_role:
                    sorun = "❌ Bu kişinin rolü benimkinden yüksek ya da eşit, işlemi yapamam."
            elif isinstance(d, discord.Role) and ad in MODERASYON_ROL:
                if d.is_default() or d.managed:
                    sorun = "❌ Bu rol (everyone ya da bot/entegrasyon rolü) verilip alınamaz."
                elif not sahip and d >= yazar.top_role:
                    sorun = "❌ Bu rol senin en yüksek rolünden yüksek ya da eşit, yönetemezsin."
                elif d >= ben.top_role:
                    sorun = "❌ Bu rol benim en yüksek rolümden yüksek ya da eşit, yönetemem."
            if sorun:
                await ctx.send(sorun)
                raise commands.CheckFailure("hiyerarşi")
    except commands.CheckFailure:
        raise
    except Exception as e:
        print(f"hiyerarşi koruması hatası: {gizle(repr(e))}")


class KilitliView(discord.ui.View):
    """Sadece menüyü açan kişinin kullanabildiği, hız sınırlı, süre dolunca kapanan view."""

    def __init__(self, yazar_id, sure=180):
        super().__init__(timeout=sure)
        self.yazar_id = yazar_id
        self.mesaj = None

    async def interaction_check(self, interaction):
        if interaction.user.id != self.yazar_id:
            await interaction.response.send_message("❌ Bu menüyü sadece komutu yazan kişi kullanabilir.", ephemeral=True)
            return False
        if not BUTON_LIMIT.dene(interaction.user.id):
            await interaction.response.send_message("⏳ Çok hızlı basıyorsun, birkaç saniye bekle.", ephemeral=True)
            return False
        return True

    async def on_timeout(self):
        for c in self.children:
            c.disabled = True
        if self.mesaj is not None:
            try:
                await self.mesaj.edit(view=self)
            except discord.HTTPException:
                pass

    async def on_error(self, interaction, error, item):
        print(f"v35 view hatası: {gizle(repr(error))}")
        try:
            if interaction.response.is_done():
                await interaction.followup.send("❌ Bir hata oldu, tekrar dene.", ephemeral=True)
            else:
                await interaction.response.send_message("❌ Bir hata oldu, tekrar dene.", ephemeral=True)
        except discord.HTTPException:
            pass


