class Sayfalayici(KilitliView):
    def __init__(self, yazar_id, sayfalar, sure=180):
        super().__init__(yazar_id, sure)
        self.sayfalar, self.i = sayfalar, 0

    def embed(self):
        e = self.sayfalar[self.i].copy()
        e.set_footer(text=f"Sayfa {self.i + 1}/{len(self.sayfalar)}")
        return e

    async def degistir(self, interaction, yeni):
        self.i = yeni % len(self.sayfalar)
        await interaction.response.edit_message(embed=self.embed(), view=self)

    @discord.ui.button(emoji="◀️", style=discord.ButtonStyle.secondary, row=0)
    async def geri(self, interaction, button):
        await self.degistir(interaction, self.i - 1)

    @discord.ui.button(emoji="▶️", style=discord.ButtonStyle.secondary, row=0)
    async def ileri(self, interaction, button):
        await self.degistir(interaction, self.i + 1)

    @discord.ui.button(label="Git", emoji="🔢", style=discord.ButtonStyle.secondary, row=0)
    async def git(self, interaction, button):
        await interaction.response.send_modal(SayfaGitModal(self))

    @discord.ui.button(emoji="✖️", style=discord.ButtonStyle.danger, row=0)
    async def kapat(self, interaction, button):
        for c in self.children:
            c.disabled = True
        self.stop()
        await interaction.response.edit_message(embed=self.embed(), view=self)


def sayfalara_bol(baslik, satirlar, boy=10, renk=0x5865F2):
    sayfalar = []
    for i in range(0, max(len(satirlar), 1), boy):
        sayfalar.append(discord.Embed(title=baslik, description="\n".join(satirlar[i:i + boy]) or "Kayıt yok", color=renk))
    return sayfalar


async def sayfali_gonder(ctx, baslik, satirlar, renk=0x5865F2, boy=10):
    """Satırları ◀ ▶ butonlu sayfalar halinde gönderir (tek sayfaysa butonsuz)."""
    sayfalar = sayfalara_bol(baslik, satirlar, boy, renk)
    if len(sayfalar) == 1:
        return await ctx.send(embed=sayfalar[0], allowed_mentions=NO_PING)
    v = Sayfalayici(ctx.author.id, sayfalar)
    v.mesaj = await ctx.send(embed=v.embed(), view=v, allowed_mentions=NO_PING)


