class PremiumButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td35:pr:(?P<i>durum|avantaj|gunluk|aylik|satin)"):
    ETIKET = {"durum": ("Durumum", "🔍", discord.ButtonStyle.primary),
              "avantaj": ("Avantajlar", "✨", discord.ButtonStyle.secondary),
              "gunluk": ("Günlük bonus", "🎁", discord.ButtonStyle.success),
              "aylik": ("Aylık altın", "🪙", discord.ButtonStyle.success),
              "satin": ("Satın al", "🛒", discord.ButtonStyle.primary)}

    def __init__(self, islem):
        etiket, emoji, stil = self.ETIKET[islem]
        super().__init__(discord.ui.Button(label=etiket, emoji=emoji, style=stil, custom_id=f"td35:pr:{islem}"))
        self.islem = islem

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["i"])

    async def callback(self, interaction):
        cog = interaction.client.get_cog("V35")
        try:
            if cog is None:
                return await interaction.response.send_message("❌ Bu sistem şu an çalışmıyor.", ephemeral=True)
            if not BUTON_LIMIT.dene(("pr", interaction.user.id)):
                return await interaction.response.send_message("⏳ Çok hızlı basıyorsun, birkaç saniye bekle.", ephemeral=True)
            await cog.premium_buton(interaction, self.islem)
        except Exception as e:
            print(f"v35 premium buton hatası: {gizle(repr(e))}")
            try:
                if interaction.response.is_done():
                    await interaction.followup.send("❌ Bir hata oldu, tekrar dene.", ephemeral=True)
                else:
                    await interaction.response.send_message("❌ Bir hata oldu, tekrar dene.", ephemeral=True)
            except discord.HTTPException:
                pass


class AyarPanel(KilitliView):
    """Butonlu merkezi ayar paneli (Sunucuyu Yönet yetkisi gerekir, sadece açan kişi kullanır)."""

    def __init__(self, guild, yazar_id):
        super().__init__(yazar_id, 240)
        self.guild = guild
        self.stil_guncelle()

    async def interaction_check(self, interaction):
        if not await super().interaction_check(interaction):
            return False
        if not interaction.user.guild_permissions.manage_guild:
            await interaction.response.send_message("❌ Bunun için **Sunucuyu Yönet** yetkin olmalı.", ephemeral=True)
            return False
        return True

    def durumlar(self):
        v33 = sys.modules.get("v33")
        guncelleme = v33.ayar(self.guild.id)["guncelleme"]["acik"] if v33 is not None else None
        return ses_dm_durum(self.guild.id), guncelleme

    def stil_guncelle(self):
        ses, guncelleme = self.durumlar()
        self.ses_btn.style = discord.ButtonStyle.success if ses else discord.ButtonStyle.secondary
        self.ses_btn.disabled = ses is None
        self.guncelleme_btn.style = discord.ButtonStyle.success if guncelleme else discord.ButtonStyle.secondary
        self.guncelleme_btn.disabled = guncelleme is None

    def embed(self):
        ses, guncelleme = self.durumlar()
        v20 = sys.modules.get("v20")
        premium = len(v20.veri["vip"].get(str(self.guild.id), {})) if v20 is not None else 0
        e = discord.Embed(title="⚙️ Merkezi ayar paneli", color=0x5865F2,
                          description="Butonlara basarak ayarları aç/kapat. Ayarlar kalıcıdır; yeni sunucular varsayılanı otomatik alır.")
        e.add_field(name="🔊 Ses giriş/çıkış DM'i", value="—" if ses is None else ("✅ Açık" if ses else "⛔ Kapalı"), inline=True)
        e.add_field(name="🔄 Güncelleme duyurusu", value="—" if guncelleme is None else ("✅ Açık" if guncelleme else "⛔ Kapalı"), inline=True)
        e.add_field(name="💎 PREMIUM (Beta) üye", value=str(premium), inline=True)
        return e

    @discord.ui.button(label="Ses çıkış DM", emoji="🔊", style=discord.ButtonStyle.secondary, row=0)
    async def ses_btn(self, interaction, button):
        ses_dm_ayarla(self.guild, not ses_dm_durum(self.guild.id), interaction.client)
        self.stil_guncelle()
        await interaction.response.edit_message(embed=self.embed(), view=self)

    @discord.ui.button(label="Güncelleme duyurusu", emoji="🔄", style=discord.ButtonStyle.secondary, row=0)
    async def guncelleme_btn(self, interaction, button):
        v33 = sys.modules.get("v33")
        if v33 is not None:
            g = v33.ayar(self.guild.id)["guncelleme"]
            g["acik"] = not g["acik"]
            v33.kaydet()
        self.stil_guncelle()
        await interaction.response.edit_message(embed=self.embed(), view=self)

    @discord.ui.button(label="Kapat", emoji="✖️", style=discord.ButtonStyle.danger, row=0)
    async def kapat_btn(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(view=None)


