# GIF üretimi (video yerine hareketli GIF)
# ======================================================================
def gif_uret(bayt, stil):
    """Çizilen resimden hareketli GIF yapar (bloklayıcı: thread'de çalıştırılır). (gif_bayt, hata) döner."""
    try:
        from PIL import Image, ImageOps
    except ImportError:
        return None, "pillow"
    im = Image.open(io.BytesIO(bayt)).convert("RGB")
    for boyut in (480, 400, 320):
        kucuk = ImageOps.contain(im, (boyut, boyut))
        W, H = kucuk.size
        taban = kucuk.resize((int(W * 1.3), int(H * 1.3)), Image.LANCZOS)
        BW, BH = taban.size
        N = 22
        kareler = []
        for i in range(N):
            t = i / (N - 1)
            if stil == "kaydir":
                x = int((BW - W) * t)
                y = int((BH - H) / 2)
                kare = taban.crop((x, y, x + W, y + H))
            else:
                if stil == "nabiz":
                    z = 1.0 + 0.18 * math.sin(math.pi * t)
                elif stil == "sallan":
                    z = 1.12
                else:
                    z = 1.0 + 0.3 * t
                cw, ch = BW / z / 1.3 * 1.0, BH / z / 1.3 * 1.0
                src = taban
                if stil == "sallan":
                    src = taban.rotate(4 * math.sin(2 * math.pi * t), resample=Image.BICUBIC)
                    cw, ch = W / z * 1.0, H / z * 1.0
                    cw, ch = min(cw * 1.3, BW), min(ch * 1.3, BH)
                cx, cy = BW / 2, BH / 2
                kare = src.crop((int(cx - cw / 2), int(cy - ch / 2), int(cx + cw / 2), int(cy + ch / 2))).resize((W, H), Image.LANCZOS)
            kareler.append(kare.convert("P", palette=Image.ADAPTIVE, colors=128))
        if stil in ("zoom", "kaydir"):
            kareler = kareler + kareler[-2:0:-1]                  # git-gel: döngü yumuşak olsun
        tampon = io.BytesIO()
        kareler[0].save(tampon, format="GIF", save_all=True, append_images=kareler[1:], duration=65, loop=0, optimize=True)
        if tampon.tell() <= 7_500_000:                            # Discord dosya sınırı için güvenli boyut
            return tampon.getvalue(), None
    return None, "boyut"


def veo_video(tarif, anahtar, model):
    """Gemini API (Veo) ile GERÇEK video üretir (bloklayıcı, thread'de çalışır). (mp4_bayt, hata) döner."""
    import urllib.request
    import urllib.error
    taban = "https://generativelanguage.googleapis.com/v1beta"

    def istek(url, govde=None, bekle=60):
        r = urllib.request.Request(url, data=json.dumps(govde).encode("utf-8") if govde is not None else None,
                                   headers={"x-goog-api-key": anahtar, "Content-Type": "application/json"})
        with urllib.request.urlopen(r, timeout=bekle) as c:
            return c.read()
    try:
        yanit = json.loads(istek(f"{taban}/models/{model}:predictLongRunning", {"instances": [{"prompt": tarif}]}))
        isim = yanit["name"]
        for _ in range(40):                                        # en fazla ~6 dakika bekler
            time.sleep(9)
            d = json.loads(istek(f"{taban}/{isim}"))
            if d.get("done"):
                if "error" in d:
                    return None, "api"
                uri = d["response"]["generateVideoResponse"]["generatedSamples"][0]["video"]["uri"]
                return istek(uri, bekle=120), None
        return None, "zaman"
    except urllib.error.HTTPError as e:
        return None, f"http{e.code}"
    except Exception:
        return None, "hata"


