    # ------------------------------------------------------------------ video (hareketli GIF)
    @commands.hybrid_command(name="video", aliases=["gif", "hareket"], usage="[gif|zoom|kaydir|nabiz|sallan] <ne çizilsin>")
    @app_commands.describe(tarif="Ne çizilsin? Başına gif/zoom/kaydir/nabiz/sallan yazarsan hareketli GIF yapılır")
    @commands.guild_only()
    async def video(self, ctx, *, tarif: str):
        """🎬 PREMIUM: gerçek video (açıksa) ya da hareketli GIF üretir"""
        m = m20()
        if not m.vip_mi(ctx.guild.id, ctx.author.id):
            return await ctx.send("💎 Bu komut sadece PREMIUM (Beta) üyeler içindir. `td!premiumsatinal`")
        parca = tarif.strip().split(None, 1)
        stil, zorla_gif = "zoom", False
        if parca and parca[0].lower() in STILLER:
            stil, zorla_gif, tarif = parca[0].lower(), True, (parca[1] if len(parca) > 1 else "")
        elif parca and parca[0].lower() == "gif":
            zorla_gif, tarif = True, (parca[1] if len(parca) > 1 else "")
        tarif = tarif.strip()
        if len(tarif) < 3:
            return await ctx.send("❌ Ne çizeyim? Örnek: `td!video karlı dağlarda gün batımı` ya da `td!video kaydir karlı dağlar`")
        if len(tarif) > m.CIZ_MAX_HARF:
            return await ctx.send(f"❌ Tarif en fazla {m.CIZ_MAX_HARF} karakter olabilir.")
        anahtar = os.getenv("GEMINI_PREMIUM_KEY", "").strip() or os.getenv("GEMINI_KEY", "").strip()
        gercek = bool(VIDEO_GERCEK and anahtar and not zorla_gif and video_hak(ctx.author.id) > 0)
        if not VIDEO_LIMIT.dene(ctx.author.id):
            return await ctx.send(f"⏳ Video/GIF için {VIDEO_BEKLEME} saniyede bir istek yapabilirsin.")
        await ctx.defer()
        durum = await ctx.send("🎬 Video hazırlanıyor (1-5 dakika sürebilir)..." if gercek else f"🎞️ GIF hazırlanıyor ({STILLER[stil]})... (20-60 saniye)")
        m.PREMIUM_ISTEK.set(True)
        async with self.video_aktif:
            if gercek:
                mp4, vhata = None, "hata"
                try:
                    mp4, vhata = await asyncio.wait_for(asyncio.to_thread(veo_video, tarif, anahtar, VIDEO_MODEL), 420)
                except Exception as e:
                    print(f"video hatası: {gizle(repr(e))}")
                if mp4 and len(mp4) <= ctx.guild.filesize_limit:
                    video_hak_dus(ctx.author.id)
                    await ctx.send(f"🎬 **{tarif[:200]}**\n_PREMIUM • gerçek video • bugün {video_hak(ctx.author.id)} video hakkın kaldı_",
                                   file=discord.File(io.BytesIO(mp4), filename="video.mp4"), allowed_mentions=NO_PING)
                    try:
                        await durum.delete()
                    except discord.HTTPException:
                        pass
                    return
                try:
                    await durum.edit(content=f"⚠️ Gerçek video üretilemedi ({vhata if not mp4 else 'dosya çok büyük'}), hareketli GIF'e geçiyorum...")
                except discord.HTTPException:
                    pass
            try:
                bayt, hata, saglayici = await asyncio.wait_for(asyncio.to_thread(m.resim_uret, tarif), m.CIZ_ZAMAN_ASIMI)
            except asyncio.TimeoutError:
                bayt, hata, saglayici = None, "zaman", ""
            except Exception as e:
                print(f"video çizim hatası: {gizle(repr(e))}")
                bayt, hata, saglayici = None, type(e).__name__, ""
            gif, ghata = (None, None)
            if bayt:
                try:
                    gif, ghata = await asyncio.wait_for(asyncio.to_thread(gif_uret, bayt, stil), 90)
                except Exception as e:
                    print(f"gif hatası: {gizle(repr(e))}")
                    gif, ghata = None, "hata"
        if not gif:
            VIDEO_LIMIT.k.pop(ctx.author.id, None)                    # başarısız deneme bekleme koymasın
            yazi = (m.CIZ_HATA.get(hata, f"❌ Resim çizilemedi ({hata}).") if not bayt else
                    "❌ GIF için Pillow gerekli (`pip install pillow`)." if ghata == "pillow" else "❌ GIF hazırlanamadı, tekrar dene.")
            try:
                return await durum.edit(content=yazi)
            except discord.HTTPException:
                return await ctx.send(yazi)
        await ctx.send(f"🎞️ **{tarif[:200]}**\n_{saglayici} • {STILLER[stil]} stili • hareketli GIF_",
                       file=discord.File(io.BytesIO(gif), filename="hareket.gif"), allowed_mentions=NO_PING)
        try:
            await durum.delete()
        except discord.HTTPException:
            pass

