# ======================================================================
# Yapay zeka (Gemini) yardımcıları
# ======================================================================
def anahtar_sec(prem):
    return (G.get("GEMINI_PREMIUM_KEY") if prem else None) or G.get("GEMINI_KEY") or ""


def gemini_metin(istem, sistem, anahtar, parcalar=None):
    """Gemini generateContent (bloklayıcı, thread'de çalışır). (metin, hata) döner."""
    if not anahtar:
        return None, "anahtar yok"
    govde = {"system_instruction": {"parts": [{"text": sistem}]},
             "contents": [{"role": "user", "parts": [{"text": istem}] + (parcalar or [])}],
             "generationConfig": {"temperature": 0.3, "maxOutputTokens": 4096}}
    modeller = list(G.get("AI_MODELLER") or ["gemini-2.5-flash"])[:3]
    son = "hata"
    for model in modeller:
        r = urllib.request.Request(f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
                                   data=json.dumps(govde).encode("utf-8"),
                                   headers={"Content-Type": "application/json; charset=utf-8", "x-goog-api-key": anahtar})
        try:
            with urllib.request.urlopen(r, timeout=70) as c:
                d = json.loads(c.read())
            metin = "".join(p.get("text", "") for p in d["candidates"][0]["content"]["parts"])
            if metin.strip():
                return metin, None
            son = "boş cevap"
        except urllib.error.HTTPError as e:
            son = f"http{e.code}"
            if e.code not in (429, 500, 503):
                break
        except Exception:
            son = "hata"
    return None, son


DIL_TAKMA = {"py": "python", "js": "javascript", "node": "javascript", "c++": "cpp", "golang": "go"}


def dil_coz(d):
    d = (d or "python").lower()
    return DIL_TAKMA.get(d, d)


def kod_ayikla(metin):
    """Cevaptan (dil, kod, açıklama) çıkarır."""
    m = re.search(r"```([\w+#-]*)\n(.*?)```", metin, re.S)
    if not m:
        return "python", metin.strip(), ""
    dil = dil_coz(m.group(1))
    dil = dil if dil in DILLER else "python"
    return dil, m.group(2).rstrip(), metin[:m.start()].strip()[:600]


# ======================================================================
# Güvenli kod çalıştırma (sadece izole ortamda)
# ======================================================================
def piston(url, dil, kod):
    govde = {"language": DILLER[dil][1], "version": "*", "files": [{"content": kod}], "run_timeout": 5000, "compile_timeout": 10000}
    r = urllib.request.Request(url, data=json.dumps(govde).encode("utf-8"), headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(r, timeout=30) as c:
        d = json.loads(c.read())
    derle = (d.get("compile") or {}).get("output", "") if (d.get("compile") or {}).get("code") not in (0, None) else ""
    run = d.get("run") or {}
    cikti = derle + (run.get("output") or (run.get("stdout", "") + run.get("stderr", "")))
    return (cikti.strip()[:3000] or "(çıktı yok)") + (f"\n[çıkış kodu: {run.get('code')}]" if run.get("code") not in (0, None) else "")


def _limitler():
    import resource
    resource.setrlimit(resource.RLIMIT_CPU, (5, 5))
    resource.setrlimit(resource.RLIMIT_AS, (1024 * 2 ** 20, 1024 * 2 ** 20))
    resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 20, 2 ** 20))
    resource.setrlimit(resource.RLIMIT_NOFILE, (64, 64))


async def yerel_python(kod):
    """bubblewrap ile ağsız, salt-okunur, geçici dizinli sandbox'ta Python çalıştırır."""
    with tempfile.TemporaryDirectory() as dizin:
        with open(os.path.join(dizin, "main.py"), "w", encoding="utf-8") as f:
            f.write(kod)
        arg = ["bwrap", "--unshare-all", "--die-with-parent", "--new-session", "--proc", "/proc", "--dev", "/dev", "--tmpfs", "/tmp"]
        for d in ("/usr", "/bin", "/lib", "/lib64", "/sbin", "/etc/alternatives"):
            if os.path.islink(d):
                arg += ["--symlink", os.readlink(d), d]
            elif os.path.exists(d):
                arg += ["--ro-bind", d, d]
        arg += ["--ro-bind", dizin, "/work", "--chdir", "/work", "--clearenv", "--setenv", "PATH", "/usr/bin:/bin",
                "--setenv", "HOME", "/tmp", "/usr/bin/python3", "-I", "main.py"]
        proc = await asyncio.create_subprocess_exec(*arg, stdin=asyncio.subprocess.DEVNULL, stdout=asyncio.subprocess.PIPE,
                                                    stderr=asyncio.subprocess.STDOUT, preexec_fn=_limitler)
        zaman = False
        try:
            cikti = await asyncio.wait_for(proc.stdout.read(4000), 8)
        except asyncio.TimeoutError:
            cikti, zaman = b"", True
        finally:
            if proc.returncode is None:
                proc.kill()
            await proc.wait()
        yazi = cikti.decode("utf-8", "replace").strip()
        return (yazi or ("(8 saniye içinde bitmedi)" if zaman else "(çıktı yok)"))[:3000]


async def calistir(dil, kod):
    kod = kod[:20000]                                   # çok büyük kodlar sandbox'a gitmez
    url = os.getenv("PISTON_URL", "").strip()
    if url:
        if not url.startswith(("http://", "https://")):
            return "⛔ PISTON_URL geçersiz (http/https olmalı)."
        return await asyncio.to_thread(piston, url, dil, kod)
    if dil == "python" and os.getenv("KOD_YEREL", "").strip().lower() in ("1", "true", "evet") and shutil.which("bwrap"):
        return await yerel_python(kod)
    return ("⛔ Kod çalıştırma kapalı: güvenlik için sadece izole ortamda çalışır. Bot sahibi `PISTON_URL` (önerilen) ya da "
            "Linux'ta `KOD_YEREL=1` + bubblewrap (bwrap) ayarlamalı. Sözdizimi kontrolü için 🧪 butonunu kullan.")


