def kod_sayfalari(kod):
    sayfalar, parca = [], ""
    for satir in kod.split("\n"):
        if len(parca) + len(satir) + 1 > SAYFA_KARAKTER and parca:
            sayfalar.append(parca)
            parca = ""
        parca += satir[:300] + "\n"
    sayfalar.append(parca)
    return sayfalar


class KodDuzenleModal(discord.ui.Modal):
    def __init__(self, panel):
        super().__init__(title="✏️ Kodu düzenle", timeout=600)
        self.panel = panel
        self.kutu = discord.ui.TextInput(label="Kod", style=discord.TextStyle.paragraph, default=panel.kod[:4000], max_length=4000, required=True)
        self.add_item(self.kutu)

    async def on_submit(self, interaction):
        self.panel.kod, self.panel.sayfa = self.kutu.value, 0
        await interaction.response.edit_message(embed=self.panel.embed(), view=self.panel)

    async def on_error(self, interaction, error):
        print(f"v37 modal hatası: {gizle(repr(error))}")


class KodDegistirModal(discord.ui.Modal):
    def __init__(self, panel):
        super().__init__(title="🔁 Yapay zekayla değiştir", timeout=300)
        self.panel = panel
        self.kutu = discord.ui.TextInput(label="Ne değişsin / ne eklensin?", style=discord.TextStyle.paragraph, max_length=400, required=True)
        self.add_item(self.kutu)

    async def on_submit(self, interaction):
        p = self.panel
        if YASAK_KOD.search(self.kutu.value):
            return await interaction.response.send_message("⛔ Bu tür kodlar yazılmaz.", ephemeral=True)
        if not KOD_URET_LIMIT.dene(interaction.user.id):
            return await interaction.response.send_message("⏳ Birkaç saniye bekle.", ephemeral=True)
        await interaction.response.defer()
        istem = f"Mevcut kod ({p.dil}):\n```{p.dil}\n{p.kod[:6000]}\n```\nİstek: {self.kutu.value}\nKodun TAMAMINI güncellenmiş haliyle ver."
        metin, hata = await asyncio.to_thread(gemini_metin, istem, KOD_SISTEM, anahtar_sec(premium(p.gid, interaction.user.id)))
        if not metin:
            return await interaction.followup.send(f"❌ Yapay zeka şu an cevap veremedi ({hata}).", ephemeral=True)
        p.dil, p.kod, p.aciklama = kod_ayikla(metin)[0], kod_ayikla(metin)[1], kod_ayikla(metin)[2]
        p.sayfa, p.cikti = 0, ""
        p.dil_guncelle()
        await interaction.edit_original_response(embed=p.embed(), view=p)

    async def on_error(self, interaction, error):
        print(f"v37 modal hatası: {gizle(repr(error))}")


class KodCanvas(KilitliView):
    """Kod yaz / düzenle / çalıştır paneli. Sadece açan kişi kullanır; çalıştırma PREMIUM + izole ortam gerektirir."""

    def __init__(self, yazar, gid, dil, kod, aciklama=""):
        super().__init__(yazar.id, 900)
        self.gid, self.dil, self.kod, self.aciklama = gid, dil, kod, aciklama
        self.sayfa, self.cikti = 0, ""
        self.secim = discord.ui.Select(placeholder="🌐 Dil", row=1, options=[
            discord.SelectOption(label=v[0], value=k, default=(k == dil)) for k, v in DILLER.items()])
        self.secim.callback = self.dil_cb
        self.add_item(self.secim)

    def dil_guncelle(self):
        for o in self.secim.options:
            o.default = o.value == self.dil

    def embed(self):
        sayfalar = kod_sayfalari(self.kod)
        self.sayfa = max(0, min(self.sayfa, len(sayfalar) - 1))
        gorunen = sayfalar[self.sayfa].replace("```", "`\u200b``")
        e = discord.Embed(title=f"💻 Kod Canvas • {DILLER[self.dil][0]}", color=0x5865F2, description=f"```{self.dil}\n{gorunen}```")
        if self.aciklama:
            e.add_field(name="💬 Açıklama", value=self.aciklama[:500], inline=False)
        if self.cikti:
            e.add_field(name="▶️ Çıktı", value="```\n" + self.cikti[:900].replace("```", "`\u200b``") + "\n```", inline=False)
        e.set_footer(text=f"Sayfa {self.sayfa + 1}/{len(sayfalar)} • {len(self.kod)} karakter")
        return e

    async def dil_cb(self, interaction):
        v = self.secim.values[0]
        if v in DILLER:
            self.dil = v
            self.dil_guncelle()
        await interaction.response.edit_message(embed=self.embed(), view=self)

    async def sayfa_degistir(self, interaction, yeni):
        self.sayfa = yeni % len(kod_sayfalari(self.kod))
        await interaction.response.edit_message(embed=self.embed(), view=self)

    @discord.ui.button(emoji="◀️", style=discord.ButtonStyle.secondary, row=0)
    async def geri(self, interaction, button):
        await self.sayfa_degistir(interaction, self.sayfa - 1)

    @discord.ui.button(emoji="▶️", style=discord.ButtonStyle.secondary, row=0)
    async def ileri(self, interaction, button):
        await self.sayfa_degistir(interaction, self.sayfa + 1)

    @discord.ui.button(label="Düzenle", emoji="✏️", style=discord.ButtonStyle.primary, row=0)
    async def duzenle(self, interaction, button):
        await interaction.response.send_modal(KodDuzenleModal(self))

    @discord.ui.button(label="YZ ile değiştir", emoji="🔁", style=discord.ButtonStyle.primary, row=0)
    async def degistir(self, interaction, button):
        await interaction.response.send_modal(KodDegistirModal(self))

    @discord.ui.button(label="Çalıştır", emoji="▶️", style=discord.ButtonStyle.success, row=2)
    async def calistir_btn(self, interaction, button):
        if not premium(self.gid, interaction.user.id):
            return await interaction.response.send_message("💎 Kod çalıştırma sadece PREMIUM (Beta) üyeler içindir. `td!premiumsatinal`", ephemeral=True)
        if not KOD_CALISTIR_LIMIT.dene(interaction.user.id):
            return await interaction.response.send_message("⏳ Çalıştırmalar arasında 10 saniye bekle.", ephemeral=True)
        await interaction.response.defer()
        try:
            self.cikti = gizle(await asyncio.wait_for(calistir(self.dil, self.kod), 45))     # çıktıda sır varsa maskelenir
        except Exception as e:
            print(f"kod çalıştırma hatası: {gizle(repr(e))}")
            self.cikti = "❌ Çalıştırılamadı (zaman aşımı ya da sandbox hatası)."
        await interaction.edit_original_response(embed=self.embed(), view=self)

    @discord.ui.button(label="Kontrol", emoji="🧪", style=discord.ButtonStyle.secondary, row=2)
    async def kontrol(self, interaction, button):
        uyarilar = []
        if TOKEN_RE.search(self.kod):
            uyarilar.append("⚠️ Kodda **bot token'ı** var gibi görünüyor! Hemen sil, `os.getenv('DISCORD_TOKEN')` kullan.")
        if self.dil == "python":
            try:
                ast.parse(self.kod)
                uyarilar.append("✅ Python sözdizimi doğru.")
            except SyntaxError as e:
                uyarilar.append(f"❌ Sözdizimi hatası: satır {e.lineno}: {e.msg}")
        else:
            uyarilar.append("ℹ️ Sözdizimi kontrolü sadece Python için; diğer diller için ▶️ Çalıştır'ı kullan.")
        await interaction.response.send_message("\n".join(uyarilar), ephemeral=True)

    @discord.ui.button(label="Dosya", emoji="📎", style=discord.ButtonStyle.secondary, row=2)
    async def dosya(self, interaction, button):
        await interaction.response.send_message(file=discord.File(io.BytesIO(self.kod.encode("utf-8")), filename=f"kod.{DILLER[self.dil][2]}"), ephemeral=True)

    @discord.ui.button(label="Kapat", emoji="🗑️", style=discord.ButtonStyle.danger, row=2)
    async def kapat_btn(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(view=None)


