# 🤖 Bot profili paneli (sunucuya özel)
# ======================================================================
def resim_dogrula(bayt):
    if bayt[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if bayt[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if bayt[:4] == b"GIF8":
        return "image/gif"
    if bayt[:4] == b"RIFF" and bayt[8:12] == b"WEBP":
        return "image/webp"
    return None


def nick_temizle(m, n):
    return re.sub(r"\s+", " ", re.sub(r"[\x00-\x1f\x7f<>@`*_~|\\]", "", m or "")).strip()[:n]


class ProfilMetinModal(discord.ui.Modal):
    def __init__(self, panel, alan, baslik, etiket, en_cok, uzun=False):
        super().__init__(title=baslik[:45], timeout=300)
        self.panel, self.alan = panel, alan
        self.kutu = discord.ui.TextInput(label=etiket[:45], max_length=en_cok, required=False,
                                         style=discord.TextStyle.paragraph if uzun else discord.TextStyle.short)
        self.add_item(self.kutu)

    async def on_submit(self, interaction):
        deger = nick_temizle(self.kutu.value, 32 if self.alan == "nick" else 190)
        if re.search(r"discord|clyde|everyone|here", deger, re.I):                    # taklitçilik/aldatma engeli
            return await interaction.response.send_message("❌ Bu ad/yazı kullanılamaz (Discord ya da yetkili taklidi gibi görünüyor).", ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        await self.panel.yama(interaction, **{self.alan: deger or None})

    async def on_error(self, interaction, error):
        print(f"v37 modal hatası: {gizle(repr(error))}")


class BotProfilPanel(KilitliView):
    """PREMIUM + Sunucuyu Yönet: botun bu sunucudaki görünümü (Discord'un sunucuya özel bot profili özelliği)."""

    def __init__(self, bot, guild, yazar_id):
        super().__init__(yazar_id, 600)
        self.bot, self.guild = bot, guild

    async def interaction_check(self, interaction):
        if not await super().interaction_check(interaction):
            return False
        if not interaction.user.guild_permissions.manage_guild or not premium(self.guild.id, interaction.user.id):
            await interaction.response.send_message("💎 Bunun için PREMIUM (Beta) üyelik ve **Sunucuyu Yönet** yetkisi gerekir.", ephemeral=True)
            return False
        return True

    def embed(self):
        me = self.guild.me
        e = discord.Embed(title="🤖 Bot profili (bu sunucuda)", color=0xF1C40F,
                          description="Botun **sadece bu sunucudaki** adı, avatarı, banner'ı ve hakkında yazısı değişir; diğer sunucular etkilenmez.")
        e.add_field(name="Ad", value=me.nick or me.name, inline=True)
        e.set_thumbnail(url=(me.guild_avatar or me.display_avatar).url)
        return e

    async def yama(self, interaction, **alanlar):
        if not PROFIL_LIMIT.dene(self.guild.id):
            return await interaction.followup.send("⏳ Profil değişikliği çok sık yapıldı (Discord sınırı), birkaç dakika bekle.", ephemeral=True)
        try:
            await self.bot.http.request(discord.http.Route("PATCH", "/guilds/{guild_id}/members/@me", guild_id=self.guild.id), json=alanlar)
        except discord.HTTPException as e:
            return await interaction.followup.send(f"❌ Discord reddetti: `{str(e)[:150]}`", ephemeral=True)
        asyncio.create_task(self._log(interaction))
        await interaction.followup.send("✅ Bot profili güncellendi!", ephemeral=True)
        try:
            await interaction.message.edit(embed=self.embed(), view=self)
        except discord.HTTPException:
            pass

    async def _log(self, interaction):
        c = log_yaz(self.guild, "🤖 Bot profili değişti", f"{interaction.user.mention} botun sunucudaki profilini güncelledi.")
        if c is not None:
            try:
                await c
            except Exception:
                pass

    async def resim_iste(self, interaction, alan):
        await interaction.response.send_message("📎 **60 saniye içinde** bu kanala bir resim yükle (PNG/JPG/GIF/WEBP, en fazla 4 MB).", ephemeral=True)
        try:
            msg = await self.bot.wait_for("message", timeout=60, check=lambda m: m.author.id == interaction.user.id
                                          and m.channel.id == interaction.channel_id and m.attachments)
        except asyncio.TimeoutError:
            return await interaction.followup.send("⌛ Süre doldu.", ephemeral=True)
        att = msg.attachments[0]
        if att.size > 4_000_000:
            return await interaction.followup.send("❌ Resim 4 MB'tan büyük.", ephemeral=True)
        bayt = await att.read()
        tip = resim_dogrula(bayt)
        if tip is None:
            return await interaction.followup.send("❌ Geçerli bir PNG/JPG/GIF/WEBP resmi değil.", ephemeral=True)
        try:
            await msg.delete()
        except discord.HTTPException:
            pass
        await self.yama(interaction, **{alan: f"data:{tip};base64," + base64.b64encode(bayt).decode()})

    @discord.ui.button(label="İsim", emoji="🏷️", style=discord.ButtonStyle.primary, row=0)
    async def isim(self, interaction, button):
        await interaction.response.send_modal(ProfilMetinModal(self, "nick", "Botun sunucudaki adı", "Yeni ad (boş = sıfırla)", 32))

    @discord.ui.button(label="Avatar", emoji="🖼️", style=discord.ButtonStyle.primary, row=0)
    async def avatar(self, interaction, button):
        await self.resim_iste(interaction, "avatar")

    @discord.ui.button(label="Banner", emoji="🎌", style=discord.ButtonStyle.primary, row=0)
    async def banner(self, interaction, button):
        await self.resim_iste(interaction, "banner")

    @discord.ui.button(label="Hakkında", emoji="📝", style=discord.ButtonStyle.primary, row=0)
    async def hakkinda(self, interaction, button):
        await interaction.response.send_modal(ProfilMetinModal(self, "bio", "Botun hakkında yazısı", "Hakkında (boş = sıfırla)", 190, uzun=True))

    @discord.ui.button(label="Sıfırla", emoji="♻️", style=discord.ButtonStyle.danger, row=1)
    async def sifirla(self, interaction, button):
        await interaction.response.defer(ephemeral=True)
        await self.yama(interaction, nick=None, avatar=None, banner=None, bio=None)

    @discord.ui.button(label="Kapat", emoji="✖️", style=discord.ButtonStyle.secondary, row=1)
    async def kapat_btn(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(view=None)


