class V37(commands.Cog):
    def __init__(self, bot):
        self.bot = bot

    # ------------------------------------------------------------------ TTS / STT
    @commands.hybrid_command(name="konus", aliases=["tts", "seslendir"], usage="[kadin|erkek] <metin>")
    @app_commands.describe(metin="Seslendirilecek yazı (başına kadin/erkek yazabilirsin)")
    @commands.guild_only()
    async def konus(self, ctx, *, metin: str):
        """🗣️ Yazıyı sese çevirir (TTS) ve mp3 olarak gönderir"""
        prem = premium(ctx.guild.id, ctx.author.id)
        sinir = TTS_LIMIT_PREMIUM if prem else TTS_LIMIT
        parca = metin.strip().split(None, 1)
        ses = SESLER["kadin"]
        if parca and parca[0].lower() in SESLER:
            ses, metin = SESLER[parca[0].lower()], (parca[1] if len(parca) > 1 else "")
        metin = re.sub(r"<[@#:][^>]+>|https?://\S+", "", metin).strip()               # etiket/emoji/link okunmasın
        en_cok = 1500 if prem else 500
        if len(metin) < 2:
            return await ctx.send("❌ Seslendirilecek bir yazı yaz. Örnek: `td!konus erkek Merhaba millet!`")
        if len(metin) > en_cok:
            return await ctx.send(f"❌ En fazla {en_cok} karakter" + ("" if prem else " (PREMIUM'da 1500)") + ".")
        if not sinir.dene(ctx.author.id):
            return await ctx.send("⏳ Çok sık seslendirme yapıyorsun, biraz bekle." + ("" if prem else " (PREMIUM'da sınır daha geniş)"))
        await ctx.defer()
        bayt, hata = None, None
        try:
            import edge_tts
            tampon = bytearray()
            async for p in edge_tts.Communicate(metin, ses).stream():
                if p["type"] == "audio":
                    tampon += p["data"]
            bayt = bytes(tampon)
        except ImportError:
            try:
                from gtts import gTTS

                def gtts_uret():
                    fp = io.BytesIO()
                    gTTS(text=metin, lang="tr").write_to_fp(fp)
                    return fp.getvalue()
                bayt = await asyncio.to_thread(gtts_uret)
            except ImportError:
                hata = "TTS kütüphanesi yok: `pip install edge-tts` (ya da `pip install gTTS`)"
            except Exception as e:
                hata = "seslendirme hatası"
                print(f"gTTS hatası: {gizle(repr(e))}")
        except Exception as e:
            hata = "seslendirme hatası"
            print(f"edge-tts hatası: {gizle(repr(e))}")
        if not bayt:
            return await ctx.send(f"❌ {hata or 'Ses üretilemedi.'}")
        if len(bayt) > ctx.guild.filesize_limit:
            return await ctx.send("❌ Ses dosyası bu sunucunun dosya sınırını aşıyor, metni kısalt.")
        await ctx.send("🗣️ Hazır!", file=discord.File(io.BytesIO(bayt), filename="konusma.mp3"))

    @commands.command(name="yaziyacevir", aliases=["stt", "transkript", "sesyazi"])
    @commands.guild_only()
    async def yaziyacevir(self, ctx):
        """🎙️ Ses kaydını yazıya çevirir (STT): ses dosyası/sesli mesaj ekle ya da birine yanıt ver"""
        ek = None
        for kaynak in (ctx.message, getattr(ctx.message.reference, "resolved", None)):
            if isinstance(kaynak, discord.Message):
                for a in kaynak.attachments:
                    if (a.content_type or "").startswith(("audio", "video/ogg")) or a.filename.lower().endswith((".ogg", ".mp3", ".wav", ".m4a", ".flac", ".aac", ".opus")):
                        ek = a
                        break
            if ek:
                break
        if ek is None:
            return await ctx.send("🎙️ Bir **ses dosyası / sesli mesaj** ekleyerek bu komutu yaz, ya da ses içeren bir mesaja **yanıt (reply)** vererek yaz.")
        if ek.size > 15_000_000:
            return await ctx.send("❌ Ses dosyası 15 MB'tan büyük.")
        if not STT_LIMIT.dene(ctx.author.id):
            return await ctx.send("⏳ Birkaç saniye bekle.")
        prem = premium(ctx.guild.id, ctx.author.id)
        bugun = time.strftime("%Y-%m-%d")
        gun, adet = veri["stt_hak"].get(str(ctx.author.id), ["", 0])
        adet = adet if gun == bugun else 0
        if not prem and adet >= UCRETSIZ_STT_GUNLUK:
            return await ctx.send(f"💎 Günlük {UCRETSIZ_STT_GUNLUK} ücretsiz ses çevirme hakkını kullandın. PREMIUM (Beta) ile sınırsız.")
        veri["stt_hak"][str(ctx.author.id)] = [bugun, adet + 1]
        kaydet()
        durum = await ctx.send("🎙️ Dinliyorum...")
        bayt = await ek.read()
        mime = (ek.content_type or "").split(";")[0] or "audio/ogg"
        if not mime.startswith(("audio", "video/ogg")):
            mime = {"mp3": "audio/mp3", "wav": "audio/wav", "m4a": "audio/mp4", "flac": "audio/flac", "aac": "audio/aac"}.get(ek.filename.rsplit(".", 1)[-1].lower(), "audio/ogg")
        parcalar = [{"inline_data": {"mime_type": "audio/ogg" if mime == "video/ogg" else mime, "data": base64.b64encode(bayt).decode()}}]
        metin, hata = await asyncio.to_thread(
            gemini_metin, "Bu ses kaydını kelimesi kelimesine yazıya dök. Konuşma dili neyse o dilde yaz. Sadece transkripti ver, yorum ekleme.",
            "Sen bir ses-yazı çeviri aracısın. Sadece duyduğunu yaz.", anahtar_sec(premium(ctx.guild.id, ctx.author.id)), parcalar)
        if not metin:
            return await durum.edit(content=f"❌ Ses yazıya çevrilemedi ({hata}).")
        e = discord.Embed(title="🎙️ Ses → Yazı", description=discord.utils.escape_mentions(metin.strip())[:4000], color=0x5865F2)
        await durum.edit(content=None, embed=e)

