# Gerçek oyunlar: durumda "Minecraft oynuyor" gibi çıkar, yanında süre sayacı hiç sıfırlanmadan hep ilerler
OYUN_LISTESI = ["Minecraft", "Roblox", "Valorant", "Fortnite", "Counter-Strike 2", "League of Legends",
                "GTA V", "Rocket League", "Apex Legends", "Among Us"]
BOT_ACIKLAMA = '🤖 THEDLAX-BOT: sunucunu tek botla yönet! 🛡️ moderasyon ve koruma • 💰 ekonomi, balık, maden, düello • 🧠 yapay zekâ sohbet ve çizim • 🎫 bilet ve ModMail • 📝 kayıt ve doğrulama • 🏷️ rol menüsü • 📜 detaylı log • 🧩 hazır sunucu şablonları. Komutlar için td!yardim yaz. Kodlayan: TheDlax'


def durum_kaydi():
    d = veri["durum"]
    d.setdefault("liste", [])
    d.setdefault("sure", 5)
    d.setdefault("sabit", None)
    d.setdefault("mod", "online")
    d.setdefault("sira", 0)
    d.setdefault("baslangic", {})
    if not d.get("oyunlar_eklendi"):               # ilk açılışta liste boşsa gerçek oyunları koy
        d["oyunlar_eklendi"] = True
        if not d["liste"]:
            d["liste"] = [{"tur": "oynuyor", "metin": o} for o in OYUN_LISTESI]
            isaretle25()
    return d


def oyun_baslangic(d, ad):
    """Oyunun başlangıç zamanı (ms). Bir kez belirlenir ve kaydedilir; sayaç hiç sıfırlanmaz, hep ilerler."""
    b = d.setdefault("baslangic", {})
    if ad not in b:
        b[ad] = int((time.time() - random.randint(20 * 60, 4 * 3600)) * 1000)
        isaretle25()
    return int(b[ad])


def durum_metni(bot, metin):
    return (metin.replace("{sunucu}", str(len(bot.guilds)))
                 .replace("{uye}", str(sum(g.member_count or 0 for g in bot.guilds)))
                 .replace("{ping}", str(round(bot.latency * 1000)))
                 .replace("{surum}", str(G.get("SURUM", "?"))))[:128]


async def durum_uygula(bot, ozel_index=None):
    d = durum_kaydi()
    liste = d["liste"]
    mod = {"online": discord.Status.online, "idle": discord.Status.idle, "dnd": discord.Status.dnd,
           "invisible": discord.Status.invisible}.get(d["mod"], discord.Status.online)
    if not liste:
        await bot.change_presence(status=mod, activity=None)
        return None
    if ozel_index is not None:
        i = ozel_index
    elif d["sabit"] is not None and d["sabit"] < len(liste):
        i = d["sabit"]
    else:
        i = d["sira"] % len(liste)
        d["sira"] = (i + 1) % len(liste)
    k = liste[i]
    metin = durum_metni(bot, k["metin"])
    if k["tur"] in ("ozel", "özel", "balon"):          # profil resminin yanındaki balon (özel durum)
        akt = discord.CustomActivity(name=metin)
    elif k["tur"] == "oynuyor":                         # oyun gibi: süre sayacı hep ilerler
        akt = discord.Activity(type=discord.ActivityType.playing, name=metin,
                               timestamps={"start": oyun_baslangic(d, k["metin"])})
    else:
        akt = discord.Activity(type=TURLER.get(k["tur"], discord.ActivityType.playing), name=metin)
    await bot.change_presence(status=mod, activity=akt)
    return k


