        kaydet()
        if kanal:
            await ctx.send(f"✅ Hata raporları artık {kanal.mention} kanalına gelecek. (İstersen ortam değişkeni: `HATA_KANAL={kanal.id}`)")
        else:
            await ctx.send("✅ Hata kanalı kapatıldı. Raporlar bot sahibine DM olarak gelir.")

