# ======================================================================
class SunucuSec(discord.ui.View):
    def __init__(self, cog, mesaj, sunucular):
        super().__init__(timeout=120)
        self.cog, self.mesaj = cog, mesaj
        sec = discord.ui.Select(placeholder="Sunucu seç...", options=[
            discord.SelectOption(label=g.name[:100], value=str(g.id)) for g in sunucular[:25]])
        sec.callback = self.sec
        self.add_item(sec)

    async def sec(self, interaction):
        g = self.cog.bot.get_guild(int(interaction.data["values"][0]))
        await interaction.response.edit_message(content="⏳ İletiliyor...", view=None)
        if g is not None:
            await self.cog.ac(self.mesaj, g)


def mm_d(g):
    """Sunucunun ModMail ayarları (eksik alanlar doldurulur)."""
    d = sg(g.id)["mm"]
    d.setdefault("alicilar", [])          # ek yetkililer (DM alacak kişiler)
    d.setdefault("dm_map", {})            # yetkiliye giden DM mesajı -> konuşulan üye (yanıtla cevap verebilsin)
    d.setdefault("gecmis", {})            # üye -> konuşma dökümü (kapanınca log'a gider)
    d.setdefault("kuruldu", False)
    sn = int(time.time())
    for k, v in list(d["kanallar"].items()):
        if v > 10 ** 11:                  # eski sürümde kanal numarasıydı: artık son yazma zamanı
            d["kanallar"][k] = sn
    return d


def mm_alicilar(g):
    """ModMail DM'lerini alacaklar: sunucu sahibi + eklenen yetkililer + (varsa) yetkili rol üyeleri."""
    d = mm_d(g)
    ids = [g.owner_id] + list(d["alicilar"])
    rol = g.get_role(d["rol"]) if d["rol"] else None
    if rol is not None:
        ids += [m.id for m in rol.members if not m.bot]
    return list(dict.fromkeys(i for i in ids if i))[:15]


def mm_yetkili(g, uid):
    if uid in mm_alicilar(g):
        return True
    uye = g.get_member(uid)
    return bool(uye and uye.guild_permissions.manage_messages)


class MMButon(discord.ui.DynamicItem[discord.ui.Button], template=r"td26m:(?P<i>cevap|kapat|engel):(?P<g>\d+):(?P<u>\d+)"):
    ETIKET = {"cevap": ("Cevapla", "↩️", discord.ButtonStyle.primary),
              "kapat": ("Kapat", "🔒", discord.ButtonStyle.secondary),
              "engel": ("Engelle", "🚫", discord.ButtonStyle.danger)}

    def __init__(self, islem, gid, uid):
        etiket, emoji, stil = self.ETIKET[islem]
        super().__init__(discord.ui.Button(label=etiket, emoji=emoji, style=stil, custom_id=f"td26m:{islem}:{gid}:{uid}"))
        self.islem, self.gid, self.uid = islem, gid, uid

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["i"], int(match["g"]), int(match["u"]))

    async def callback(self, interaction):
        cog = interaction.client.get_cog("ModMail26")
        try:
            if cog is None:
                return await interaction.response.send_message("❌ ModMail şu an çalışmıyor.", ephemeral=True)
            await cog.buton(interaction, self.islem, self.gid, self.uid)
        except Exception as e:
            await hata(interaction.client, e, "modmail")
            try:
                if interaction.response.is_done():
                    await interaction.followup.send("❌ Bir hata oldu, tekrar dene.")
                else:
                    await interaction.response.send_message("❌ Bir hata oldu, tekrar dene.")
            except discord.HTTPException:
                pass


def mm_gorunum(gid, uid):
    v = discord.ui.View(timeout=None)
    for islem in ("cevap", "kapat", "engel"):
        v.add_item(MMButon(islem, gid, uid))
    return v


class MMCevapModal(discord.ui.Modal):
    def __init__(self, cog, gid, uid):
        super().__init__(title="↩️ ModMail cevabı", timeout=900)
        self.cog, self.gid, self.uid = cog, gid, uid
        self.kutu = discord.ui.TextInput(label="Cevabın", style=discord.TextStyle.paragraph, max_length=1800, required=True,
                                         placeholder="Yazdığın mesaj üyeye DM olarak gider")
        self.add_item(self.kutu)

    async def on_submit(self, interaction):
        await interaction.response.defer()
        g = self.cog.bot.get_guild(self.gid)
        if g is None:
            return await interaction.followup.send("❌ Sunucuyu bulamadım.")
        ok, mesaj = await self.cog.cevapla(g, interaction.user, self.uid, self.kutu.value)
        await interaction.followup.send("✅ Cevabın üyeye gönderildi." if ok else mesaj)

    async def on_error(self, interaction, error):
        await hata(interaction.client, error, "modmail")


class MailCog(commands.Cog, name="ModMail26"):
    """ModMail: üye bota DM atar -> mesaj yetkililere DM olarak gelir. Cevap: mesaja yanıt ver ya da ↩️ Cevapla butonu."""

    def __init__(self, bot):
        self.bot = bot
        self.son_acma = {}
        self.mesaj_zamanlari = {}      # flood koruması: kişi başı 30 sn'de en fazla 8 DM

    @commands.Cog.listener()
    async def on_message(self, m):
        if m.author.bot or m.guild is not None:
            return
        try:
            await self.dm_geldi(m)
        except Exception as e:
            await hata(self.bot, e, "modmail")

    async def kisi_getir(self, g, uid):
        uye = g.get_member(uid)
        if uye is not None:
            return uye
        try:
            return await self.bot.fetch_user(uid)
        except discord.HTTPException:
            return None

    async def dm_geldi(self, m):
        if (m.content or "").lower().startswith(prefixler()):
            return
        simdi = time.time()
        zamanlar = [t for t in self.mesaj_zamanlari.get(m.author.id, []) if simdi - t < 30]
        if len(zamanlar) >= 8:                                   # yetkililerin DM kutusunu doldurmaya karşı
            self.mesaj_zamanlari[m.author.id] = zamanlar
            return
        zamanlar.append(simdi)
        self.mesaj_zamanlari[m.author.id] = zamanlar
        # 1) Yetkili, ona gelen ModMail mesajına yanıt veriyorsa -> üyeye iletilir
        if m.reference and m.reference.message_id:
            ref = str(m.reference.message_id)
            for g in self.bot.guilds:
                uid = mm_d(g)["dm_map"].get(ref)
                if uid is None:
                    continue
                if not mm_yetkili(g, m.author.id):
                    return await m.channel.send("❌ Bu konuşmaya cevap verme yetkin yok.")
                ok, mesaj = await self.cevapla(g, m.author, int(uid), m.content, m.attachments)
                if not ok:
                    await m.channel.send(mesaj)
                return
        # 2) Normal üye mesajı
        adaylar = []
        for g in self.bot.guilds:
            d = mm_d(g)
            if d["acik"] and g.get_member(m.author.id) and m.author.id not in d["engel"] and m.author.id not in mm_alicilar(g):
                adaylar.append(g)
        if not adaylar:
            return
        for g in adaylar:
            son = mm_d(g)["kanallar"].get(str(m.author.id))
            if son and time.time() - son < 86400:                 # devam eden konuşma
                return await self.ilet(m, g)
        if len(adaylar) == 1:
            return await self.ac(m, adaylar[0])
        await m.channel.send("📨 Hangi sunucunun yetkililerine yazmak istiyorsun?", view=SunucuSec(self, m, adaylar))

    async def ilet(self, m, g, acilis=False):
        """Üyenin mesajını yetkililere DM olarak yollar. Kaç kişiye gittiğini döndürür (boş mesajsa None)."""
        if not m.content and not m.attachments:
            return None
        d = mm_d(g)
        e = discord.Embed(description=kisa(m.content, 3900) or None, color=0x5865F2, timestamp=discord.utils.utcnow())
        e.set_author(name=f"{m.author} • {g.name}", icon_url=m.author.display_avatar.url)
        if acilis:
            uye = g.get_member(m.author.id)
            e.title = "📨 Yeni ModMail"
            e.add_field(name="Kullanıcı", value=f"{m.author.mention} ({m.author})\nID: `{m.author.id}`", inline=False)
            e.add_field(name="Hesap", value=discord.utils.format_dt(m.author.created_at, "R"), inline=True)
            if uye and uye.joined_at:
                e.add_field(name="Katılma", value=discord.utils.format_dt(uye.joined_at, "R"), inline=True)
            e.set_thumbnail(url=m.author.display_avatar.url)
        if m.attachments:
            e.add_field(name="Dosyalar", value="\n".join(a.url for a in m.attachments)[:1000], inline=False)
        e.set_footer(text="↩️ Cevapla butonuna bas ya da bu mesaja Discord'dan yanıt (reply) ver")
        gonderilen = 0
        for uid in mm_alicilar(g):
            kisi = await self.kisi_getir(g, uid)
            if kisi is None:
                continue
            try:
                msg = await kisi.send(embed=e, view=mm_gorunum(g.id, m.author.id))
            except discord.HTTPException:
                continue
            d["dm_map"][str(msg.id)] = m.author.id
            gonderilen += 1
        while len(d["dm_map"]) > 800:
            d["dm_map"].pop(next(iter(d["dm_map"])))
        if gonderilen:
            gm = d["gecmis"].setdefault(str(m.author.id), [])
            gm.append([int(time.time()), f"{m.author}", (m.content or "")[:500] + (" [dosya]" if m.attachments else "")])
            del gm[:-200]
            d["kanallar"][str(m.author.id)] = int(time.time())
            isaretle26()
            kaydet()
        return gonderilen

    async def ac(self, m, g):
        simdi = time.time()
        if simdi - self.son_acma.get(m.author.id, 0) < 30:
            return await m.channel.send("⏳ Biraz yavaş, birkaç saniye sonra tekrar yaz.")
        self.son_acma[m.author.id] = simdi
        n = await self.ilet(m, g, acilis=True)
        if n is None:
            return
        if n == 0:
            return await m.channel.send("❌ Şu an yetkililere ulaşamadım, sonra tekrar dene.")
        await log26(g, "mm", "📨 ModMail açıldı", f"{m.author.mention} → {n} yetkiliye DM gitti", 0x5865F2)

    async def cevapla(self, g, yetkili, uid, metin, dosyalar=()):
        """Yetkilinin cevabını üyeye DM atar. (başarılı_mı, hata_metni) döndürür."""
        metin = (metin or "").strip()
        if not metin and not dosyalar:
            return False, "❌ Boş mesaj gönderemem."
        d = mm_d(g)
        kisi = await self.kisi_getir(g, uid)
        if kisi is None:
            return False, "❌ Kullanıcıyı bulamadım."
        e = discord.Embed(description=kisa(metin, 3900) or None, color=0x57F287, timestamp=discord.utils.utcnow())
        e.set_author(name=f"{g.name} • {yetkili.display_name}", icon_url=g.icon.url if g.icon else None)
        if dosyalar:
            e.add_field(name="Dosyalar", value="\n".join(a.url for a in dosyalar)[:1000], inline=False)
        try:
            await kisi.send(embed=e)
        except discord.HTTPException:
            return False, "❌ Kullanıcıya DM atılamadı (DM'leri kapalı ya da sunucudan ayrılmış olabilir)."
        gm = d["gecmis"].setdefault(str(uid), [])
        gm.append([int(time.time()), f"yetkili {yetkili}", metin[:500]])
        del gm[:-200]
        d["kanallar"][str(uid)] = int(time.time())
        # diğer yetkililer de cevabı görsün (ve onlar da yanıtlayabilsin)
        bilgi = discord.Embed(title=f"↩️ {yetkili.display_name} cevapladı → {kisi}", description=kisa(metin, 3500) or None, color=0x57F287)
        for rid in mm_alicilar(g):
            if rid == yetkili.id:
                continue
            diger = await self.kisi_getir(g, rid)
            if diger is None:
                continue
            try:
                msg = await diger.send(embed=bilgi, view=mm_gorunum(g.id, uid))
                d["dm_map"][str(msg.id)] = uid
            except discord.HTTPException:
                pass
        isaretle26()
        kaydet()
        return True, None

    async def kapat(self, g, uid, kapatan, sebep="Konuşma tamamlandı"):
        d = mm_d(g)
        gm = d["gecmis"].pop(str(uid), [])
        d["kanallar"].pop(str(uid), None)
        isaretle26()
        kaydet()
        if gm:
            satir = [f"[{time.strftime('%d.%m %H:%M', time.localtime(t))}] {kim}: {ic}" for t, kim, ic in gm]
            dosya = discord.File(io.BytesIO("\n".join(satir).encode("utf-8")), filename=f"modmail-{uid}.txt")
            lk = log_kanali(g, "mm")
            if lk is not None:
                try:
                    await lk.send(embed=discord.Embed(title="📨 ModMail kapandı", description=f"<@{uid}> • kapatan {kapatan.mention}\nSebep: {sebep}", color=0xED4245),
                                  file=dosya, allowed_mentions=NO_PING)
                except discord.HTTPException:
                    pass
        kisi = await self.kisi_getir(g, uid)
        if kisi is not None:
            try:
                await kisi.send(embed=discord.Embed(title="📨 Konuşma kapatıldı", description=f"**{g.name}** yetkilileri konuşmayı kapattı.\nSebep: {sebep}\nTekrar yazarsan yeni konuşma açılır.", color=0xED4245))
            except discord.HTTPException:
                pass

    async def buton(self, interaction, islem, gid, uid):
        g = self.bot.get_guild(gid)
        if g is None:
            return await interaction.response.send_message("❌ Sunucuyu bulamadım.")
        if not mm_yetkili(g, interaction.user.id):
            return await interaction.response.send_message("❌ Bunun için yetkin yok.", ephemeral=True)
        if islem == "cevap":
            return await interaction.response.send_modal(MMCevapModal(self, gid, uid))
        await interaction.response.defer()
        if islem == "kapat":
            await self.kapat(g, uid, interaction.user)
            await interaction.followup.send("🔒 Konuşma kapatıldı.")
        else:
            d = mm_d(g)
            if uid not in d["engel"]:
                d["engel"].append(uid)
            await self.kapat(g, uid, interaction.user, "ModMail'den engellendi")
            await interaction.followup.send("🚫 Kullanıcı engellendi ve konuşma kapatıldı.")

    @commands.command(name="modmailkur", aliases=["mmkur"], usage="[@rol]")
    @commands.guild_only()
    async def modmailkur(self, ctx, kategori: Optional[discord.CategoryChannel] = None, rol: Optional[discord.Role] = None):
        """ModMail'i aç: üyenin bota attığı DM, sunucu sahibine (ve istersen bir role) DM olarak gelir (yönetici)"""
        if not await yetkili_mi(ctx, "administrator"):
            return await ctx.send("❌ Bunun için yönetici olmalısın.")
        d = mm_d(ctx.guild)
        d["acik"], d["kuruldu"] = True, True
        if rol:
            d["rol"] = rol.id
        isaretle26()
        kaydet()
        alicilar = " ".join(f"<@{u}>" for u in mm_alicilar(ctx.guild))
        await ctx.send("✅ **ModMail açık.** Üyeler bana **DM** atınca mesaj yetkililere **DM olarak** gelir.\n"
                       f"📬 Alıcılar: {alicilar}\n"
                       "↩️ Cevap vermek için gelen mesaja **yanıt (reply)** ver ya da **Cevapla** butonuna bas.\n"
                       "➕ Alıcı eklemek için `td!mmyetkili @kişi`, bir rolün hepsi alsın istersen `td!modmailkur @rol`.",
                       allowed_mentions=NO_PING)

    @commands.command(name="mmyetkili", usage="[@kişi]")
    @commands.guild_only()
    async def mmyetkili(self, ctx, uye: Optional[discord.Member] = None):
        """ModMail DM'lerini alacak kişiyi ekle/çıkar (yönetici). Sunucu sahibi her zaman alır"""
        if not await yetkili_mi(ctx, "administrator"):
            return await ctx.send("❌ Bunun için yönetici olmalısın.")
        d = mm_d(ctx.guild)
        if uye is not None:
            if uye.bot:
                return await ctx.send("❌ Bot alıcı olamaz.")
            if uye.id == ctx.guild.owner_id:
                return await ctx.send("ℹ️ Sunucu sahibi zaten her zaman alır.")
            if uye.id in d["alicilar"]:
                d["alicilar"].remove(uye.id)
            else:
                d["alicilar"].append(uye.id)
            isaretle26()
            kaydet()
        rol = ctx.guild.get_role(d["rol"]) if d["rol"] else None
        await ctx.send("📬 **ModMail alıcıları:** " + " ".join(f"<@{u}>" for u in mm_alicilar(ctx.guild))
                       + (f"\n🏷️ Rol: {rol.mention} (üyeleri de alır)" if rol else "")
                       + "\n`td!mmyetkili @kişi` ekler/çıkarır", allowed_mentions=NO_PING)

    @commands.command(name="modmail", usage="ac | kapat")
    @commands.guild_only()
    async def modmail(self, ctx, islem: str = ""):
        """ModMail'i aç/kapat (yönetici)"""
        if not await yetkili_mi(ctx, "administrator"):
            return await ctx.send("❌ Bunun için yönetici olmalısın.")
        d = mm_d(ctx.guild)
        d["acik"] = islem.lower() in ("ac", "aç", "on") if islem else not d["acik"]
        isaretle26()
        kaydet()
        await ctx.send("🟢 ModMail açıldı" if d["acik"] else "🔴 ModMail kapatıldı")

    @commands.command(name="mmkapat", aliases=["mailkapat"], usage="[@kişi] [sebep]")
    @commands.guild_only()
    async def mmkapat(self, ctx, uye: Optional[discord.User] = None, *, sebep: str = "Konuşma tamamlandı"):
        """Bir ModMail konuşmasını kapat (döküm log'a gider). Kişi yazmazsan açık konuşmalar listelenir"""
        if not await yetkili_mi(ctx, "manage_messages"):
            return await ctx.send("❌ Yetkin yok.")
        d = mm_d(ctx.guild)
        if uye is None:
            if not d["kanallar"]:
                return await ctx.send("📨 Açık ModMail konuşması yok.")
            return await ctx.send("📨 **Açık konuşmalar:** " + " ".join(f"<@{u}>" for u in d["kanallar"])
                                  + "\nKapatmak için `td!mmkapat @kişi [sebep]` (ya da DM'deki 🔒 butonu)", allowed_mentions=NO_PING)
        if str(uye.id) not in d["kanallar"]:
            return await ctx.send("❌ Bu kişiyle açık bir ModMail konuşması yok.")
        await self.kapat(ctx.guild, uye.id, ctx.author, sebep)
        await ctx.send(f"🔒 **{uye}** ile ModMail konuşması kapatıldı.")

    @commands.command(name="mmengel", usage="@kişi")
    @commands.guild_only()
    async def mmengel(self, ctx, uye: discord.Member):
        """Birini ModMail'den engelle (yetkili)"""
        if not await yetkili_mi(ctx, "manage_messages"):
            return await ctx.send("❌ Yetkin yok.")
        k = mm_d(ctx.guild)["engel"]
        if uye.id in k:
            k.remove(uye.id)
            yazi = f"✅ **{uye.display_name}** engeli kaldırıldı."
        else:
            k.append(uye.id)
            yazi = f"🚫 **{uye.display_name}** ModMail'den engellendi."
        isaretle26()
        kaydet()
        await ctx.send(yazi)


