# 9) BOT KÖPRÜSÜ: başka botlarla konuşma
# ======================================================================
class KopruCog(commands.Cog, name="Kopru26"):
    """İzin verdiğin botlarla, SADECE ayarladığın kanalda konuşur. Sonsuz döngüyü sınırlar:
    botlar arası en fazla 4 ardışık cevap, 10 dakikada en fazla 8 cevap; bir insan yazınca sayaç sıfırlanır."""
    MAX_ZINCIR = 4
    PENCERE_MAX = 8

    def __init__(self, bot):
        self.bot = bot
        self.zincir_say = {}
        self.pencere = {}
        self.saat = {}          # döngü modu: son 1 saatteki cevap zamanları (kota koruması)
        self.mesgul = {}        # aynı kanalda aynı anda tek cevap
        self.insan = {}         # kanalda en son insan mesajı zamanı

    @commands.Cog.listener()
    async def on_message(self, m):
        if m.guild is None:
            return
        d = sg(m.guild.id)["bot"]
        if not d["acik"] or m.channel.id != d["kanal"]:
            return
        if not m.author.bot:
            self.zincir_say[m.channel.id] = 0          # insan yazdı: sayaç sıfırlanır
            self.insan[m.channel.id] = time.time()
            return
        if m.author.id == self.bot.user.id or m.author.id not in d["botlar"]:
            return
        icerik = (m.content or "").strip()
        if not icerik and m.embeds:                       # embed ile konuşan botlar
            e0 = m.embeds[0]
            icerik = " ".join(x for x in (e0.title, e0.description) if x).strip()
        icerik = re.sub(r"<@!?%d>" % self.bot.user.id, "", icerik).strip()      # beni etiketlediyse etiketi at
        if not icerik:
            return
        if self.mesgul.get(m.channel.id):                 # bu kanalda zaten bir cevap hazırlanıyor
            return
        self.mesgul[m.channel.id] = True
        try:
            k, simdi = m.channel.id, time.time()
            pencere = [t for t in self.pencere.get(k, []) if simdi - t < 600]
            saat = [t for t in self.saat.get(k, []) if simdi - t < 3600]
            if not d.get("dongu"):                      # döngü kapalıysa eski sınırlar geçerli
                if self.zincir_say.get(k, 0) >= self.MAX_ZINCIR or len(pencere) >= self.PENCERE_MAX:
                    return
            else:                                       # döngü açık: saatlik limit dolduysa yer açılana kadar bekle
                if len(saat) >= max(1, int(d.get("saatlik", 10))):
                    await asyncio.sleep(max(1, saat[0] + 3600 - simdi))
                    if self.insan.get(k, 0) > simdi:    # beklerken bir insan yazdıysa bu eski mesajı bırak
                        return
                    simdi = time.time()
                    saat = [t for t in saat if simdi - t < 3600]
            if icerik.lower().startswith("tdapi "):
                cevap = self.api(m, icerik[6:].strip())
            else:
                cog = self.bot.get_cog("HizliAI")
                if cog is None:
                    return
                cevap = await cog.ai_cevapla(m.author, m.channel.id, icerik[:500], sessiz=True, mesaj=m)
            if not cevap:
                return
            pencere.append(simdi)
            self.pencere[k] = pencere
            saat.append(simdi)
            self.saat[k] = saat
            self.zincir_say[k] = self.zincir_say.get(k, 0) + 1
            if d.get("dongu"):                          # döngüde cevaplar arası bekleme (yapay zeka kotasını korur)
                await asyncio.sleep(max(0, int(d.get("bekle", 40)) - 4))
            async with m.channel.typing():
                await asyncio.sleep(random.uniform(2, 4))
            if not m.channel.permissions_for(m.guild.me).send_messages:
                return
            # diğer botun mesajını YANITLAYARAK cevap ver (sadece o botu etiketler, başka kimseyi değil)
            ping = discord.AllowedMentions(users=[m.author], replied_user=True, roles=False, everyone=False)
            try:
                await m.channel.send(cevap[:1900], reference=m.to_reference(fail_if_not_exists=False),
                                     allowed_mentions=ping)
            except discord.HTTPException:
                await m.channel.send(cevap[:1900], allowed_mentions=NO_PING)
        except Exception as e:
            await hata(self.bot, e, "bot köprüsü")
        finally:
            self.mesgul.pop(m.channel.id, None)

    def api(self, m, komut):
        """Başka botun okuyabileceği basit komutlar. Yanıt: 'tdapi ok ...' / 'tdapi hata ...'"""
        p = komut.split()
        if not p or p[0] in ("ok", "hata"):
            return None
        try:
            if p[0] == "ping":
                return f"tdapi ok pong {round(self.bot.latency * 1000)}ms"
            if p[0] == "bakiye" and len(p) > 1 and p[1].isdigit():
                return f"tdapi ok bakiye {p[1]} {int(eko(m.guild.id, int(p[1])).get('bakiye', 0))}"
            if p[0] == "uye" and len(p) > 1 and p[1].isdigit():
                return f"tdapi ok uye {p[1]} {'var' if m.guild.get_member(int(p[1])) else 'yok'}"
            return "tdapi hata bilinmeyen_komut (ping, bakiye <id>, uye <id>)"
        except Exception:
            return "tdapi hata islem_basarisiz"

    @commands.command(name="botsohbet", aliases=["botkoprusu", "botkopru"], usage="kanal #kanal | ekle @bot | cikar @bot | ac | kapat | durum")
    @commands.guild_only()
    async def botsohbet(self, ctx, islem: str = "durum", *, hedef: str = ""):
        """Başka botlarla konuşmayı ayarla (yönetici)"""
        if not await yetkili_mi(ctx, "administrator"):
            return await ctx.send("❌ Bunun için yönetici olmalısın.")
        d = sg(ctx.guild.id)["bot"]
        islem = islem.lower()
        sayi = re.sub(r"\D", "", hedef)
        if islem in ("kanal", "ekle", "cikar", "çıkar") and not sayi:
            return await ctx.send("❌ Etiketle ya da ID yaz. Örnek: `td!botsohbet kanal #kanal` • `td!botsohbet ekle @bot`")
        if islem == "kanal":
            if not ctx.guild.get_channel(int(sayi)):
                return await ctx.send("❌ Bu sunucuda böyle bir kanal yok.")
            d["kanal"] = int(sayi)
        elif islem in ("ekle", "cikar", "çıkar") and sayi:
            uid = int(sayi)
            if islem == "ekle":
                uye = ctx.guild.get_member(uid)
                if uye is None:
                    try:
                        uye = await ctx.guild.fetch_member(uid)
                    except discord.HTTPException:
                        uye = None
                if uye is None or not uye.bot:
                    return await ctx.send("❌ Bu sunucuda böyle bir bot yok. Botu etiketle ya da ID yaz.")
                if uid not in d["botlar"]:
                    d["botlar"].append(uid)
            elif uid in d["botlar"]:
                d["botlar"].remove(uid)
        elif islem in ("hiz", "hız", "bekle"):
            d["bekle"] = max(5, min(600, int(sayi or 40)))
        elif islem in ("limit", "saatlik"):
            d["saatlik"] = max(1, min(120, int(sayi or 10)))
        elif islem in ("dongu", "döngü"):
            d["dongu"] = hedef.strip().lower() not in ("kapat", "kapali", "kapalı", "0", "hayir", "hayır")
        elif islem in ("ac", "aç"):
            if not d["kanal"]:
                return await ctx.send("❌ Önce kanalı ayarla: `td!botsohbet kanal #kanal`")
            d["acik"] = True
        elif islem == "kapat":
            d["acik"] = False
        isaretle26()
        kaydet()
        durum_y = "🟢 açık" if d["acik"] else "🔴 kapalı"
        kanal_y = "<#%d>" % d["kanal"] if d["kanal"] else "ayarlı değil"
        botlar_y = ", ".join("<@%d>" % b for b in d["botlar"]) or "yok"
        await ctx.send(
            f"🤖 **Bot köprüsü:** {durum_y}\n"
            f"Kanal: {kanal_y}\n"
            f"İzinli botlar: {botlar_y}\n"
            f"Döngü: {'♾️ açık, cevaplar arası ' + str(d.get('bekle', 40)) + ' sn, saatte en fazla ' + str(d.get('saatlik', 10)) + ' cevap' if d.get('dongu') else 'kapalı (en fazla 4 ardışık cevap)'}\n"
            f"`td!botsohbet kanal #kanal` • `ekle @bot` • `cikar @bot` • `ac` • `kapat` • `dongu ac/kapat` • `hiz 40` (sn) • `limit 10` (saatlik)\n"
            f"💡 Diğer botun `tdapi ping` / `tdapi bakiye <id>` yazarsa makine gibi yanıt veririm, yoksa sohbet ederim.",
            allowed_mentions=NO_PING)


