'''


MODUL_KAYNAK["v29"] = r'''# -*- coding: utf-8 -*-
"""
THEDLAX BOT v2.9 - Bot sahibi araçları, kara liste, bakım modu, yapay zeka emoji ayarı ve ses DM

  🔔 Sunucu bildirimi : bot bir sunucuya eklenince ya da çıkarılınca bot sahibine DM atar
  🚪 td!sunucuayril <sunucu ID> [evet]      (bot sahibi) botu o sunucudan çıkarır
  ⛔ td!karaliste liste | ekle kullanici/sunucu <ID> [sebep] | cikar <ID>   (bot sahibi)
        kullanıcı: mesajları ve slash komutları yok sayılır
        sunucu   : bot o sunucudan çıkar, tekrar eklenirse yine çıkar
  🛠️ td!bakim [ac | kapat]                 (bot sahibi) açıkken bot sadece sahibine cevap verir
  🤖 td!aiemoji [ac | kapat]                (Sunucuyu Yönet) yapay zeka cevaplarında emoji aç (varsayılan kapalı)
  🔊 td!sesdm [ac | kapat | mesaj <yazı> | mesaj sil | test]   (Yönetici) sese girip çıkanlara DM
  🔕 td!sesdmben [ac | kapat]               herkes kendi ses DM'lerini kapatabilir

Veri: veri_v29.json
"""
import re
import json
import os
import time
import asyncio

import discord
from discord.ext import commands

DOSYA = "veri_v29.json"
NO_PING = discord.AllowedMentions.none()
PREFIXLER = ("td/", "td!")
SES_DM_KATILMA_BEKLEME = 30      # aynı kişiye "katıldın" DM'i en sık bu kadar saniyede bir
SES_DM_MIN_SURE = 10             # bundan kısa kalışlarda "ayrıldın" DM'i atılmaz (saniye)
SES_DM_CIKIS_BEKLEME = 300      # aynı kişiye "ayrıldın" DM\'i en sık bu kadar saniyede bir (spam koruması)
MESAJ_MAX = 300

veri = {
    "kara_kullanici": {},        # {"id": "sebep"}
    "kara_sunucu": {},           # {"id": "sebep"}
    "bakim": False,
    "ai_emoji_acik": [],         # emojiyi AÇIK tutan sunucular (varsayılan: kapalı)
    "sesdm": {},                 # {"sunucu_id": {"aktif": bool, "mesaj": str}}
    "sesdm_kapali_uye": [],      # [kullanici_id (str)]
    "ses_toplam": {},            # {"sunucu_id": {"kullanici_id": saniye}}
}
G = {}
SAHIPLER = set()                 # bot sahibi (takımsa tüm takım üyeleri) kimlikleri
DURUM = {"kirli": False, "bakim_uyari": {}}


# ---------------------------------------------------------------------- veri
def yukle():
    if os.path.exists(DOSYA):
        try:
            with open(DOSYA, encoding="utf-8") as f:
                veri.update(json.load(f))
        except (OSError, ValueError) as e:
            print(f"v29 verisi okunamadı: {e!r}")
    veri.setdefault("kara_kullanici", {})
    veri.setdefault("kara_sunucu", {})
    veri.setdefault("bakim", False)
    veri.setdefault("ai_emoji_acik", [])
    veri.setdefault("sesdm", {})
    veri.setdefault("sesdm_kapali_uye", [])
    veri.setdefault("ses_toplam", {})


def kaydet():
    try:
        gecici = DOSYA + ".tmp"
        with open(gecici, "w", encoding="utf-8") as f:
            json.dump(veri, f, ensure_ascii=False)
        os.replace(gecici, DOSYA)
        DURUM["kirli"] = False
    except OSError as e:
        print(f"v29 verisi kaydedilemedi: {e!r}")


def isaretle():
    DURUM["kirli"] = True


async def kaydet_dongusu():
    while True:
        await asyncio.sleep(30)
        if DURUM["kirli"]:
            kaydet()


def sure_yaz(sn):
    sn = int(sn)
    gun, sn = divmod(sn, 86400)
    saat, sn = divmod(sn, 3600)
    dk, sn = divmod(sn, 60)
    parca = []
    if gun:
        parca.append(f"{gun} gün")
    if saat:
        parca.append(f"{saat} sa")
    if dk:
        parca.append(f"{dk} dk")
    if sn or not parca:
        parca.append(f"{sn} sn")
    return " ".join(parca[:3])


def kimlik(metin):
    s = re.sub(r"\D", "", metin or "")
    return s or None


# ---------------------------------------------------------------------- bot sahibi
async def sahip_yukle(bot):
    """Bot sahibini Discord'dan öğrenir (kimlik ile kontrol: isim/profil taklit edilemez)."""
    try:
        bilgi = await bot.application_info()
    except Exception as e:
        print(f"v29: bot sahibi öğrenilemedi: {e!r}")
        return
    kimlikler = set()
    takim = getattr(bilgi, "team", None)
    if takim:
        kimlikler |= {m.id for m in takim.members}
        G["sahip_dm_id"] = takim.owner_id
    elif bilgi.owner:
        kimlikler.add(bilgi.owner.id)
        G["sahip_dm_id"] = bilgi.owner.id
    SAHIPLER.clear()
    SAHIPLER.update(kimlikler)


async def sahibe_dm(bot, embed):
    uid = G.get("sahip_dm_id")
    if uid is None:
        await sahip_yukle(bot)
        uid = G.get("sahip_dm_id")
    if uid is None:
        return False
    try:
        kisi = bot.get_user(uid) or await bot.fetch_user(uid)
        await kisi.send(embed=embed)
        return True
    except (discord.HTTPException, AttributeError):
        return False


# ---------------------------------------------------------------------- kara liste ve bakım
def engel_sebebi(m):
    """None = serbest, 'kara' = engelli, 'bakim' = bakım modu."""
    if m.author.bot or m.author.id in SAHIPLER:
        return None
    if str(m.author.id) in veri["kara_kullanici"]:
        return "kara"
    if m.guild is not None and str(m.guild.id) in veri["kara_sunucu"]:
        return "kara"
    if veri["bakim"]:
        return "bakim"
    return None


def bakim_uyar(m):
    icerik = (m.content or "").lower()
    if not icerik.startswith(PREFIXLER):
        return
    simdi = time.time()
    if simdi - DURUM["bakim_uyari"].get(m.channel.id, 0) < 20:
        return
    DURUM["bakim_uyari"][m.channel.id] = simdi

    async def gonder():
        try:
            await m.channel.send("🛠️ Bot şu an bakımda, birazdan döneceğim.", delete_after=8)
        except discord.HTTPException:
            pass
    asyncio.ensure_future(gonder())


def dispatch_yama(bot):
    """Engelli kullanıcı/sunucu ve bakım modunda mesaj olaylarını hiçbir modüle ulaştırmaz."""
    if getattr(bot, "_v29_yama", False):
        return
    orj = bot.dispatch

    def yeni(olay, *a, **kw):
        if olay == "message" and a and SAHIPLER:
            try:
                sebep = engel_sebebi(a[0])
                if sebep == "bakim":
                    bakim_uyar(a[0])
            except Exception as e:
                print(f"v29 engel kontrolü hatası: {e!r}")
                sebep = None
            if sebep:
                return None
        return orj(olay, *a, **kw)

    bot.dispatch = yeni
    try:
        bot._connection.dispatch = yeni      # Discord olayları buradan geçer
    except AttributeError:
        print("v29: UYARI, kara liste / bakım modu tam çalışmayabilir (discord.py sürümü farklı).")
    bot._v29_yama = True


async def tree_kontrol(interaction):
    """Slash komutları için aynı engel kontrolü."""
    kisi = interaction.user
    if kisi.id in SAHIPLER:
        return True
    kara = (str(kisi.id) in veri["kara_kullanici"]
            or (interaction.guild_id and str(interaction.guild_id) in veri["kara_sunucu"]))
    if kara or veri["bakim"]:
        try:
            await interaction.response.send_message(
                "🚫 Bu botu kullanman engellendi." if kara else "🛠️ Bot şu an bakımda, birazdan döneceğim.",
                ephemeral=True)
        except discord.HTTPException:
            pass
        return False
    return True


def emoji_kapali_mi(gid):
    return str(gid) not in veri["ai_emoji_acik"]


# ---------------------------------------------------------------------- ses DM metinleri
def yerlestir(metin, uye, kanal_adi):
    return (metin.replace("{sunucu}", uye.guild.name)
                 .replace("{kanal}", kanal_adi)
                 .replace("{uye}", uye.display_name))


def katilma_embed(uye, kanal_adi, sahne, kisi, ayar):
    if sahne:
        baslik, satir = "🎤 Sahneye katıldın", f"**{uye.guild.name}** sunucusunda **{kanal_adi}** sahne kanalına girdin."
    else:
        baslik, satir = "🔊 Sese katıldın", f"**{uye.guild.name}** sunucusunda **{kanal_adi}** kanalına girdin."
    aciklama = satir + f"\n👥 Şu an kanalda **{kisi}** kişi var."
    ozel = (ayar.get("mesaj") or "").strip()
    if ozel:
        aciklama += "\n\n📢 " + yerlestir(ozel, uye, kanal_adi)
    e = discord.Embed(title=baslik, description=aciklama[:4000], color=0x57F287)
    e.set_footer(text="Bu mesajları kapatmak için: td!sesdmben kapat")
    return e


def ayrilma_embed(uye, kanal_adi, bu_sefer, toplam):
    aciklama = (f"**{uye.guild.name}** sunucusunda **{kanal_adi}** kanalından ayrıldın.\n"
                f"⏱️ Bu sefer **{sure_yaz(bu_sefer)}** seslide kaldın.\n"
                f"📊 Bu sunucuda toplam: **{sure_yaz(toplam)}**")
    e = discord.Embed(title="🔇 Sesten ayrıldın", description=aciklama, color=0xED4245)
    e.set_footer(text="Bu mesajları kapatmak için: td!sesdmben kapat")
    return e


# ---------------------------------------------------------------------- cog
class V29Cog(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.giris = {}      # {(sunucu_id, kullanici_id): sese giriş zamanı}
        self.son_dm = {}     # {(sunucu_id, kullanici_id): son "katıldın" DM zamanı}
        self.son_cikis = {}  # {(sunucu_id, kullanici_id): son "ayrıldın" DM zamanı}
        self.dm_kilit = asyncio.Lock()   # DM\'ler sırayla gider (hız sınırı koruması)
        self.dm_bekleyen = 0
        self.dm_engelli = {}  # {kullanici_id: DM\'leri kapalı, şu zamana kadar deneme}

    async def sahip_mi(self, kisi):
        try:
            return await self.bot.is_owner(kisi)
        except Exception:
            return False

    # ---------------- olaylar
    @commands.Cog.listener()
    async def on_ready(self):
        await sahip_yukle(self.bot)
        for g in list(self.bot.guilds):
            if str(g.id) in veri["kara_sunucu"]:
                await self.engelli_sunucudan_cik(g)
            else:
                self.sese_tohumla(g)

    def sese_tohumla(self, g):
        """Şu an seste olanların giriş zamanını bu ana ayarlar (süre buradan itibaren sayılır)."""
        ayar = veri["sesdm"].get(str(g.id))
        if not ayar or not ayar.get("aktif"):
            return
        simdi = time.time()
        for vc in list(g.voice_channels) + list(g.stage_channels):
            for m in vc.members:
                if not m.bot:
                    self.giris.setdefault((g.id, m.id), simdi)

    async def engelli_sunucudan_cik(self, g):
        ad, gid = g.name, g.id
        try:
            await g.leave()
        except discord.HTTPException:
            return
        sebep = veri["kara_sunucu"].get(str(gid)) or "sebep yok"
        await sahibe_dm(self.bot, discord.Embed(
            title="⛔ Kara listedeki sunucudan çıkıldı",
            description=f"**{ad}** (`{gid}`)\nSebep: {sebep}", color=0xED4245))

    @commands.Cog.listener()
    async def on_guild_join(self, guild):
        if str(guild.id) in veri["kara_sunucu"]:
            return await self.engelli_sunucudan_cik(guild)
        e = discord.Embed(title="➕ Yeni sunucuya eklendim", color=0x57F287,
                          description=f"**{discord.utils.escape_markdown(guild.name)}**")
        e.add_field(name="ID", value=f"`{guild.id}`")
        e.add_field(name="Üye", value=str(guild.member_count or "?"))
        e.add_field(name="Sahip", value=f"<@{guild.owner_id}> (`{guild.owner_id}`)" if guild.owner_id else "?")
        e.set_footer(text=f"Toplam {len(self.bot.guilds)} sunucu • td!sunucuayril {guild.id}")
        await sahibe_dm(self.bot, e)

    @commands.Cog.listener()
    async def on_guild_remove(self, guild):
        e = discord.Embed(title="➖ Bir sunucudan ayrıldım / atıldım", color=0xED4245,
                          description=f"**{discord.utils.escape_markdown(guild.name)}**")
        e.add_field(name="ID", value=f"`{guild.id}`")
        e.add_field(name="Üye", value=str(guild.member_count or "?"))
        e.set_footer(text=f"Kalan toplam {len(self.bot.guilds)} sunucu")
        await sahibe_dm(self.bot, e)

    # ---------------- ses DM
    async def dm_gonder(self, uye, embed):
        """DM sırayla, aralıklı gider; DM'i kapalı kişi 24 saat denenmez; kuyruk şişerse yeni DM atlanır."""
        if self.dm_engelli.get(uye.id, 0) > time.time() or self.dm_bekleyen >= 100:
            return
        self.dm_bekleyen += 1
        try:
            async with self.dm_kilit:
                try:
                    await uye.send(embed=embed)
                except discord.Forbidden:
                    self.dm_engelli[uye.id] = time.time() + 86400
                except discord.HTTPException:
                    pass
                await asyncio.sleep(1.2)
        finally:
            self.dm_bekleyen -= 1

    @commands.Cog.listener()
    async def on_voice_state_update(self, uye, once, sonra):
        if uye.bot:
            return
        gid = uye.guild.id
        anahtar = (gid, uye.id)
        ayar = veri["sesdm"].get(str(gid))
        if not ayar or not ayar.get("aktif"):
            self.giris.pop(anahtar, None)
            return
        if veri["bakim"] or str(uye.id) in veri["kara_kullanici"]:
            return
        if str(uye.id) in veri["sesdm_kapali_uye"]:
            self.giris.pop(anahtar, None)
            return
        simdi = time.time()

        if once.channel is None and sonra.channel is not None:           # sese girdi
            self.giris[anahtar] = simdi
            if simdi - self.son_dm.get(anahtar, 0) >= SES_DM_KATILMA_BEKLEME:
                self.son_dm[anahtar] = simdi
                kanal = sonra.channel
                kisi = len([m for m in kanal.members if not m.bot])
                sahne = isinstance(kanal, discord.StageChannel)
                asyncio.ensure_future(self.dm_gonder(uye, katilma_embed(uye, kanal.name, sahne, kisi, ayar)))

        elif once.channel is not None and sonra.channel is None:         # sesten çıktı
            bas = self.giris.pop(anahtar, None)
            if bas is None:
                return
            sure = simdi - bas
            toplamlar = veri["ses_toplam"].setdefault(str(gid), {})
            toplamlar[str(uye.id)] = int(toplamlar.get(str(uye.id), 0) + sure)
            isaretle()
            if sure >= SES_DM_MIN_SURE and simdi - self.son_cikis.get(anahtar, 0) >= SES_DM_CIKIS_BEKLEME:
                self.son_cikis[anahtar] = simdi
                asyncio.ensure_future(self.dm_gonder(
                    uye, ayrilma_embed(uye, once.channel.name, sure, toplamlar[str(uye.id)])))

