class _Mesaj:
    """Sessiz modda ctx.send'in döndürdüğü sahte mesaj."""
    id = 0

    def __init__(self, notlar):
        self._n = notlar

    async def edit(self, *a, **k):
        if k.get("content"):
            self._n.append(str(k["content"]))

    async def delete(self, *a, **k):
        return None

    async def add_reaction(self, *a, **k):
        return None


class _Sessiz:
    """Komutların cevaplarını kanala yazmak yerine toplar (rapora girsin diye)."""

    def __init__(self, ctx):
        self._ctx = ctx
        self.notlar = []

    def __getattr__(self, ad):
        return getattr(self._ctx, ad)

    async def send(self, icerik=None, *a, **k):
        if icerik:
            self.notlar.append(str(icerik))
        return _Mesaj(self.notlar)

    reply = send

    async def defer(self, *a, **k):
        return None


class V31Cog(commands.Cog):
    def __init__(self, bot):
        self.bot = bot

    @staticmethod
    def v15():
        m = sys.modules.get("v15")
        return m if m is not None and hasattr(m, "RolButonu") else None

    @staticmethod
    def rol_hatasi(ctx, r, v15):
        """Rol butona konamıyorsa sebebini yazı olarak döndürür, sorun yoksa None."""
        if r.managed or r.is_default() or r >= ctx.guild.me.top_role:
            return (f"❌ {r.mention} rolünü veremem (benim rolüm onun altında kalıyor ya da özel bir rol). "
                    "Sunucu Ayarları > Roller'den botun rolünü verilecek rollerin üstüne çek.")
        if v15.riskli_rol(r):
            return f"❌ {r.mention} yetkili bir rol (yönetici/ban/rol yönetme gibi), güvenlik için butona konamaz."
        if ctx.author.id != ctx.guild.owner_id and r >= ctx.author.top_role:
            return f"❌ {r.mention} senin en yüksek rolünle aynı ya da senden yüksek."
        return None

    async def menu_gonder(self, ctx, kanal, liste, emojiler=None, baslik="🏷️ Rol Al", aciklama=None):
        v15 = self.v15()
        emojiler = emojiler or {}
        for r in liste:
            hata = self.rol_hatasi(ctx, r, v15)
            if hata:
                await ctx.send(hata, allowed_mentions=NO_PING)
                return False
        v = discord.ui.View(timeout=None)
        for r in liste:
            oge = v15.RolButonu(r.id, r.name)
            oge.item.style = discord.ButtonStyle.primary
            emoji = emojiler.get(r.id) or r.unicode_emoji
            if emoji:
                oge.item.emoji = emoji
            v.add_item(oge)
        e = discord.Embed(
            title=baslik,
            description=(aciklama or "Aşağıdaki butonlara basarak rolü alabilir, tekrar basarak geri verebilirsin.")
                        + "\n\n" + "\n".join(f"{emojiler.get(r.id, '')} {r.mention}".strip() for r in liste),
            color=discord.Color.blurple())
        try:
            await kanal.send(embed=e, view=v, allowed_mentions=NO_PING)
        except discord.HTTPException as ex:
            await ctx.send(f"❌ Menü gönderilemedi: {ex}")
            return False
        return True

    @commands.command(name="rolmenu", aliases=["rolsistemi", "rolpaneli", "rolbutonlari"],
                      usage="[#kanal] @rol1 @rol2 ...")
    @commands.has_permissions(manage_roles=True)
    @commands.bot_has_permissions(manage_roles=True)
    @commands.guild_only()
    async def rolmenu(self, ctx, kanal: typing.Optional[discord.TextChannel] = None, *roller: discord.Role):
        """🏷️ Butonla rol alma menüsü gönder, en fazla 25 rol (Rolleri Yönet)"""
        if self.v15() is None:
            return await ctx.send("❌ Rol butonu modülü (v15) yüklenmemiş, `td!modul` ile bak.")
        if not roller:
            return await ctx.send("Kullanım: `td!rolmenu [#kanal] @rol1 @rol2 ...`\n"
                                  "Örnek: `td!rolmenu #roller @Oyuncu @Müzik @Duyuru`\n"
                                  "Üyeler butona basınca rolü alır, tekrar basınca geri verir.\n"
                                  "Hazır ping rolleri için: `td!rolsablon`")
        liste = []
        for r in roller:
            if r not in liste:
                liste.append(r)
        if len(liste) > 25:
            return await ctx.send("❌ Bir menüye en fazla 25 rol konabilir, fazlası için ikinci menü aç.")
        kanal = kanal or ctx.channel
        if not kanal.permissions_for(ctx.guild.me).send_messages:
            return await ctx.send(f"❌ {kanal.mention} kanalına yazma iznim yok.")
        if await self.menu_gonder(ctx, kanal, liste) and kanal.id != ctx.channel.id:
            await ctx.send(f"✅ Rol menüsü {kanal.mention} kanalına gönderildi.")

    @commands.command(name="rolsablon", aliases=["pingrolleri", "pingroller", "pingsablon"], usage="[#kanal]")
    @commands.has_permissions(manage_roles=True)
    @commands.bot_has_permissions(manage_roles=True)
    @commands.guild_only()
    async def rolsablon(self, ctx, kanal: discord.TextChannel = None):
        """🔔 Hazır ping rollerini (duyuru, aktiflik, anket...) açar ve buton menüsüne koyar (Rolleri Yönet)"""
        if self.v15() is None:
            return await ctx.send("❌ Rol butonu modülü (v15) yüklenmemiş, `td!modul` ile bak.")
        kanal = kanal or ctx.channel
        if not kanal.permissions_for(ctx.guild.me).send_messages:
            return await ctx.send(f"❌ {kanal.mention} kanalına yazma iznim yok.")
        liste, emojiler, yeni, var = [], {}, [], []
        for ad, emoji in SABLON:
            r = discord.utils.find(lambda x: x.name.lower() == ad.lower() and not x.managed, ctx.guild.roles)
            if r is None:
                try:
                    r = await ctx.guild.create_role(name=ad, mentionable=True,
                                                    reason=f"Rol şablonu - {ctx.author}")
                except (discord.Forbidden, discord.HTTPException) as ex:
                    return await ctx.send(f"❌ **{ad}** rolünü açamadım: {ex}")
                yeni.append(ad)
            else:
                var.append(ad)
            liste.append(r)
            emojiler[r.id] = emoji
        ok = await self.menu_gonder(
            ctx, kanal, liste, emojiler, baslik="🔔 Ping Rolleri",
            aciklama="Hangi bildirimleri istiyorsan o butonlara bas, rolü alırsın. Tekrar basarsan rol geri gider.")
        if ok:
            ozet = f"✅ Ping menüsü {kanal.mention} kanalına gönderildi."
            if yeni:
                ozet += "\n➕ Açılan roller: " + ", ".join(f"**{x}**" for x in yeni)
            if var:
                ozet += "\n♻️ Zaten vardı, onları kullandım: " + ", ".join(f"**{x}**" for x in var)
            await ctx.send(ozet)

    async def adim(self, w, rapor, etiket, komut, *args):
        """Mevcut bir komutun kodunu çağırır, sonucu rapora yazar."""
        cmd = self.bot.get_command(komut)
        if cmd is None:
            rapor.append(f"⏭️ {etiket}: komut bulunamadı")
            return
        w.notlar.clear()
        try:
            if cmd.cog is not None:
                await cmd.callback(cmd.cog, w, *args)
            else:
                await cmd.callback(w, *args)
        except Exception as ex:
            rapor.append(f"❌ {etiket}: {type(ex).__name__} {str(ex)[:70]}")
            return
        son = w.notlar[-1] if w.notlar else ""
        if son.startswith("❌"):
            rapor.append(f"❌ {etiket}: {son[:90]}")
        elif son.startswith("ℹ️"):
            rapor.append(f"ℹ️ {etiket}: zaten kurulu")
        else:
            rapor.append(f"✅ {etiket}")

    @commands.command(name="toplukur", aliases=["herseykur", "hepsinikur", "tamkur"], usage="evet")
    @commands.has_permissions(administrator=True)
    @commands.bot_has_permissions(manage_channels=True, manage_roles=True)
    @commands.guild_only()
    async def toplukur(self, ctx, onay: str = ""):
        """🧰 Botun bütün sistemlerini tek komutla kur: kanallar, roller, log, bilet, güvenlik... (Yönetici)"""
        if onay.lower() not in ("evet", "onay", "tamam"):
            return await ctx.send(PLAN)
        g = ctx.guild
        PO = discord.PermissionOverwrite
        sebep = f"Toplu kurulum - {ctx.author}"
        durum = await ctx.send("⏳ Toplu kurulum başladı, 1-2 dakika sürebilir...")
        rapor = []
        async with ctx.typing():
            # ---- roller ----
            roller = {}
            for anahtar, ad, renk, izin, hoist in (
                    ("moderator", "🛡️ Moderatör", 0x3498DB,
                     dict(kick_members=True, ban_members=True, manage_messages=True, moderate_members=True,
                          manage_nicknames=True, view_audit_log=True), True),
                    ("uye", "✅ Üye", 0x95A5A6, dict(), False)):
                r = discord.utils.find(lambda x, a=anahtar: _ad(x.name) == ("moderatör" if a == "moderator" else "üye")
                                       and not x.managed, g.roles)
                if r is None:
                    try:
                        r = await g.create_role(name=ad, colour=discord.Colour(renk), hoist=hoist,
                                                permissions=discord.Permissions(**izin), reason=sebep)
                        rapor.append(f"✅ Rol açıldı: {ad}")
                    except discord.HTTPException as ex:
                        rapor.append(f"❌ Rol açılamadı ({ad}): {str(ex)[:60]}")
                roller[anahtar] = r
            mod, uye = roller.get("moderator"), roller.get("uye")

            # ---- kategoriler ve kanallar ----
            kanallar, yeni, kategoriler = {}, set(), {}
            try:
                for kat_ad, gizli, liste in YAPI:
                    kat = discord.utils.find(lambda c, n=kat_ad: c.name.lower() == n.lower(), g.categories)
                    if kat is None:
                        ow = {}
                        if gizli:
                            ow = {g.default_role: PO(view_channel=False),
                                  g.me: PO(view_channel=True, send_messages=True, manage_channels=True)}
                            if mod:
                                ow[mod] = PO(view_channel=True, send_messages=True)
                        kat = await g.create_category(kat_ad, overwrites=ow, reason=sebep)
                    kategoriler[kat_ad] = kat
                    for ad in liste:
                        k = discord.utils.get(g.text_channels, name=ad)
                        if k is None:
                            ow = {}
                            if ad in SALT_OKUNUR:
                                ow = {g.default_role: PO(send_messages=False), g.me: PO(send_messages=True)}
                                if mod:
                                    ow[mod] = PO(send_messages=True)
                            k = await g.create_text_channel(ad, category=kat, overwrites=ow, reason=sebep)
                            yeni.add(ad)
                        kanallar[ad] = k
                rapor.append(f"✅ Kanallar hazır ({len(yeni)} yeni açıldı)")
            except discord.HTTPException as ex:
                rapor.append(f"❌ Kanal kurulumu yarıda kaldı: {str(ex)[:80]}")
            if "kurallar" in yeni:
                try:
                    await kanallar["kurallar"].send(embed=discord.Embed(
                        title="📜 Sunucu Kuralları", description=KURALLAR, color=discord.Color.blurple()))
                except discord.HTTPException:
                    pass

            # ---- güvenlik (küfür / spam / davet koruması) ----
            v15 = sys.modules.get("v15")
            try:
                v15.sunucu_ayar(g.id)["guvenlik"].update(kufur=True, spam=True, davet=True)
                v15.veri_kaydet()
                rapor.append("✅ Güvenlik: küfür, spam ve davet koruması açık")
            except Exception as ex:
                rapor.append(f"❌ Güvenlik: {str(ex)[:70]}")

            # ---- bu komutun kendi ayarları: her adımın cevabı rapora girer ----
            w = _Sessiz(ctx)
            K = kanallar.get
            if K("hosgeldin"):
                await self.adim(w, rapor, "Hoş geldin kanalı", "hosgeldin", K("hosgeldin"))
            if uye:
                await self.adim(w, rapor, "Otorol (Üye)", "otorol", uye)
            if K("destek"):
                await self.adim(w, rapor, "Bilet paneli", "biletpanel", K("destek"))
            if mod:
                await self.adim(w, rapor, "Bilet destek rolü", "biletayar", mod)
            if K("rol-al"):
                await self.adim(w, rapor, "Rol menüsü + ping rolleri", "rolsablon", K("rol-al"))
            if K("log"):
                await self.adim(w, rapor, "Genel log kanalı", "logkanal", K("log"))
            await self.adim(w, rapor, "Log sistemi (gizli kategori)", "logkur")
            if K("oneriler"):
                await self.adim(w, rapor, "Öneri kanalı", "onerikanal", K("oneriler"))
            if K("enyiler"):
                await self.adim(w, rapor, "Starboard", "starboard", K("enyiler"), 3)
            if K("kelime-zinciri"):
                await self.adim(w, rapor, "Kelime zinciri", "kelimezinciri", K("kelime-zinciri"), "")
            if K("sayi-sayma"):
                await self.adim(w, rapor, "Sayı sayma", "sayisayma", K("sayi-sayma"), "")
            if K("gunun-sorusu"):
                await self.adim(w, rapor, "Günün sorusu (quiz)", "quizkur", K("gunun-sorusu"))
            if K("aktiflik"):
                await self.adim(w, rapor, "Aktiflik mesajı", "aktiflikkur", K("aktiflik"))
            if K("dogum-gunleri"):
                await self.adim(w, rapor, "Doğum günü kanalı", "dogumgunukanal", K("dogum-gunleri"))
            await self.adim(w, rapor, "Kademeli ceza (varsayılan)", "ceza", "varsayilan")
            await self.adim(w, rapor, "Kademeli ceza açık", "ceza", "ac")
            await self.adim(w, rapor, "Davet takibi", "davettakip", "ac")
            await self.adim(w, rapor, "ModMail", "modmailkur", None, mod)
            await self.adim(w, rapor, "İstatistik kanalları", "istatistikkanal")
            await self.adim(w, rapor, "Premium (Beta) rolü", "premiumkur")

            # hata kanalı: daha önce ayarlıysa dokunma
            m25 = sys.modules.get("v25")
            try:
                a25 = m25.ayar() if m25 is not None and callable(getattr(m25, "ayar", None)) else None
            except Exception:
                a25 = None
            if a25 is not None:
                if not a25.get("hata_kanal") and K("hata-log"):
                    await self.adim(w, rapor, "Hata kanalı", "hatakanal", K("hata-log"))

            # mapushane en sona: bütün kanallar açıldıktan sonra her kanalda mahpusu gizler
            await self.adim(w, rapor, "Mapushane", "mapuskur")

        ok = sum(1 for x in rapor if x.startswith("✅"))
        kotu = [x for x in rapor if x.startswith("❌")]
        e = discord.Embed(title="🧰 Toplu kurulum bitti",
                          description="\n".join(rapor)[:3900],
                          color=discord.Color.green() if not kotu else discord.Color.orange())
        e.set_footer(text=f"{ok} adım tamam, {len(kotu)} sorun. Kayıt/doğrulama için: td!kayitkur • td!dogrulamakur")
        try:
            await durum.edit(content=None, embed=e)
        except discord.HTTPException:
            await ctx.send(embed=e)


