# ======================================================================
# SQLite deposu
# ======================================================================
class Depo:
    """Anahtar/değer deposu (JSON değerler). Yazma anında diske gider (WAL), okuma belleğe alınır."""

    def __init__(self, yol):
        self.kilit = threading.Lock()
        self.bag = sqlite3.connect(yol, check_same_thread=False, timeout=10)
        self.bag.execute("PRAGMA journal_mode=WAL")
        self.bag.execute("CREATE TABLE IF NOT EXISTS kv (anahtar TEXT PRIMARY KEY, deger TEXT NOT NULL, guncelleme INTEGER NOT NULL)")
        self.bag.commit()
        self.onbellek = {}

    def al(self, anahtar, varsayilan=None, onbellekle=True):
        if anahtar in self.onbellek:
            return self.onbellek[anahtar]
        with self.kilit:
            satir = self.bag.execute("SELECT deger FROM kv WHERE anahtar=?", (anahtar,)).fetchone()
        deger = None
        if satir:
            try:
                deger = json.loads(satir[0])
            except ValueError:
                deger = None
        if deger is None:
            deger = copy.deepcopy(varsayilan)
        if onbellekle and deger is not None:
            self.onbellek[anahtar] = deger
        return deger

    def yaz(self, anahtar, deger=None):
        if deger is None:
            deger = self.onbellek.get(anahtar)
        if deger is None:
            return
        self.onbellek[anahtar] = deger
        with self.kilit:
            self.bag.execute(
                "INSERT INTO kv(anahtar,deger,guncelleme) VALUES(?,?,?) "
                "ON CONFLICT(anahtar) DO UPDATE SET deger=excluded.deger, guncelleme=excluded.guncelleme",
                (anahtar, json.dumps(deger, ensure_ascii=False), int(time.time())))
            self.bag.commit()

    def sil(self, anahtar):
        self.onbellek.pop(anahtar, None)
        with self.kilit:
            self.bag.execute("DELETE FROM kv WHERE anahtar=?", (anahtar,))
            self.bag.commit()


