def _birlestir(hedef, varsayilan):
    for k, v in varsayilan.items():
        if k not in hedef:
            hedef[k] = copy.deepcopy(v)
        elif isinstance(v, dict) and isinstance(hedef[k], dict):
            _birlestir(hedef[k], v)
    return hedef


def ayar(gid):
    return _birlestir(depo.al(f"g:{gid}", {}), VARSAYILAN)


def ayar_kaydet(gid):
    depo.yaz(f"g:{gid}")


