DIL_OK = {"tr": "🌐 Dilin **Türkçe** olarak ayarlandı.", "en": "🌐 Your language is now **English**.",
          "az": "🌐 Dilin **Azərbaycan dili** olaraq təyin edildi."}
DIL_SUNUCU_OK = {"tr": "🌐 Sunucu varsayılan dili **Türkçe** oldu.", "en": "🌐 Server default language is now **English**.",
                 "az": "🌐 Serverin defolt dili **Azərbaycan dili** oldu."}


def dil_al(gid, uid=None):
    if uid is not None:
        k = depo.al(f"dil:{uid}", None, onbellekle=False)
        if k in ("tr", "en", "az"):
            return k
    if gid:
        d = ayar(gid).get("dil", "tr")
        return d if d in ("tr", "en", "az") else "tr"
    return "tr"


def t(gid, uid, anahtar, **kw):
    s = M.get(dil_al(gid, uid), M["tr"]).get(anahtar) or M["tr"].get(anahtar, anahtar)
    try:
        return s.format(**kw)
    except (KeyError, IndexError):
        return s


def para(n):
    return f"{int(n):,}".replace(",", ".")


def m15():
    return sys.modules["v15"]


def cuzdan(uid):
    return int(m15().eko(0, uid)["bakiye"])


def para_ekle(uid, n):
    m15().eko_ekle(0, uid, int(n))


def yonetici_mi(uye):
    p = uye.guild_permissions
    return p.administrator or p.manage_guild or uye.id == uye.guild.owner_id


# ======================================================================
# Blackjack
# ======================================================================
KART_RENK = "♠♥♦♣"
KART_DEGER = "A23456789TJQK"


def yeni_deste():
    d = [(r, s) for r in KART_DEGER for s in KART_RENK] * 2
    random.shuffle(d)
    return d


def puan(el):
    toplam, asl = 0, 0
    for r, _ in el:
        if r == "A":
            asl += 1
            toplam += 11
        elif r in "TJQK":
            toplam += 10
        else:
            toplam += int(r)
    while toplam > 21 and asl:
        toplam -= 10
        asl -= 1
    return toplam


def kartlar(el, gizle_ikinci=False):
    parca = []
    for i, (r, s) in enumerate(el):
        if gizle_ikinci and i == 1:
            parca.append("`🂠`")
        else:
            parca.append(f"`{'10' if r == 'T' else r}{s}`")
    return " ".join(parca)


AKTIF_OYUN = set()
OYUN_LIMIT = Sinirlayici(6, 20)


class BJ(discord.ui.View):
    def __init__(self, ctx, bahis):
        super().__init__(timeout=90)
        self.ctx, self.uid, self.gid = ctx, ctx.author.id, ctx.guild.id
        self.bahis, self.msg, self.bitti = bahis, None, False
        self.deste = yeni_deste()
        self.oyuncu = [self.deste.pop(), self.deste.pop()]
        self.krupiye = [self.deste.pop(), self.deste.pop()]
        self.ilk_hamle = True

    def tt(self, anahtar, **kw):
        return t(self.gid, self.uid, anahtar, **kw)

    def embed(self, son=None, renk=discord.Color.blurple()):
        e = discord.Embed(title=self.tt("bj_baslik"), color=renk)
        acik = son is not None
        e.add_field(name=f"{self.tt('bj_sen')} ({puan(self.oyuncu)})", value=kartlar(self.oyuncu), inline=False)
        kr = f"{self.tt('bj_krupiye')} ({puan(self.krupiye)})" if acik else f"{self.tt('bj_krupiye')} (?)"
        e.add_field(name=kr, value=kartlar(self.krupiye, gizle_ikinci=not acik), inline=False)
        e.set_footer(text=f"{self.tt('bj_bahis')}: {para(self.bahis)} 🪙")
        if son:
            e.description = son
        return e

    async def interaction_check(self, i):
        if i.user.id != self.uid:
            await i.response.send_message(self.tt("bj_kimse"), ephemeral=True)
            return False
        return True

    async def bitir(self, i=None, patladi=False):
        if self.bitti:
            return
        self.bitti = True
        AKTIF_OYUN.discard(self.uid)
        self.stop()
        for c in self.children:
            c.disabled = True
        op = puan(self.oyuncu)
        if patladi:
            son, renk, geri = self.tt("bj_patla", n=para(self.bahis)), discord.Color.red(), 0
        else:
            while puan(self.krupiye) < 17:
                self.krupiye.append(self.deste.pop())
            kp = puan(self.krupiye)
            if kp > 21 or op > kp:
                son, renk, geri = self.tt("bj_kazan", n=para(self.bahis)), discord.Color.green(), self.bahis * 2
            elif op == kp:
                son, renk, geri = self.tt("bj_bera"), discord.Color.light_grey(), self.bahis
            else:
                son, renk, geri = self.tt("bj_kaybet", n=para(self.bahis)), discord.Color.red(), 0
        if geri:
            para_ekle(self.uid, geri)
        e = self.embed(son=son, renk=renk)
        try:
            if i is not None and not i.response.is_done():
                await i.response.edit_message(embed=e, view=None)
            elif self.msg is not None:
                await self.msg.edit(embed=e, view=None)
        except discord.HTTPException:
            pass

    @discord.ui.button(label="Hit", emoji="➕", style=discord.ButtonStyle.primary)
    async def hit(self, i, b):
        self.ilk_hamle = False
        self.oyuncu.append(self.deste.pop())
        p = puan(self.oyuncu)
        if p > 21:
            return await self.bitir(i, patladi=True)
        if p == 21:
            return await self.bitir(i)
        for c in self.children:
            if c.label == "Double":
                c.disabled = True
        await i.response.edit_message(embed=self.embed(), view=self)

    @discord.ui.button(label="Stand", emoji="✋", style=discord.ButtonStyle.success)
    async def stand(self, i, b):
        await self.bitir(i)

    @discord.ui.button(label="Double", emoji="✖️", style=discord.ButtonStyle.secondary)
    async def double(self, i, b):
        if not self.ilk_hamle or cuzdan(self.uid) < self.bahis:
            return await i.response.send_message(self.tt("yetersiz", bak=para(cuzdan(self.uid))), ephemeral=True)
        para_ekle(self.uid, -self.bahis)
        self.bahis *= 2
        self.ilk_hamle = False
        self.oyuncu.append(self.deste.pop())
        await self.bitir(i, patladi=puan(self.oyuncu) > 21)

    async def on_timeout(self):
        await self.bitir(None)


