KIRMIZI = {1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36}
CARK = [("💀 x0", 0, 40), ("😐 x0.5", 0.5, 25), ("🟢 x1.5", 1.5, 18), ("🔵 x2", 2, 10),
        ("🟣 x3", 3, 4), ("🟡 x5", 5, 2), ("💎 x10", 10, 1)]


def rulet_renk(n):
    return "yesil" if n == 0 else ("kirmizi" if n in KIRMIZI else "siyah")


def bahis_oku(tt, ctx, ham):
    try:
        b = int(str(ham).replace(".", "").replace(",", ""))
    except ValueError:
        return None, tt("bahis_gecersiz", min=para(MIN_BAHIS), max=para(MAX_BAHIS))
    if b < MIN_BAHIS or b > MAX_BAHIS:
        return None, tt("bahis_gecersiz", min=para(MIN_BAHIS), max=para(MAX_BAHIS))
    if cuzdan(ctx.author.id) < b:
        return None, tt("yetersiz", bak=para(cuzdan(ctx.author.id)))
    return b, None


