TAKAS_AKTIF = set()


def esya_bul(sozluk, ad):
    ad = ad.lower().translate(TR_ASCII)
    for k in sozluk:
        if k.lower().translate(TR_ASCII) == ad:
            return k
    return None


class TakasView(discord.ui.View):
    def __init__(self, ctx, hedef, ver, al, esya, adet):
        super().__init__(timeout=120)
        self.ctx, self.a, self.b = ctx, ctx.author, hedef
        self.ver, self.al, self.esya, self.adet = ver, al, esya, adet
        self.msg, self.bitti = None, False

    def tt(self, k, **kw):
        return t(self.ctx.guild.id, self.b.id, k, **kw)

    def ozet(self, para_miktar, esya=None, adet=0):
        p = []
        if para_miktar:
            p.append(f"{para(para_miktar)} 🪙")
        if esya:
            p.append(f"{adet}x {esya}")
        return ", ".join(p) or self.tt("takas_bos")

    def metin(self):
        return self.tt("takas_teklif", a=self.a.mention, b=self.b.mention,
                       ver=self.ozet(self.ver, self.esya, self.adet), al=self.ozet(self.al))

    def kapat(self):
        self.bitti = True
        TAKAS_AKTIF.discard(self.a.id)
        TAKAS_AKTIF.discard(self.b.id)
        self.stop()

    @discord.ui.button(label="Kabul / Accept", emoji="✅", style=discord.ButtonStyle.success)
    async def kabul(self, i, b):
        if i.user.id != self.b.id:
            return await i.response.send_message(self.tt("takas_sadece_hedef"), ephemeral=True)
        if self.bitti:
            return
        self.kapat()
        sebep = self.uygula()
        if sebep:
            return await i.response.edit_message(content=self.tt("takas_hata", sebep=sebep), view=None)
        await i.response.edit_message(content=self.tt("takas_ok") + "\n" + self.metin().split("\n\n")[1], view=None)

    @discord.ui.button(label="Reddet / Decline", emoji="❌", style=discord.ButtonStyle.danger)
    async def red(self, i, b):
        if i.user.id not in (self.a.id, self.b.id):
            return await i.response.send_message(self.tt("takas_sadece_hedef"), ephemeral=True)
        self.kapat()
        await i.response.edit_message(content=self.tt("takas_red"), view=None)

    async def on_timeout(self):
        if not self.bitti:
            self.kapat()
            try:
                await self.msg.edit(content=self.tt("takas_sure"), view=None)
            except (discord.HTTPException, AttributeError):
                pass

    def uygula(self):
        """Her şeyi yeniden doğrular, sonra tek seferde uygular. Hata sebebini döner, başarılıysa None."""
        v22 = sys.modules.get("v22")
        if self.ver and cuzdan(self.a.id) < self.ver:
            return self.tt("takas_para_yok", k=self.a.display_name)
        if self.al and cuzdan(self.b.id) < self.al:
            return self.tt("takas_para_yok", k=self.b.display_name)
        ea = None
        if self.esya:
            if v22 is None:
                return "v22 yok"
            ea = v22.env(self.ctx.guild.id, self.a.id)["esya"]
            ad = esya_bul(ea, self.esya)
            if ad is None or ea.get(ad, 0) < self.adet:
                return self.tt("takas_esya_yok", k=self.a.display_name)
            self.esya = ad
        if self.ver:
            para_ekle(self.a.id, -self.ver)
            para_ekle(self.b.id, self.ver)
        if self.al:
            para_ekle(self.b.id, -self.al)
            para_ekle(self.a.id, self.al)
        if self.esya:
            eb = v22.env(self.ctx.guild.id, self.b.id)["esya"]
            ea[self.esya] -= self.adet
            eb[self.esya] = eb.get(self.esya, 0) + self.adet
            try:
                v22.isaretle22()
            except Exception:
                pass
        return None


