# Rank kartı (PNG)
# ======================================================================
def _font(n):
    from PIL import ImageFont
    for yol in ("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", "/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf",
                "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf", "DejaVuSans-Bold.ttf", "arialbd.ttf"):
        try:
            return ImageFont.truetype(yol, n), True
        except OSError:
            continue
    try:
        return ImageFont.load_default(size=n), False
    except TypeError:
        return ImageFont.load_default(), False


def rank_png(ad, avatar_b, seviye, mevcut, gerekli, toplam, sira, mesaj):
    from PIL import Image, ImageDraw
    W, H = 720, 210
    im = Image.new("RGB", (W, H), (24, 26, 34))
    d = ImageDraw.Draw(im)
    for y in range(H):
        c = int(24 + y * 0.18)
        d.line((0, y, W, y), fill=(c, c + 4, c + 16))
    d.rounded_rectangle((8, 8, W - 8, H - 8), 18, outline=(25, 200, 45), width=3)
    buyuk, ttf = _font(34)
    orta, _ = _font(22)
    kucuk, _ = _font(17)
    if not ttf:
        ad = ad.translate(TR_ASCII)
    try:
        av = Image.open(io.BytesIO(avatar_b)).convert("RGB").resize((120, 120))
        maske = Image.new("L", (120, 120), 0)
        ImageDraw.Draw(maske).ellipse((0, 0, 119, 119), fill=255)
        im.paste(av, (34, 45), maske)
        d.ellipse((30, 41, 158, 169), outline=(254, 231, 92), width=3)
    except Exception:
        pass
    d.text((180, 28), ad[:20], font=buyuk, fill=(255, 255, 255))
    d.text((180, 74), f"Seviye {seviye}   |   Sira #{sira or '-'}", font=orta, fill=(254, 231, 92))
    oran = max(0.0, min(1.0, mevcut / gerekli if gerekli else 0))
    x0, x1, y0, y1 = 180, W - 36, 120, 146
    d.rounded_rectangle((x0, y0, x1, y1), 13, fill=(50, 54, 70))
    if oran > 0:
        d.rounded_rectangle((x0, y0, x0 + max(26, int((x1 - x0) * oran)), y1), 13, fill=(25, 200, 45))
    d.text((x0, 154), f"{para(mevcut)} / {para(gerekli)} XP", font=kucuk, fill=(195, 255, 200))
    d.text((x1 - 190, 154), f"Toplam {para(toplam)} XP  |  {para(mesaj)} mesaj", font=kucuk, fill=(200, 205, 220))
    cikti = io.BytesIO()
    im.save(cikti, "PNG")
    cikti.seek(0)
    return cikti


# ======================================================================
# Link yardımcıları
# ======================================================================
URL_RE = re.compile(r"(?:https?://|www\.)[^\s<>()\[\]]+|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|net|org|io|gg|me|tv|xyz|ru|info|co|link|ly|app|dev|tk|ml|ga|cf)\b(?:/[^\s<>()]*)?", re.I)
HER_ZAMAN = ("tenor.com", "giphy.com", "cdn.discordapp.com", "media.discordapp.net", "discord.com")
ALAN_RE = re.compile(r"^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$")


def host_cikar(url):
    if not re.match(r"^[a-z]+://", url, re.I):
        url = "http://" + url
    try:
        h = (urlparse(url).hostname or "").lower().rstrip(".")
    except ValueError:
        return ""
    return h[4:] if h.startswith("www.") else h


def alan_temizle(ham):
    ham = (ham or "").strip().lower()
    h = host_cikar(ham) if ("/" in ham or "://" in ham) else ham
    h = h[4:] if h.startswith("www.") else h
    return h if ALAN_RE.match(h) else None


def izinli_mi(host, alanlar):
    return any(host == a or host.endswith("." + a) for a in list(alanlar) + list(HER_ZAMAN))


def yasak_link_var_mi(metin, alanlar):
    for u in URL_RE.findall(metin or ""):
        h = host_cikar(u)
        if h and "." in h and not izinli_mi(h, alanlar):
            return h
    return None


def benzer_ad(a, b):
    a, b = a.lower().translate(TR_ASCII), b.lower().translate(TR_ASCII)
    a, b = re.sub(r"[^a-z0-9]", "", a), re.sub(r"[^a-z0-9]", "", b)
    return len(a) >= 4 and len(b) >= 4 and difflib.SequenceMatcher(None, a, b).ratio() >= 0.85


