class V38Cog(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.duzenlenen = {}      # kanal_id -> (yazar, eski, yeni, zaman)
        self.ihlal = {}           # (gid, uid, tetik) -> [zaman]
        self.son_kural = {}       # (gid, kural_id, uid) -> zaman
        self.katilimlar = {}      # gid -> [(zaman, uid, olusturma_ts)]
        self.ayrilanlar = {}      # gid -> [(ad, zaman)]

    async def cog_load(self):
        self.sezon_kontrol.start()
        self.kural_tarama.start()

    async def cog_unload(self):
        self.sezon_kontrol.cancel()
        self.kural_tarama.cancel()

    # ---------------- yardımcılar ----------------
    def tt(self, ctx, k, **kw):
        return t(ctx.guild.id if ctx.guild else None, ctx.author.id, k, **kw)

    async def bildir(self, guild, baslik, aciklama, renk, kanal_id=None):
        e = discord.Embed(title=baslik, description=aciklama[:3900], color=renk, timestamp=discord.utils.utcnow())
        kanal = guild.get_channel(kanal_id) if kanal_id else None
        if kanal is not None:
            try:
                return await kanal.send(embed=e)
            except discord.HTTPException:
                pass
        try:
            await m15().log(guild, baslik, aciklama, renk)
        except Exception:
            pass

    async def yonetici_kontrol(self, ctx):
        if not yonetici_mi(ctx.author):
            await ctx.send(self.tt(ctx, "yetki"))
            return False
        return True

    # ---------------- dil ----------------
    @commands.command(name="dil", aliases=["language", "lang", "dilsec"])
    async def dil(self, ctx, kod: str = None):
        """Kendi dilini ayarla: td!dil tr | az | en"""
        if kod is None or kod.lower() not in DIL_OK:
            return await ctx.send(self.tt(ctx, "dil_gecersiz"))
        depo.yaz(f"dil:{ctx.author.id}", kod.lower())
        await ctx.send(DIL_OK[kod.lower()])

    @commands.command(name="dilsunucu")
    async def dilsunucu(self, ctx, kod: str = None):
        """Sunucunun varsayılan dilini ayarla (yetkili): tr | az | en"""
        if not await self.yonetici_kontrol(ctx):
            return
        if kod is None or kod.lower() not in DIL_OK:
            return await ctx.send(self.tt(ctx, "dil_gecersiz"))
        ayar(ctx.guild.id)["dil"] = kod.lower()
        ayar_kaydet(ctx.guild.id)
        await ctx.send(DIL_SUNUCU_OK[kod.lower()])

    # ---------------- hatırlatmalar ----------------
    def kendi_hatirlatmalar(self, uid):
        liste = [k for k in G["hatirlatmalar"] if k.get("kullanici") == uid]
        return sorted(liste, key=lambda k: k["zaman"])

    @commands.command(name="hatirlatmalarim", aliases=["hatirlatmalar", "reminders"])
    async def hatirlatmalarim(self, ctx):
        """Aktif hatırlatmalarını listele"""
        liste = self.kendi_hatirlatmalar(ctx.author.id)
        if not liste:
            return await ctx.send(self.tt(ctx, "hatir_yok"))
        satir = [f"**{i}.** <t:{int(k['zaman'])}:R> — {str(k['mesaj'])[:80]}" for i, k in enumerate(liste[:15], 1)]
        e = discord.Embed(title=self.tt(ctx, "hatir_baslik"), description="\n".join(satir), color=discord.Color.green())
        await ctx.send(embed=e, allowed_mentions=NO_PING)

