    @commands.command(name="blackjack", aliases=["bj"])
    async def blackjack(self, ctx, bahis: str):
        """Blackjack: td!blackjack <bahis>"""
        if not OYUN_LIMIT.dene(ctx.author.id):
            return
        if ctx.author.id in AKTIF_OYUN:
            return await ctx.send(self.tt(ctx, "oyun_var"))
        b, hata = bahis_oku(lambda k, **kw: self.tt(ctx, k, **kw), ctx, bahis)
        if hata:
            return await ctx.send(hata)
        AKTIF_OYUN.add(ctx.author.id)
        para_ekle(ctx.author.id, -b)
        v = BJ(ctx, b)
        if puan(v.oyuncu) == 21:
            AKTIF_OYUN.discard(ctx.author.id)
            v.bitti = True
            if puan(v.krupiye) == 21:
                para_ekle(ctx.author.id, b)
                son, renk = self.tt(ctx, "bj_bera"), discord.Color.light_grey()
            else:
                para_ekle(ctx.author.id, int(b * 2.5))
                son, renk = self.tt(ctx, "bj_blackjack", n=para(int(b * 1.5))), discord.Color.gold()
            return await ctx.send(embed=v.embed(son=son, renk=renk))
        v.msg = await ctx.send(embed=v.embed(), view=v)

    @commands.command(name="rulet", aliases=["roulette"])
    async def rulet(self, ctx, bahis: str, secim: str):
        """Rulet: td!rulet <bahis> <kirmizi|siyah|tek|cift|0-36>"""
        if not OYUN_LIMIT.dene(ctx.author.id):
            return
        s = secim.lower().translate(TR_ASCII)
        s = {"red": "kirmizi", "black": "siyah", "odd": "tek", "even": "cift", "green": "0", "yesil": "0"}.get(s, s)
        if not (s in ("kirmizi", "siyah", "tek", "cift") or (s.isdigit() and 0 <= int(s) <= 36)):
            return await ctx.send(self.tt(ctx, "rulet_secim"))
        b, hata = bahis_oku(lambda k, **kw: self.tt(ctx, k, **kw), ctx, bahis)
        if hata:
            return await ctx.send(hata)
        para_ekle(ctx.author.id, -b)
        sayi = random.randint(0, 36)
        renk = rulet_renk(sayi)
        if s.isdigit():
            kazanc = b * 36 if int(s) == sayi else 0
        elif s in ("kirmizi", "siyah"):
            kazanc = b * 2 if renk == s else 0
        else:
            kazanc = b * 2 if sayi != 0 and (sayi % 2 == (1 if s == "tek" else 0)) else 0
        if kazanc:
            para_ekle(ctx.author.id, kazanc)
        msg = await ctx.send("🎡 ⚪ ...")
        await asyncio.sleep(1.2)
        sonuc = self.tt(ctx, "rulet_sonuc", sayi=sayi, renk=self.tt(ctx, renk))
        son = self.tt(ctx, "kazandin", n=para(kazanc - b)) if kazanc else self.tt(ctx, "kaybettin", n=para(b))
        await msg.edit(content=f"{sonuc}\n{son}")

    @commands.command(name="cark", aliases=["wheel"])
    async def cark(self, ctx, bahis: str):
        """Şans çarkı: td!cark <bahis>"""
        if not OYUN_LIMIT.dene(ctx.author.id):
            return
        b, hata = bahis_oku(lambda k, **kw: self.tt(ctx, k, **kw), ctx, bahis)
        if hata:
            return await ctx.send(hata)
        para_ekle(ctx.author.id, -b)
        ad, carpan, _ = random.choices(CARK, weights=[w for _, _, w in CARK])[0]
        geri = int(b * carpan)
        if geri:
            para_ekle(ctx.author.id, geri)
        msg = await ctx.send(f"{self.tt(ctx, 'cark_baslik')}\n🌀 ...")
        await asyncio.sleep(1.2)
        fark = geri - b
        son = self.tt(ctx, "kazandin", n=para(fark)) if fark > 0 else (
            self.tt(ctx, "kaybettin", n=para(-fark)) if fark < 0 else "🤝 ±0")
        await msg.edit(content=f"{self.tt(ctx, 'cark_baslik')}\n**{ad}**\n{son}")

