    @commands.command(name="takas", aliases=["trade"])
    async def takas(self, ctx, hedef: discord.Member = None, ver: int = 0, al: int = 0, esya: str = None, adet: int = 1):
        """Takas: td!takas @kişi <verdiğin🪙> <istediğin🪙> [eşya] [adet]"""
        if hedef is None or ver < 0 or al < 0 or adet < 1 or (ver == 0 and al == 0 and not esya):
            return await ctx.send(self.tt(ctx, "takas_arg"))
        if hedef.id == ctx.author.id or hedef.bot:
            return await ctx.send(self.tt(ctx, "takas_kendi"))
        if ctx.author.id in TAKAS_AKTIF or hedef.id in TAKAS_AKTIF:
            return await ctx.send(self.tt(ctx, "takas_var"))
        if ver and cuzdan(ctx.author.id) < ver:
            return await ctx.send(self.tt(ctx, "yetersiz", bak=para(cuzdan(ctx.author.id))))
        if esya:
            v22 = sys.modules.get("v22")
            ea = v22.env(ctx.guild.id, ctx.author.id)["esya"] if v22 else {}
            ad = esya_bul(ea, esya)
            if ad is None or ea.get(ad, 0) < adet:
                return await ctx.send(self.tt(ctx, "takas_esya_yok", k=ctx.author.display_name))
            esya = ad
        TAKAS_AKTIF.update((ctx.author.id, hedef.id))
        v = TakasView(ctx, hedef, ver, al, esya, adet)
        v.msg = await ctx.send(v.metin(), view=v, allowed_mentions=discord.AllowedMentions(users=[hedef]))

    # ---------------- sezon ----------------
    @staticmethod
    def sezon_anahtar():
        return datetime.datetime.now(TZ).strftime("%Y-%m")

    def xp_anlik(self, gid):
        return {u: int(k[0]) for u, k in m15().veri["xp"].get(str(gid), {}).items()}

    def sezon_siralama(self, gid, snap):
        anlik = self.xp_anlik(gid)
        fark = {u: x - snap.get(u, 0) for u, x in anlik.items() if x - snap.get(u, 0) > 0}
        return sorted(fark.items(), key=lambda x: -x[1])

    @commands.command(name="sezon", aliases=["season"])
    async def sezon(self, ctx):
        """Bu ayın XP sıralaması"""
        s = ayar(ctx.guild.id)["sezon"]
        kayit = depo.al(f"sezon:{ctx.guild.id}", None)
        if not s["acik"] or not kayit:
            return await ctx.send(self.tt(ctx, "sezon_kapali"))
        sira = self.sezon_siralama(ctx.guild.id, kayit["snap"])[:10]
        if not sira:
            return await ctx.send(self.tt(ctx, "sezon_bos"))
        madalya = {1: "🥇", 2: "🥈", 3: "🥉"}
        satir = [f"{madalya.get(i, f'**{i}.**')} <@{u}> — {para(x)} XP" for i, (u, x) in enumerate(sira, 1)]
        e = discord.Embed(title=self.tt(ctx, "sezon_baslik", ay=kayit["ay"]), description="\n".join(satir), color=discord.Color.gold())
        await ctx.send(embed=e, allowed_mentions=NO_PING)

    @commands.command(name="sezonayar")
    async def sezonayar(self, ctx, islem: str = "", *degerler: str):
        """td!sezonayar ac|kapat | odul <1.> <2.> <3.> | rol @rol | kanal #kanal"""
        if not await self.yonetici_kontrol(ctx):
            return
        s = ayar(ctx.guild.id)["sezon"]
        islem = islem.lower()
        if islem == "ac":
            s["acik"] = True
            depo.yaz(f"sezon:{ctx.guild.id}", {"ay": self.sezon_anahtar(), "snap": self.xp_anlik(ctx.guild.id)})
        elif islem == "kapat":
            s["acik"] = False
        elif islem == "odul" and len(degerler) == 3 and all(d.isdigit() for d in degerler):
            s["odul"] = [min(int(d), 10_000_000) for d in degerler]
        elif islem == "rol" and ctx.message.role_mentions:
            s["rol"] = ctx.message.role_mentions[0].id
        elif islem == "kanal" and ctx.message.channel_mentions:
            s["kanal"] = ctx.message.channel_mentions[0].id
        else:
            return await ctx.send("`td!sezonayar ac|kapat` • `odul <1.> <2.> <3.>` • `rol @rol` • `kanal #kanal`")
        ayar_kaydet(ctx.guild.id)
        await ctx.send(self.tt(ctx, "sezon_ok"))

    async def sezon_bitir(self, guild, kayit):
        s = ayar(guild.id)["sezon"]
        sira = self.sezon_siralama(guild.id, kayit["snap"])[:3]
        satir = []
        rol = guild.get_role(s["rol"]) if s.get("rol") else None
        for i, (uid, xp) in enumerate(sira):
            odul = s["odul"][i] if i < len(s["odul"]) else 0
            if odul:
                para_ekle(int(uid), odul)
            satir.append(f"{['🥇', '🥈', '🥉'][i]} <@{uid}> — {para(xp)} XP (+{para(odul)} 🪙)")
        if rol is not None:
            try:
                for uye in list(rol.members):
                    await uye.remove_roles(rol, reason="Sezon bitti")
                if sira:
                    kazanan = guild.get_member(int(sira[0][0]))
                    if kazanan:
                        await kazanan.add_roles(rol, reason="Sezon birincisi")
            except discord.HTTPException:
                pass
        dil = ayar(guild.id).get("dil", "tr")
        if satir:
            await self.bildir(guild, M.get(dil, M["tr"])["sezon_bitti"].format(ay=kayit["ay"]), "\n".join(satir), discord.Color.gold(), s.get("kanal"))

    @tasks.loop(minutes=30)
    async def sezon_kontrol(self):
        for g in list(self.bot.guilds):
            try:
                s = ayar(g.id)["sezon"]
                if not s["acik"]:
                    continue
                kayit = depo.al(f"sezon:{g.id}", None)
                simdi = self.sezon_anahtar()
                if kayit is None:
                    depo.yaz(f"sezon:{g.id}", {"ay": simdi, "snap": self.xp_anlik(g.id)})
                elif kayit["ay"] != simdi:
                    await self.sezon_bitir(g, kayit)
                    depo.yaz(f"sezon:{g.id}", {"ay": simdi, "snap": self.xp_anlik(g.id)})
            except Exception as ex:
                print(f"v38 sezon hatası: {ex!r}")

    @sezon_kontrol.before_loop
    async def _sezon_bekle(self):
        await self.bot.wait_until_ready()

