    @commands.Cog.listener()
    async def on_member_join(self, uye):
        if uye.bot:
            return
        g = uye.guild
        cfg = ayar(g.id)
        dil = cfg.get("dil", "tr")
        yas_gun = (discord.utils.utcnow() - uye.created_at).total_seconds() / 86400
        # --- yeni hesap filtresi ---
        a = cfg["yeni_hesap"]
        if a["acik"] and yas_gun < a["gun"] and uye.id not in a["muaf"]:
            eylem = a["eylem"]
            sonuc = "uyar"
            try:
                if eylem == "kick":
                    try:
                        await uye.send(M.get(dil, M["tr"])["yeni_hesap_dm"].format(gun=a["gun"]))
                    except discord.HTTPException:
                        pass
                    await uye.kick(reason="Yeni hesap filtresi")
                    sonuc = "kick"
                elif eylem == "timeout":
                    kalan = min(28.0, max(0.1, a["gun"] - yas_gun))
                    await uye.timeout(datetime.timedelta(days=kalan), reason="Yeni hesap filtresi")
                    sonuc = "timeout"
            except discord.HTTPException:
                sonuc = "uyar (yetki yok)"
            await self.bildir(g, M.get(dil, M["tr"])["yeni_hesap_log"].format(uye=str(uye)),
                              f"{uye.mention}\nHesap yaşı: **{yas_gun:.1f}** gün\nEylem: **{sonuc}**", discord.Color.orange())
        # --- alt hesap şüphesi ---
        alt = cfg["alt"]
        if alt["acik"]:
            await self.alt_kontrol(uye, yas_gun, alt, dil)

