    @commands.command(name="altuyari")
    async def altuyari(self, ctx, islem: str = ""):
        """td!altuyari ac [#kanal] | kapat | esik <1-6>"""
        if not await self.yonetici_kontrol(ctx):
            return
        a = ayar(ctx.guild.id)["alt"]
        islem = islem.lower()
        if islem == "ac":
            a["acik"] = True
            if ctx.message.channel_mentions:
                a["kanal"] = ctx.message.channel_mentions[0].id
        elif islem == "kapat":
            a["acik"] = False
        elif islem == "esik":
            sayi = [x for x in ctx.message.content.split() if x.isdigit()]
            if not sayi or not 1 <= int(sayi[-1]) <= 6:
                return await ctx.send("`td!altuyari esik <1-6>`")
            a["esik"] = int(sayi[-1])
        else:
            return await ctx.send(f"{'✅' if a['acik'] else '❌'} eşik {a['esik']}\n`td!altuyari ac [#kanal]` • `kapat` • `esik <1-6>`")
        ayar_kaydet(ctx.guild.id)
        await ctx.send(self.tt(ctx, "ayar_ok"))

    async def alt_kontrol(self, uye, yas_gun, alt, dil):
        g, simdi = uye.guild, time.time()
        puan_, sebepler = 0, []
        if yas_gun < 3:
            puan_ += 2
            sebepler.append(f"hesap {yas_gun:.1f} günlük")
        elif yas_gun < 14:
            puan_ += 1
            sebepler.append(f"hesap {yas_gun:.0f} günlük")
        if uye.avatar is None:
            puan_ += 1
            sebepler.append("varsayılan avatar")
        liste = [x for x in self.katilimlar.get(g.id, []) if simdi - x[0] < 120]
        genc = [x for x in liste if x[2] < 14]
        if yas_gun < 14 and len(genc) >= 2:
            puan_ += 2
            sebepler.append(f"2 dk içinde {len(genc)} genç hesap daha katıldı")
        liste.append((simdi, uye.id, yas_gun))
        self.katilimlar[g.id] = liste[-50:]
        for ad, z in self.ayrilanlar.get(g.id, []):
            if simdi - z < 7 * 86400 and (ad == uye.name or benzer_ad(ad, uye.name)):
                puan_ += 2
                sebepler.append(f"adı son 7 günde ayrılan **{ad}** ile benzer")
                break
        if puan_ >= alt["esik"]:
            await self.bildir(g, M.get(dil, M["tr"])["alt_baslik"],
                              f"{uye.mention} ({uye})\nPuan: **{puan_}** / eşik {alt['esik']}\n• " + "\n• ".join(sebepler),
                              discord.Color.orange(), alt.get("kanal"))

