    async def link_kontrol(self, msg):
        if msg.guild is None or msg.author.bot or not isinstance(msg.author, discord.Member):
            return False
        a = ayar(msg.guild.id)["link"]
        if not a["acik"]:
            return False
        p = msg.author.guild_permissions
        if p.administrator or p.manage_messages or p.manage_guild:
            return False
        if not yasak_link_var_mi(msg.content, a["alanlar"]):
            return False
        try:
            m15().otomod_silinen.add(msg.id)
        except Exception:
            pass
        try:
            await msg.delete()
        except discord.HTTPException:
            return False
        try:
            await msg.channel.send(t(msg.guild.id, msg.author.id, "link_silindi", uye=msg.author.mention),
                                   delete_after=8, allowed_mentions=discord.AllowedMentions(users=[msg.author]))
        except discord.HTTPException:
            pass
        await self.ihlal_kaydet(msg.author, "link")
        return True

