    @commands.command(name="otokural")
    async def otokural(self, ctx, islem: str = "liste", *arg: str):
        """td!otokural ekle <uyari|kufur|link> <adet> <pencere_dk> <timeout|kick|ban|uyar> [sure_dk] | liste | sil <no>"""
        kurallar = ayar(ctx.guild.id)["kurallar"]
        islem = islem.lower()
        if islem == "liste":
            if not kurallar:
                return await ctx.send(self.tt(ctx, "kural_yok"))
            satir = [f"**{i}.** {k['tetik']} ≥ {k['adet']} / {k['pencere']} dk → **{k['eylem']}**" + (f" ({k['sure']} dk)" if k["eylem"] == "timeout" else "")
                     for i, k in enumerate(kurallar, 1)]
            return await ctx.send("📏\n" + "\n".join(satir))
        if not await self.yonetici_kontrol(ctx):
            return
        if islem == "sil" and arg and arg[0].isdigit() and 1 <= int(arg[0]) <= len(kurallar):
            kurallar.pop(int(arg[0]) - 1)
            ayar_kaydet(ctx.guild.id)
            return await ctx.send(self.tt(ctx, "kural_sil_ok", n=arg[0]))
        if islem == "ekle":
            if len(arg) < 4 or arg[0] not in ("uyari", "kufur", "link") or not arg[1].isdigit() or not arg[2].isdigit() \
                    or arg[3] not in ("timeout", "kick", "ban", "uyar"):
                return await ctx.send(self.tt(ctx, "kural_arg"))
            if len(kurallar) >= 10:
                return await ctx.send(self.tt(ctx, "kural_limit"))
            adet, pencere = max(1, min(int(arg[1]), 50)), max(1, min(int(arg[2]), 1440))
            sure = int(arg[4]) if len(arg) > 4 and arg[4].isdigit() else 60
            kurallar.append({"id": secrets.token_hex(3), "tetik": arg[0], "adet": adet, "pencere": pencere,
                             "eylem": arg[3], "sure": max(1, min(sure, 40320))})
            ayar_kaydet(ctx.guild.id)
            return await ctx.send(self.tt(ctx, "kural_ekle_ok", n=len(kurallar)))
        await ctx.send(self.tt(ctx, "kural_arg"))

    async def ihlal_kaydet(self, uye, tetik):
        if not ayar(uye.guild.id)["kurallar"]:
            return
        anahtar = (uye.guild.id, uye.id, tetik)
        self.ihlal.setdefault(anahtar, []).append(time.time())
        self.ihlal[anahtar] = self.ihlal[anahtar][-60:]
        await self.kural_degerlendir(uye.guild, uye, tetik)

    def ihlal_say(self, gid, uid, tetik, saniye):
        simdi = time.time()
        if tetik == "uyari":
            return sum(1 for x in G["uyarilar"].get(gid, {}).get(uid, []) if simdi - x[2] < saniye)
        return sum(1 for z in self.ihlal.get((gid, uid, tetik), []) if simdi - z < saniye)

    async def kural_degerlendir(self, guild, uye, tetik):
        for k in ayar(guild.id)["kurallar"]:
            if k["tetik"] != tetik:
                continue
            n = self.ihlal_say(guild.id, uye.id, tetik, k["pencere"] * 60)
            if n < k["adet"]:
                continue
            anahtar = (guild.id, k["id"], uye.id)
            if time.time() - self.son_kural.get(anahtar, 0) < k["pencere"] * 60:
                continue
            self.son_kural[anahtar] = time.time()
            await self.kural_uygula(guild, uye, k, n)

    async def kural_uygula(self, guild, uye, k, n):
        dil = ayar(guild.id).get("dil", "tr")
        eylem, sonuc = k["eylem"], "uyar"
        guvenli = (uye.id != guild.owner_id and not uye.guild_permissions.administrator
                   and uye.top_role < guild.me.top_role)
        if eylem != "uyar" and guvenli:
            try:
                if eylem == "timeout":
                    await uye.timeout(datetime.timedelta(minutes=k["sure"]), reason=f"Otomod kuralı {k['id']}")
                elif eylem == "kick":
                    await uye.kick(reason=f"Otomod kuralı {k['id']}")
                elif eylem == "ban":
                    await uye.ban(reason=f"Otomod kuralı {k['id']}", delete_message_days=0)
                sonuc = eylem
            except discord.HTTPException:
                sonuc = "uyar (yetki yok)"
        await self.bildir(guild, "📏 Otomod", M.get(dil, M["tr"])["kural_log"].format(no=k["id"], uye=str(uye), n=n, dk=k["pencere"], eylem=sonuc),
                          discord.Color.red())

    @tasks.loop(seconds=20)
    async def kural_tarama(self):
        """Uyarı sayısına göre kurallar: `td!warn` ile verilen uyarıları izler."""
        for g in list(self.bot.guilds):
            try:
                kurallar = [k for k in ayar(g.id)["kurallar"] if k["tetik"] == "uyari"]
                if not kurallar:
                    continue
                for uid in list(G["uyarilar"].get(g.id, {})):
                    uye = g.get_member(uid)
                    if uye is not None:
                        await self.kural_degerlendir(g, uye, "uyari")
            except Exception as ex:
                print(f"v38 kural tarama hatası: {ex!r}")

    @kural_tarama.before_loop
    async def _tarama_bekle(self):
        await self.bot.wait_until_ready()

    @commands.Cog.listener()
    async def on_message(self, msg):
        if msg.guild is None or msg.author.bot:
            return
        await self.link_kontrol(msg)
        if any(k["tetik"] == "kufur" for k in ayar(msg.guild.id)["kurallar"]):
            try:
                v = m15()
                if v.kufur_var_mi(msg.content or "", v.sunucu_ayar(msg.guild.id)["kufur_ekstra"]):
                    await self.ihlal_kaydet(msg.author, "kufur")
            except Exception:
                pass


